quests[9381] = { id = 9381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treffsichere Pfeile", description = "Mit dem Zustrom von Pilgern und dem Vordringen der Allianz, war die Falkenwacht in letzter Zeit ein sehr geschäftiger Ort. In meiner freien Zeit stelle ich normalerweise Pfeile für die Waldläufer her. Leider habe ich schon lange keine Zeit mehr dazu gehabt, die für die Pfeilherstellung notwendigen Federn zu beschaffen.\n\nEs wäre mir ein paar Münzen wert, wenn Ihr die Schwanzfedern von Knochenhäutern für mich einsammeln würdet. In der Vergangenheit habe ich diese Geier oft über den Knochen verendeter Kreaturen, nördlich der Falkenwacht, ausfindig gemacht.", sourceObjective = "Sammelt 8 Schwanzfedern eines Knochenhäuters von den Knochenhäutergeiern und bringt sie Falknerin Drenna Flusswind in der Falkenwacht.", progress = "Habt Ihr alle Federn beisammen?", completion = "Die sollten ihren Zweck erfüllen. Ich hatte schon befürchtet, dass den Waldläufern bald die Pfeile ausgehen, doch nun muss ich mir darüber erstmal keine Sorgen mehr machen. Vielen Dank für Eure Hilfe, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9382] = { id = 9382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal der Grollhufe", description = "Grüße, {class}.\n\nIch bin sicher, dass Ihr auf Euren Reisen etwas von der Verderbtheit dieser Welt mitbekommen habt. Sie ist so allgegenwärtig, dass sie sogar die einheimischen Tiere verändert hat. Natürlich nur die, die sie überlebt haben.\n\nDie Grollhufe im Süden und Westen waren einst friedliche Weidentiere, aber die Verderbtheit hat sie mit einer unstillbaren Wut erfüllt. Der einzige Ausweg aus dieser Qual ist der Tod, auch wenn wir nur ungern ihr Blut vergießen. Helft Ihr mir dabei, das Leiden der borstigen Grollhufe zu beenden?", sourceObjective = "Tötet 15 borstige Grollhufe und kehrt dann zu Amaan dem Weisen im Tempel von Telhamat zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9383] = { id = 9383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gewagter Plan", description = "Die Blutelfen verkörpern den völlig unverantwortlichen Umgang mit den Mächten der Magie, {class}. Sie kontrollieren die Magie nicht, nein, vielmehr sind sie ihre Sklaven und sie werden niemanden zwischen ihre Abhängigkeit und die magischen Energien kommen lassen, nach denen es ihnen dürstet. Die Blutelfen nutzen die Energien der Scherbenweltleerwandler, um ihre dämonische Magie zu wirken.\n\nIch habe einen Kristall mit einem Zauber aufgeladen, der es uns ermöglichen wird, einen Leerwandler zu neutralisieren und das magische Band zwischen ihm und dieser Welt zu zerschneiden. Ich habe die Leerwandler hauptsächlich in den Sphärenfeldern und südöstlich der Höllenfeuerzitadelle gesehen.", sourceObjective = "Wendet den geweihten Kristall auf einen verwundeten unkontrollierten Leerwandler an. Kehrt anschließend zu Elsaana beim Tempel von Telhamat zurück.", progress = "Habt Ihr die Magie des Kristalls gegen einen unkontrollierten Leerwandler eingesetzt?", completion = "Ihr habt Euch bewährt, {name}. Es scheint, als würde der Verwahrungskristall fürs Erste standhalten, allerdings weiß niemand wie lange. Wir werden ihn im Auge behalten und in der Zwischenzeit noch mehr Kristalle vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9384] = { id = 9384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nutzt das Licht", description = "Die Zeit ist gekommen, diesen Dämon zu vernichten. Ich empfehle Euch vorsichtig zu sein, {name}, denn es gibt noch vieles, dass Ihr noch nicht über die Leerwandler der Scherbenwelt wisst.\n\nBringt Rumatu dieses Gefäß, damit er sich um dessen Zerstörung kümmern kann. Beobachtet den Vorgang genau und berichtet mir, sobald der Prozess abgeschlossen ist.", sourceObjective = "Bringt den leuchtenden geweihten Kristall zu Rumatu beim Tempel von Sha'naar, damit er den darin eingeschlossenen Dämon mit den Kräften des Lichts zerschlagen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[9385] = { id = 9385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tobende Felshetzer", description = "Also schickt uns die Ehrenfeste hierher, um mit den Arakkoa fertigzuwerden, und wir bauen unser Lager auf und denken uns hey, schön hier. Wir hatten ja keine Ahnung, dass wir so nahe bei den Stachelklauenfelshetzern sind.\n\nSie sind erbarmungslose Raubtiere und haben jegliche Arbeit unsererseits zunichtegemacht. Wenn Ihr Euch darum kümmert, würde ich Euch bezahlen. Habt Ihr Lust?", sourceObjective = "Tötet 10 Stachelklauenfelshetzer und kehrt anschließend zu Gremni Langbart auf der Höllenfeuerhalbinsel zurück.", completion = "Gut gemacht, {name}. Das wird den Biestern zeigen, wer hier der Boss ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[9386] = { id = 9386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Licht im Dunkeln", description = "Ihr seid ziemlich eifrig, oder? Solltet Ihr Euch noch einmal in die Tiefen wagen, so bin ich gerne bereit, Euch dafür zu belohnen.\n\nSucht die Freudenfeuer in Stratholme, Scholomance, dem Düsterbruch und den Hallen der Schwarzfelsspitze auf. Ich erwarte Eure Rückkehr, {name}.", sourceObjective = "Findet und berührt die Freudenfeuer innerhalb der Schwarzfelsspitze, dem Düsterbruch, Scholomance und Stratholme. Sprecht dann mit dem Flammenbewahrer.", sourceObjectiveStatus = "unverified-source-field" }
quests[9387] = { id = 9387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Quelle der Verderbtheit", description = "Unverderbte Draenei, wie dieser unglückliche Geselle hier, sind begabte Helden des Lichts. Welche Verderbtheit hat wohl ihr großartiges Volk dazu gebracht, sich zu Zerschlagenen und Verirrten zurückzuentwickeln?\n\nMir ist eine Theorie zu Ohren gekommen, die besagt, dass die Mutation von teuflischen Energien ausgelöst wurde. Ich würde diese Theorie gerne überprüfen.\n\nNordwestlich von hier findet Ihr die Ruinen von Sha'naar. Dort befinden sich einige einfache Zerschlagene unter dem Befehl der Zuchtmeister der Illidari. Bringt mir die dämonischen Essenzen der Zuchtmeister, damit ich sie an diesem Draenei ausprobieren kann.", sourceObjective = "Reist zu den Ruinen von Sha'naar auf der Höllenfeuerhalbinsel und besorgt 5 dämonische Essenzen von den Zuchtmeistern der Illidari. Kehrt zu Apotheker Azethen in der Falkenwacht zurück, wenn Ihr die Aufgabe erfüllt habt.", progress = "Habt Ihr die Proben bekommen?", completion = "Ihr wart mir eine große Hilfe, {name}. Nun wollen wir sehen, was wir von unserem blauen Freund lernen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[9388] = { id = 9388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lodernde Flammen in Kalimdor", description = "Heute lodern zahlreiche Flammen in der Welt, {name}. Die Feuer, die am schwierigsten zu unterhalten sind, leuchten grün; werden sie nicht ständig beaufsichtigt, brennen sie nicht lange. Versichert Euch für unseren Flammenbewahrer, dass die Smaragdfeuer in Kalimdor auch weiterhin lodern, eh?\n\nIhr findet sie in der Nähe von Ratschet im Brachland, unweit der Meistergleve an der Dunkelküste, im Wald des Eschentals bei der Brücke nahe des Außenpostens der Silberschwingen und entlang der Hauptstraße im Steinkrallengebirge, in der Nähe der Straße, die zur Scherwindklippe führt.", sourceObjective = "Sucht die Freudenfeuer im Eschental, im Brachland, an der Dunkelküste und im Steinkrallengebirge auf. Sprecht anschließend mit dem Flammenbewahrer.", sourceObjectiveStatus = "unverified-source-field" }
quests[9389] = { id = 9389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lodernde Flammen in den Östlichen Königreichen", description = "Die Feuer des Sonnenwendfests lassen das Land traditionsgemäß im Licht unzähliger Flammen erstrahlen. Manche behaupten, dass die grünen Flammen die besten seien, da sie so schwierig zu unterhalten sind und eine solch ungewöhnliche Farbgebung haben.\n\nVersichert Euch für unseren Flammenbewahrer, dass die Feuer in den Östlichen Königreichen auch weiterhin lodern. Ihr findet sie in der Nähe von Dun Modr im Sumpfland, unweit von Lohenscheit im Silberwald, bei den Klippen zum Leuchtturm in Westfall und nahe dem zerstörten Turm im Vorgebirge des Hügellands.", sourceObjective = "Sucht die Freudenfeuer im Vorgebirge des Hügellands, im Silberwald, in Westfall und dem Sumpfland auf. Sprecht anschließend mit dem Flammenbewahrer.", sourceObjectiveStatus = "unverified-source-field" }
quests[9390] = { id = 9390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach Sedai", description = "Hört mein Leid, {class}. Mein Bruder Sedai ist schon vor längerer Zeit losgezogen, um den Orcs beim Posten der Mag'har eine Botschaft zu übermitteln. Als ein unverbesserlicher Idealist war er der Meinung, dass der Zeitpunkt nun gekommen sei, unsere Differenzen beizulegen und einen Friedensvertrag mit ihnen auszuhandeln.\n\nEr wird jetzt schon seit Tagen vermisst und ich befürchte das Schlimmste.\n\nWürdet Ihr für mich nach ihm Ausschau halten, damit ich endlich wieder Ruhe finde? Sedai müsste sich irgendwo in der östlichen Umgebung aufhalten.", sourceObjective = "Anachoret Obadei möchte, dass Ihr östlich von hier auf der Höllenfeuerhalbinsel nach seinem Bruder Sedai Ausschau haltet.", completion = "Ihr habt den Leichnam eines jungen Paladins der Draenei gefunden. Es scheint, als hätte ihn jemand hinterrücks erschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9391] = { id = 9391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Weg kennzeichnen", description = "Nachdem die Felsklauenpopulation ausgedünnt ist, müssen wir die sichere Passage nur noch für unsere Pilger kenntlich machen. Nehmt diese Fackel und begebt Euch erneut in die Große Kluft. Sucht dort die drei Leuchtsignale, die den Verlauf des Pfads im Osten kennzeichnen.\n\nEntzündet die drei Signale und kehrt anschließend zu mir zurück. Doch seid gewarnt, das Entzünden eines Leuchtsignals zieht unweigerlich die Felsklauen aus der Umgebung an.", sourceObjective = "Waldläuferhauptmann Venn'ren an der Falkenwacht möchte, dass Ihr auf der Höllenfeuerhalbinsel die Große Kluft aufsucht und dort das südliche Leuchtsignal, westliche Leuchtsignal und das zentrale Leuchtsignal entzündet. Kehrt anschließend mit der brennenden Fackel zu ihm zurück.", progress = "Habt ihr getan, worum ich Euch gebeten habe, {name}?", completion = "Obwohl die Große Kluft noch immer ein gefährlicher Ort ist, gibt sie einen brauchbaren Pfad für unsere Pilger ab.\n\nEin derartiger Akt der Verzweiflung ist unvermeidlich, solange die Allianz weiterhin sämtliche ein- und ausgehenden Straßen zur Falkenwacht beobachtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[9392] = { id = 9392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung zum Schurken", description = "Während Ihr in Eurer Klasse weiter aufsteigt, werdet Ihr sicher die Ausbildung, die Euch der Lehrer Eurer Klasse anbietet, nutzen wollen. Der Lehrer für junge Schurken hier auf der Insel der Sonnenwanderer ist Pfadpirscher Kariel. Sprecht mit Kariel, um herauszufinden, welche Ausbildung er Euch anbieten kann. Die Ausbildung hat ihren Preis, bringt also ein paar Münzen mit Euch.\n\nKariel - wie alle anderen Lehrer auf der Insel der Sonnenwanderer auch - ist innerhalb des Sonnenturms, auf der unteren Ebene, anzutreffen.", sourceObjective = "Sprecht mit Pfadpirscher Kariel - dem Schurkenlehrer - innerhalb des Sonnenturms auf der Insel der Sonnenwanderer.", sourceObjectiveStatus = "unverified-source-field" }
quests[9393] = { id = 9393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung zum Jäger", description = "Während Ihr in Eurer Klasse weiter aufsteigt, werdet Ihr sicher die Ausbildung, die Euch der Lehrer Eurer Klasse anbietet, nutzen wollen. Die Lehrerin für junge Jäger hier auf der Insel der Sonnenwanderer ist Waldläuferin Sallina. Sprecht mit Sallina, um herauszufinden, welche Ausbildung sie Euch anbieten kann. Die Ausbildung hat ihren Preis, bringt also ein paar Münzen mit Euch.\n\nSallina - wie alle anderen Lehrer auf der Insel der Sonnenwanderer auch - ist innerhalb des Sonnenturms, auf der unteren Ebene, anzutreffen.", sourceObjective = "Sprecht mit Waldläuferin Sallina - der Jägerlehrerin - innerhalb des Sonnenturms auf der Insel der Sonnenwanderer.", sourceObjectiveStatus = "unverified-source-field" }
quests[9394] = { id = 9394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist Wyllithen?", description = "Der Nachtschimmergrundbewahrer ist verschwunden! Jemand muss vergessen haben, ihm zu sagen, dass er den Ort verlassen sollte, als der Magister und alle anderen es taten. Ich weiß, dass er sich noch irgendwo hier auf dem Grund aufhält, aber ich getraue mich nicht, selbst nach ihm zu sehen, da sich hier so viele magische Kreaturen herumtreiben.\n\nKönnt Ihr ihn für mich finden, {class}? Bitte seht nach, ob er in Ordnung ist.", sourceObjective = "Findet Grundbewahrer Wyllithen beim Nachtschimmergrund im Immersangwald.", completion = "Wer seid Ihr? Ihr seid keiner von den Lehrlingen des Magisters, das steht fest!\n\nMan hat Euch sicherlich hierher geschickt, um mir dabei zu helfen, wieder Ordnung in dieses Chaos zu bringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[9395] = { id = 9395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saltherils Hafen", description = "Ich schwöre, dass ich jemandem einen Feuerball verpasse, wenn Lord Saltheril mir auch nur noch eine Lieferanfrage für seine endlosen Feste schickt. Sehe ich verdammt nochmal wie ein Festtagsplaner aus?! Unter uns gesagt, dieser Verrückte und seine Bande von Speichelleckern scheinen bis heute zu verdrängen, dass wir unter ständiger Belagerung stehen!\n\nEinige von uns sind doch tatsächlich mit, äh, ich weiß nicht... der verdammten Verteidigung unseres Königreichs, Quel'Thalas, beschäftigt?! Würdet Ihr mir einen Gefallen tun, {class}? Seid doch so gut und reist für mich nach Saltherils Hafen und seht zu, dass er endlich Ruhe gibt! Es ist gleich die Straße runter, Richtung Westen.", sourceObjective = "Sprecht mit Lord Saltheril in Saltherils Hafen im Immersangwald.", completion = "Ah, Magistrix Morgenwandler hat zu guter Letzt doch noch auf meine simple Anfrage reagiert. Beizeiten werde ich ihr Benehmen mit dem Lordregenten erörtern. Sie ist eine recht ungehobelte Person!\n\nNichts, worüber Ihr Euch Sorgen machen müsstet. Nun, wo Ihr schon mal hier seid, besteht vielleicht die Möglichkeit, dass ich endlich meine Vorräte für das Fest bekomme, auf die ich schon so lange warte.", sourceObjectiveStatus = "unverified-source-field" }
quests[9396] = { id = 9396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Magie der Arakkoa", description = "Die Scherbenwelt birgt viele Geheimnisse, {name}. Es ist nur noch eine Frage der Zeit, bis wir sie alle enträtselt haben.\n\nDas Volk der halb Vogel, halb menschlichen Arakkoa verfügt über uraltes arkanes Wissen, welches sich als sehr nützlich für unsere Erforschung dieser Welt erweisen würde. Reist nach Süden zum Haal'eshbau. Nehmt alle magischen Rollen an Euch, die Ihr bei den Haal'eshi finden könnt und bringt sie mir.", sourceObjective = "Bringt 4 Rollen der Haal'eshi zu Arkanist Calesthris Morgenstern bei der Falkenwacht auf der Höllenfeuerhalbinsel.", progress = "Habt Ihr die Schriftrollen, {name}?", completion = "Gut gemacht, {name}. Die Geheimnisse der Scherbenwelt werden sich nicht lange vor uns verstecken können.\n\nEs ist unser Schicksal, die Meister dieser Welt zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9397] = { id = 9397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommt ein Vogel geflogen", description = "Die Arakkoa der Haal'eshi haben eine wunderschöne Vogelart, den Kaliri, domestiziert.\n\nMir ist es gelungen, ein junges Kalirimännchen einzufangen, und sie scheinen zähmbar zu sein. Die weiblichen Exemplare sind deutlich seltener, aber wenn es mir gelänge, eines davon zu ergattern, sollte ich in der Lage sein, sie selbst zu züchten. Es muss jedoch ein junges Weibchen sein, fast noch ein Küken. Ein alter Wildvogel würde die Gefangenschaft nicht lange überleben.\n\nNehmt diesen Käfig und reist nach Süden zum Haal'eshbau. Sucht nach Eiern, die kurz vor dem Schlüpfen stehen. Wenn Ihr mir ein junges Weibchen zurückbringt, werde ich Euch fürstlich belohnen.", sourceObjective = "Reist zum Haal'eshbau auf der Höllenfeuerhalbinsel und durchsucht die Kalirinester nach einem jungen Kaliriweibchen. Benutzt den leeren Vogelkäfig, um es zu fangen, und kehrt anschließend zu Falknerin Drenna Flusswind in der Falkenwacht zurück.", progress = "Ihr seid zurück. Habt Ihr mir ein Kaliriweibchen mitgebracht?", completion = "Ihr habt es geschafft! Ihr habt ein junges Weibchen gefangen!\n\nSie ist wundervoll. Vielen, vielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9398] = { id = 9398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tödliche Raubtiere", description = "Die Zerschlagenen in der Scherbenwelt haben unendlich viel Grausamkeit ertragen müssen. Kein Wunder, dass sie sofort nach der Öffnung des Dunklen Portals scharenweise in der Hoffnung, diesem Land entfliehen zu können, dorthin gepilgert sind.\n\nZum Pech für unsere verwirrten Brüder und Schwestern aus dem Süden sind sie für die Felsklauen, die in der Großen Kluft leben, eine leichte Beute. Geht dort hin und vernichtet einige der Felsklauen, damit unseresgleichen eine Chance hat.", sourceObjective = "Späher Vanura im Tempel von Telhamat auf der Höllenfeuerhalbinsel möchte, dass Ihr 8 Steinsichelwelpen und 4 Steinsichelalpha tötet.", completion = "Ihr habt gute Arbeit geleistet, {name}. Es ist immer schlimm, wenn Töten die einzige Möglichkeit ist, die bleibt, sogar wenn es sich um so gefährliche Biester wie die Steinsichelklauen handelt.\n\nIhr habt meinen Dank, dass Ihr diese grausame Aufgabe erledigt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9399] = { id = 9399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grausamkeit der Zuchtmeister", description = "Sicherlich glaubt auch Ihr, dass die meisten Zerschlagenen bösartig sind, nicht wahr? In Wahrheit mangelt es vielen nur an geistiger Führung.\n\nIch war ebenfalls verloren, bevor ich die Omenai getroffen habe.\n\nUnser Verstand litt sehr unter der dämonischen Magie der Orcs. Man kann uns leicht in die Irre führen und ausnutzen.\n\nDämonen, die mit Illidan verbündet sind, überfallen täglich die Höllenfeuerhalbinsel und verschleppen unseresgleichen als Sklaven. Doch mit den Omenai kam die Hoffnung. Reist zu den Ruinen von Sha'naar, südwestlich von hier, und tötet die Zuchtmeister der Illidari, damit mein Volk endlich wieder frei ist!", sourceObjective = "Reist zu den Ruinen von Sha'naar und erschlagt 4 Zuchtmeister der Illidari. Kehrt anschließend zu Ikan im Tempel von Telhamat auf der Höllenfeuerhalbinsel zurück.", completion = "Ihr habt es geschafft! Wir stehen tief in Eurer Schuld, {name}. Seht Euch nur all die Ankömmlinge des Lumpenpacks an.\n\nUnter meiner geistigen Führung werden sie alles über die alten Traditionen lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9400] = { id = 9400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Assassine", description = "{name}, wir haben erst kürzlich einen Plan zur Ermordung unseres Gesandten in der Falkenwacht aufgedeckt. Spione der Höllenfeuerzitadelle haben von unseren Plänen, eine Expedition zur Wacht auszusenden, erfahren und einen Hinterhalt vorbereitet.\n\nUnsere Späher berichteten mir, dass ein Assassine namens Krun Rückenbrecher auf der Straße nördlich der Zitadelle in Stellung gegangen ist. Begebt Euch dorthin und tötet diesen Assassinen. Macht den Höllenorcs klar, dass man mit uns keine Spielchen treibt.", sourceObjective = "Nazgrel möchte, dass Ihr zu der Straße nördlich der Höllenfeuerzitadelle reist und nach einem Assassinen namens Krun Rückenbrecher Ausschau haltet.", completion = "Der Leichnam stimmt mit der Beschreibung von Krun Rückenbrecher, dem Assassinen der Höllenfeuerzitadelle, überein. Als Ihr den noch warmen Körper umdreht, erblickt Ihr eine Steinaxt, die in seinem Rücken steckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9401] = { id = 9401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine seltsame Waffe", description = "Ihr zieht die Steinaxt aus dem toten Körper, um sie eingehender zu untersuchen. Irgendetwas an der Verarbeitung der Axt ist ungewöhnlich.\n\nSie scheint orcischen Ursprungs zu sein und dennoch besteht sie aus einem Material, das Ihr noch nie zuvor gesehen habt. Nazgrel wäre bestimmt daran interessiert, die Axt weiter zu untersuchen.", sourceObjective = "Bringt die schwere Steinaxt zu Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel.", progress = "Sagt mir, ist der Assassine tot?", completion = "Er wurde mit dieser Waffe getötet? Das ist unmöglich!\n\nHaben wir... haben wir sie tatsächlich gefunden?", sourceObjectiveStatus = "unverified-source-field" }
quests[9402] = { id = 9402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fangt!", description = "So... Ihr seid {name}, oder? Fühlt Euch nicht geschmeichelt, ich kenne Euren Namen, einer meiner Schüler ist bei Euch herumscharwenzelt und plappert ununterbrochen.\n\nHmm... wenn Ihr <ihn/sie> beeindrucken möchtet, warum helft Ihr mir dann nicht aus? Auf dem Grund des Stillwispertümpels hinter mir liegt eine Azurphiole. Taucht in die Tiefe, schnappt sie Euch und bringt sie zu mir.", sourceObjective = "Taucht auf den Grund des Stillwispertümpels und holt die Azurphiole für Instrukteur Antheol.", progress = "Wie ist das Wasser?", completion = "Oh, gut gemacht... ich sagte Ihr sollt in den Tümpel springen und Ihr habt es getan. Ich kann mir gut vorstellen, was Ihr tun würdet, wenn einer Eurer Freunde Euch um etwas bitten würde.\n\nWollt Ihr für Eure Mühe belohnt werden, dann ist es das: macht keinen Finger krumm, bevor Ihr nicht wisst, was dabei für Euch herausspringt. Der Geist des Magiers ist seine stärkste Waffe. Vergesst das nicht und versucht Euren ein wenig mehr anzustrengen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9403] = { id = 9403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das reinste Wasser", description = "Jetzt, da Ihr eine kleine Lektion gelernt habt, biete ich Euch etwas Handfesteres an. Es betrifft Eure Fähigkeiten der Selbstverteidigung. Ihr solltet natürlich nur im äußersten Notfall von Nahkampftechniken Gebrauch machen, aber deshalb sollte man trotzdem nicht unvorbereitet sein.\n\nIch kann Euch bei der Herstellung eines Stabs helfen, der einem Magier Eures Ranges gerecht wird. Nehmt die Phiole, die Ihr für mich besorgt habt, und füllt sie bei den Elrendarfällen auf. Folgt einfach dem Fluss südöstlich von hier.", sourceObjective = "Instrukteur Antheol möchte, dass Ihr die Azurphiole bei den Elrendarfällen auffüllt.", progress = "Nur das Wasser von den Elrendarfällen hat die erforderliche Reinheit für den Gebrauch von Magie. Habt Ihr es?", completion = "Mal sehen, was Ihr mir gebracht habt...\n\n<Er hält die Phiole gegen das Licht und studiert sie genau.>\n\nJa, das sollte es sein. Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9404] = { id = 9404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch lebendig", description = "Ihr habt vielleicht die wandelnden Bäume nahe der Elrendarfälle bemerkt. Als Behüter der Natur sind sie mit urzeitlicher Magie erfüllt, die wir mithilfe des reinem Wassers, das Ihr mir gebracht habt, umformen und für unsere Zwecke verwenden können.\n\nUnglücklicherweise sind die Waldbehüter knorrige und verdrehte Kreaturen, so dass Ihr womöglich erst einige töten müsst, bevor Ihr einen brauchbaren Zweig findet.", sourceObjective = "Tötet die Immersangwaldbehüter bis Ihr einen lebendigen Zweig für Instrukteur Antheol findet.", progress = "Habt Ihr den lebendigen Zweig? Schnell, gebt ihn mir!", completion = "Ihr seid meiner Bitte nachgekommen, {name}. Ihr könnt Eure Belohnung jetzt entgegennehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9405] = { id = 9405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Anliegen des Kriegshäuptlings", description = "Wie Ihr wisst, steht der Kriegshäuptling aus ganzer Kraft hinter dieser Expedition und das aus gutem Grund. Dies ist unsere Heimatwelt. Hier liegen unsere Wurzeln.\n\nDiese Reise hat für Orcs und Blutelfen gänzlich unterschiedliche Bedeutung. Für sie ist es die Suche nach dem gelobten Land. Für uns ist es die Rückkehr in unsere lange verlorene Heimat.\n\nWer auch immer diese Axt gefertigt hat, ist mit den alten Traditionen vertraut. Wir müssen Kontakt zu ihnen aufnehmen. Diese Angelegenheit ist zu wichtig, als dass wir reguläre Methoden des Aufspürens verwenden. Zeigt Scharfseherin Regulkut die Waffe; sie wird wissen, was zu tun ist.", sourceObjective = "Bringt die schwere Steinaxt zu Scharfseherin Regulkut in Thrallmar auf der Höllenfeuerhalbinsel.", progress = "Sagt mir, wonach Ihr sucht, damit ich Euch bei der Suche unterstützen kann.", completion = "Ich verstehe Nazgrels Anliegen, {class}. Sagt nichts weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[9406] = { id = 9406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Mag'har", description = "Diese Neuigkeiten, die Ihr von jenseits des Dunklen Portals bringt... Ihr wollt mir ernsthaft Glauben machen, dass der Sohn Durotans über die jenseitigen Länder geherrscht hat? Frei von dämonischem Einfluss? Und nun sind seine Leute in diese Welt zurückgekehrt?\n\nUm Euretwillen hoffe ich, dass das nicht irgendein perfider Witz sein soll, {class}. Es ist schwer zu beschreiben, was dies für mein Volk bedeutet. Ich werde umgehend eine Botschaft nach Nagrand schicken! Höllschrei muss davon erfahren.\n\nBringt diesen Brief zu Eurem Anführer in Thrallmar. Sagt ihm, die Mag'har heißen Euch willkommen!", sourceObjective = "Bringt den Brief von den Mag'har zu Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel.", progress = "Was habt Ihr für uns, {name}?", completion = "Seid Ihr sicher? Das sind große Neuigkeiten, {name}. Diese Orcs können sicherlich unserer Sache hier und auch zuhause dienlich sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[9407] = { id = 9407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Crusade: Durch das Dunkle Portal", description = "Viele Jahre stand das Dunkle Portal still... vergessen. Aber nun ist es nicht mehr still.\n\nNachdem der Angriff der Dämonen aufgehalten wurde, haben unsere Truppen das Portal durchschritten und sich den Dämonen auf ihrem eigenen Gebiet gestellt!\n\nNun sind wir in einem wilden Krieg gefangen, und einige sind der Meinung, dass wir ihn nicht gewinnen können. Es ist also unsere Pflicht und unser grausames Vergnügen, unsere Feinde in der Scherbenwelt zu bekämpfen und unseren Sieg zu sichern, {name}.\n\nWenn Ihr uns helfen wollt, meldet Euch unverzüglich bei Generalleutnant Orion. Er erwartet Euch in der Scherbenwelt...", sourceObjective = "Reist durch das Dunkle Portal und meldet Euch bei Generalleutnant Orion. Er erwartet Euch auf der anderen Seite - in der Scherbenwelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9408] = { id = 9408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergessene Helden", description = "Auch wenn es mich traurig macht, dass wir so viele Soldaten bei dem Versuch, das Portal zu durchbrechen, verloren haben, erfüllt es mich doch mit Stolz, dass das ursprüngliche Expeditionskorps noch am Leben ist.\n\nIch kann es kaum glauben, aber dort stehen sie - ein Zeichen für die Entschlossenheit der Allianz.\n\nIn dieser Festung steht einer unserer großartigsten Helden: Danath Trollbann! Geht zu ihm, {class}. Er hat schon all unsere Soldaten getroffen und mit ihnen gesprochen. Er möchte Euch sicher kennenlernen.", sourceObjective = "Sprecht mit Truppenkommandant Danath Trollbann in der Ehrenfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[9409] = { id = 9409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eilige Lieferung!", description = "Da Ihr jetzt alles besorgt habt, was zum Wiederaufladen der Heilkristalle benötigt wird, müsst Ihr die Phiolen zu unserem Priester Zalduun bringen. Er kümmert sich um die Verwundeten innerhalb der zentralen Kammer des Schiffes.", sourceObjective = "Bringt die Phiolensammlung zu Zalduun bei der Absturzstelle im Am'mental.", progress = "Hallo, {class}. Was habt Ihr da? Ist das für mich?", completion = "Gute Arbeit! Das wird die erschöpften Heilkristalle wieder aufladen.\n\nDa Ihr nun schon einmal hier seid... ich hätte da noch eine Aufgabe für Euch, solltet Ihr gewillt sein?", sourceObjectiveStatus = "unverified-source-field" }
quests[9410] = { id = 9410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirituelle Führung", description = "Selbst die Sinne unserer besten Spürwölfe können sich irren, {name}. Die Geister jedoch, haben eine andere Sicht auf diese Welt. Das Wesen, welches Ihr beschwören werdet, wird die von Euch gesuchte Person ausfindig machen, denn es spürt nicht dem Geruch des Gesuchten hinterher, sondern seiner Essenz.\n\nGeht jetzt, {class}, nehmt dieses Totem mit Euch und benutzt es an dem Ort, wo Ihr die Steinaxt gefunden habt.", sourceObjective = "Verwendet das Wolfstotem an dem Ort, wo Ihr Krun Rückenbrechers Leichnam gefunden habt und folgt dem Ahnengeistwolf.", progress = "Ihr könnt froh sein, dass Ihr noch lebt.", completion = "Wer seid Ihr, dass Ihr hier so einfach unangekündigt umherwandert? Ich habe meine Männer nur zurückgehalten, weil Ryga die Anwesenheit der Geister in Eurer Nähe verspürte.\n\nIhr könnt frei sprechen, doch wählt Eure Worte mit Bedacht. Wir vertrauen normalerweise keinen Fremden, die hier so nah bei der Zitadelle umherstreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9411] = { id = 9411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchdrungene Verbände" }
quests[9412] = { id = 9412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallflockendrops" }
quests[9413] = { id = 9413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallflockendrops" }
quests[9414] = { id = 9414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchdrungene Verbände" }
quests[9415] = { id = 9415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung bei Marschall Himmelswand", description = "Gehört Ihr zu Marschall Himmelswands neuen Rekruten? Natürlich.\n\nAuf was wartet Ihr noch? Gute Soldaten verlieren ihr Leben in der Wüste. Freut es Euch nicht, bald dazuzugehören?\n\nLos jetzt, macht Euch auf den Weg... und trocknet dabei nicht aus.", sourceObjective = "Sprecht mit Marschall Himmelswand beim Lager der Allianz in der Nähe des Zoraschwarmbaus.", completion = "Die Allianz braucht jeden tauglichen Rekrut, den sie bekommen kann. Die Horde hat ständig Verstärkung vom nördlichen Kontinent bekommen, wir mussten kämpfen, um überhaupt standzuhalten.\n\nLasst Euch die Lage von mir schildern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9416] = { id = 9416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung bei General Kirika", description = "Ihr müsst zu General Kirikas neuen Rekruten gehören. Es wurde Zeit, dass Ihr kommt. Der Truppenverschleiß in der Wüste ist hoch.\n\nDie Zwerge haben tagtäglich Verstärkung bekommen, wir können es uns nicht leisten in unserem Kampf um Ressourcen in Silithus an Boden zu verlieren.\n\nLasst Euch vom General weitere Anweisungen geben. Ich muss Euch Rekruten lediglich finden, nicht ausbilden.", sourceObjective = "Sprecht mit General Kirika beim Lager der Horde in der Nähe des Regalschwarmbaus.", completion = "Es ist gut, dass Ihr hier seid, aber wir haben keine Zeit für überflüssige Worte. Was Ihr braucht, sind Anweisungen, und dann müsst Ihr losziehen.\n\nHört gut zu.", sourceObjectiveStatus = "unverified-source-field" }
quests[9417] = { id = 9417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Arakkoabedrohung", description = "Die Arakkoa sind hochintelligente Wesen... genauso gerissen wie Gnome. Nur, dass sie über ein aggressives Gemüt und ein Händchen für Magie verfügen.\n\nIn letzter Zeit haben sie häufiger Patrouillen der Ehrenfeste überfallen, was auch der Grund für unsere Anwesenheit hier ist. Wisst Ihr, Mirren und ich sind weltbekannte Scharfschützen, ja, das sind wir! Allerdings sind wir eher auf Federvieh und Wildtiere spezialisiert... nicht auf diese Blitze schleudernden Vogelmenschen.\n\nWas sagt Ihr, greift Ihr uns in dieser Sache etwas unter die Arme? Ihr findet den Haal'eshbau im Südosten.", sourceObjective = "Gremni Langbart auf der Höllenfeuerhalbinsel möchte, dass Ihr 4 Windspäher der Haal'eshi und 6 Krallenwachen der Haal'eshi tötet.", progress = "Ihr seid zurück! Wie ist es gelaufen?", completion = "Fantastische Arbeit, {name}! Ich ernenne Euch hiermit zum Langbart ehrenhalber.\n\nBleibt noch ein Weilchen und trinkt etwas mit uns!", sourceObjectiveStatus = "unverified-source-field" }
quests[9418] = { id = 9418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avruus Kugel", description = "<Als Ihr die Kugel näher an Euer Ohr haltet, hört Ihr, wie Euch eine Stimme anspricht.>\n\nIhr seid kein Arakkoa, wie ich spüre. Deswegen werde ich versuchen, Euch einen Handel für meine Freiheit vorzuschlagen. Mein Name ist Aeranas. Ich regierte einst über die östlichen Winde. Der Magier der Haal'eshi, Avruu, hat mich in dieser Kugel eingefangen.\n\nSucht den Altar der Arakkoa, mit dessen Hilfe sie mich versklavt haben. Er ist südöstlich vom Bau der Arakkoa versteckt. Nähert Euch ihm mit der Kugel und gebt sie mir, sobald ich frei bin. Als Ausgleich für meine Freiheit werde ich Euch einen mächtigen Schatz geben!", sourceObjective = "Bringt Avruus Kugel zum Altar der Haal'eshi südöstlich des Haal'eshbaus auf der Höllenfeuerhalbinsel und gebt sie Aeranas, sobald er frei ist.", progress = "Endlich habe ich meine Freiheit wieder!", completion = "Mit dieser Kugel erlange ich meine Freiheit wieder. Nehmt Eure Belohnung, Sterblicher, auf dass meine Schuld bezahlt sei.", sourceObjectiveStatus = "unverified-source-field" }
quests[9419] = { id = 9419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchkämmen der Wüste", description = "Wir hatten vor Kurzem herausgefunden, dass die Horde die Wüste von Silithus nach Ressourcen abgesucht hat, schenkten dem Ganzen aber keine besondere Beachtung. Wir dachten, es wäre die Sache nicht wert, eine größere Anzahl von Soldaten in dieser Bruthitze zu stationieren.\n\nWie dem auch sei, wir haben die Wichtigkeit dieser Ressourcen erkannt und versuchen nun, um jeden Preis aufzuholen.\n\nWenn Ihr uns unterstützen wollt, müsst Ihr in die Wüste gehen, dort nach Silithyst suchen und diesen anschließend hierher bringen.", sourceObjective = "Findet Silithyst, bringt es zum Silithystextraktor und sprecht anschließend mit Marschall Himmelswand beim Lager der Allianz in der Nähe des Zoraschwarmbaus.", completion = "Dem Licht sei Dank, Eure Suche war erfolgreich.\n\nHätten wir nur eher damit begonnen, dann wären wir jetzt nicht in einer so verzweifelten Notlage. Wir müssen verhindern, dass die Schätze der Wüste in die Hände der Horde fallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9420] = { id = 9420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feinste Daunen", description = "Die Arakkoa das Haaleshbaus südlich von hier züchten eine besonders prächtige Art von Vögeln, namens Kaliri. Ihre Federn würden mir in den Handelsposten Azeroths einen ganz schönen Batzen Gold einbringen. Denkt nur an all das viele Bier, das ich mir leisten könnte!\n\nIch sag Euch was, bringt mir eine Ladung Kalirifedern und ich gebe Euch meinen Hut. Was sagt Ihr dazu? So einen Hut wie diesen hier, werdet Ihr nirgendwo sonst finden! Sind wir im Geschäft?", sourceObjective = "Mirren Langbart auf der Höllenfeuerhalbinsel möchte, dass Ihr ihm 8 Kalirifedern von den Kaliri im Haal'eshbau bringt.", progress = "Habt Ihr die Kalirifedern, {class}?", completion = "Ihr habt Euren Teil der Abmachung erfüllt. Ich schätze, Geschäft ist Geschäft!\n\nHier, mein Freund. Passt gut auf ihn auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[9421] = { id = 9421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung zum Schamanen" }
quests[9422] = { id = 9422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchkämmen der Wüste", description = "Wir haben die Wüste von Silithus bereits seit einiger Zeit nach Kristallressourcen durchkämmt. Die einzigen Gefahren, die sich uns dabei in den Weg gestellt haben, waren die Kreaturen, die dort heimisch sind, sowie Sand, Staub und Hitze.\n\nDie Allianz scheint nun aber Wind von unserem Unterfangen bekommen zu haben. Ein Rennen hat begonnen. Ein Rennen um die natürlichen Ressourcen und um deren Verteidigung.\n\nWir brauchen jede helfende Hand, die wir bekommen können. Ich hoffe, Ihr werdet uns unterstützen.", sourceObjective = "Findet Silithyst, bringt es zum Silithystextraktor und sprecht anschließend mit General Kirika beim Lager der Horde in der Nähe des Regalschwarmbaus.", completion = "Ausgezeichnete Arbeit, {name}. Diese Ressourcen kommen sofort zum Rest der Vorräte. Jedes bisschen trägt zu unserem Sieg und zur Schwächung unserer Feinde bei.", sourceObjectiveStatus = "unverified-source-field" }
quests[9423] = { id = 9423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Obadei", description = "Jetzt, da sich Sedais Tod bestätigt hat, liegt es an Euch, Obadei die traurige Nachricht zu überbringen.", sourceObjective = "Kehrt zu Anachoret Obadei beim Tempel von Telhamat auf der Höllenfeuerhalbinsel zurück und berichtet ihm von Sedais Tod.", completion = "Sedai, mein geliebter Bruder... \n\nDiese feigen Orcs! Er war unbewaffnet, wie konnten sie nur?\n\nLasst mich alleine, {name}. Ich danke Euch für Eure Hilfe, doch ich brauche jetzt etwas Zeit für mich selbst.", sourceObjectiveStatus = "unverified-source-field" }
quests[9424] = { id = 9424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Makurus Rache", description = "Sedai war für Makuru wie ein Bruder. Ich schulde ihm mein Leben und noch weit mehr! Sie sagen, Makuru sei verrückt, doch wenn die Omenai nach seinem Tod nichts tun wollen, dann sind sie die wahren Verrückten!\n\nMakuru kann in dieser Welt nicht viel sein Eigen nennen, aber ich werde Euch mit Freuden meinen einzigen Besitz überlassen, wenn Ihr Sedai rächt. \n\nIch habe die braunen Orcgrunzer schon mal gesehen, oben in den Bergen, im Nordosten. Sie hassen uns! Sie haben unser Mitleid nicht verdient! Geht und rächt Sedais Tod. Bringt mir ihre Ahnenperlen als Beweis!", sourceObjective = "Makuru im Tempel von Telhamat auf der Höllenfeuerhalbinsel möchte, dass Ihr ihm 10 Ahnenperlen der Mag'har bringt.", progress = "Habt Ihr Sedai in Makurus Namen gerächt?", completion = "Ja... Rache! Ihr wart gut.\n\nNehmt dies, es war ein Geschenk von Sedai. Wenn Makuru es behält, stimmt es ihn nur traurig.", sourceObjectiveStatus = "unverified-source-field" }
quests[9425] = { id = 9425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht an Tarrens Mühle", description = "Ah, gut Euch hier zu sehen, {class}! Ich habe eine Aufgabe, die wie für Euch gemacht ist.\n\nAls neue Mitglieder der Horde müssen wir dafür sorgen, dass wir sie bei ihren Unternehmungen unterstützen und bei ihren Problemen helfen. Dann werden sie uns auch bereitwilliger bei unseren helfen.\n\nReist zum Dorf der Verlassenen, Tarrens Mühle, im Vorgebirge des Hügellands im Südwesten. Meldet Euch bei Beraterin Morgenabend, wenn Ihr da seid.", sourceObjective = "Reist nach Tarrens Mühle im Vorgebirge des Hügellands und sprecht mit Beraterin Morgenabend.", sourceObjectiveStatus = "unverified-source-field" }
quests[9426] = { id = 9426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Teiche von Aggonar", description = "Seit den Tagen, in denen wir dieses Land Draenor nannten, hat sich viel geändert. Teile des Landes wurden durch die Verderbtheit der Dämonen für immer verwandelt.\n\nDazu gehören die Teiche von Aggonar. Einst befanden sich an diesem Ort die heiligen Quellen unseres Volkes. Das Blut des Dämons Aggonar hat die Essenz des geheiligten Wassers verschmutzt. Dieses teuflische Blut hat verderbte Kreaturen vorgebracht, die ausgelöscht werden müssen, wenn wir die Teiche jemals zurückfordern möchten. Reist von hier aus nach Osten und tötet die Teufelsblutelementare und den Schleim, der sich in den Teichen herumtreibt.", sourceObjective = "Amaan der Weise möchte, dass Ihr zu den Teichen von Aggonar geht und 6 Teufelsblutschrecken und 6 mörderische Faulschleime tötet.", completion = "Ja, ich fühle, wie die teuflische Präsenz in den Teichen abnimmt.\n\nIhr habt gute Arbeit geleistet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9427] = { id = 9427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinigung des Wassers", description = "Ich muss euch bitten, das, was wir angefangen haben, zu Ende zu bringen. Jetzt, da der teuflische Einfluss nachgelassen hat, müsst Ihr diese Reinigungsphiole nehmen und sie auf den Ursprung der Verderbnis schütten, Aggonars Leiche.\n\nIhr könnt die Knochen des Dämons am nördlichen Ende der Teiche finden. Aber seid vorsichtig, seine Essenz ist immer noch nicht ganz aus dieser Welt verschwunden.", sourceObjective = "Amaan der Weise möchte, dass Ihr zu den Teichen von Aggonar reist und die Reinigungsphiole bei Aggonars Leiche benutzt. Kehrt zu ihm zurück, wenn Ihr das Wasser von Aggonars Essenz befreit habt.", progress = "Ihr seid zurück, {name}. Ist das Wasser gereinigt?", completion = "Die Essenz von Aggonar lebte in seinem verderbten Nachkommen Aggonis weiter. Dank Eures Erfolgs gegen den Dämon können wir nun beginnen, die Teiche zu ihrer ursprünglichen Reinheit zurückzuführen.\n\nIhr habt unseren Dank, {name}. Eure Arbeit hat einen tiefen Eindruck in dieser Welt hinterlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9428] = { id = 9428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht an den Splitterholzposten", description = "<Die Botschafterin senkt die Stimme und beugt sich zu Euch.>\n\nEuer Ruf eilt Euch voraus, {name}. Ich möchte, dass Ihr zum Splitterholzposten im Eschental reist. Zu Fuß gelangt man am einfachsten durch Durotar, das Brachland und dann an der Weggabelung nach Norden dorthin.\n\nWenn Ihr dort angekommen seid, sprecht mit Berater Sonnenschwur. Reist vorsichtig, das Eschental kann sehr gefährlich sein!", sourceObjective = "Reist zum Splitterholzposten im Eschental und sprecht mit Berater Sonnenschwur.", sourceObjectiveStatus = "unverified-source-field" }
quests[9429] = { id = 9429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reist nach Dunkelhain", description = "Mir wurde gesagt, dass es einen Dorn in der Seite des Königreichs von Sturmwind gibt, Dämmerwald genannt. Dieser Ort ist erfüllt vom bösen und niederträchtigen Gestank des Untodes.\n\nDa wir versuchen, so gut wie möglich zu helfen, möchte ich, dass Ihr nach Südosten zu der größeren Menschensiedlung Dunkelhain reist. Anachoret Delan wird dort auf Eure Ankunft warten.", sourceObjective = "Reist nach Dunkelhain im Dämmerwald und sprecht mit Anachoret Delan.", sourceObjectiveStatus = "unverified-source-field" }
quests[9430] = { id = 9430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikte von Sha'naar", description = "Wie ich es Euch bereits sagte, ich brauche mein Augenlicht nicht, um zu sehen, was andere nicht zu erkennen vermögen. Ich werde nicht verurteilen, was Ihr in Makurus Namen getan habt, dennoch denke ich, Ihr solltet über das, was Euch Eure Augen zeigen, hinausblicken.\n\nReist zu den Ruinen von Sha'naar im Südwesten und sammelt so viele Relikte ein, wie Ihr finden könnt. Wenn es das Schicksal so will, werdet Ihr finden, was wir brauchen.\n\nDie Bedeutung meiner Bitte mag Euch im Moment unklar sein, doch habt vertrauen, {name}. Der Geduldige wird erleuchtet werden.", sourceObjective = "Amaan der Weise beim Tempel von Telhamat auf der Höllenfeuerhalbinsel möchte, dass Ihr zu den Ruinen von Sha'naar reist und 10 Relikte von Sha'naar einsammelt.", progress = "Habt Ihr die Relikte aus Sha'naar bei Euch, {name}?", completion = "Das Glück hat Euch gesegnet. Genau wie ich es erhofft hatte, habt Ihr ein ganz besonderes Relikt zwischen all den anderen gefunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9431] = { id = 9431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Different Approach" }
quests[9432] = { id = 9432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reist nach Astranaar", description = "Ich bin froh, dass Ihr helfen wollt. Es gibt in der Tat etwas, was Ihr tun könnt.\n\nAls Teil unseres Bündnisses mit der Allianz möchte ich, dass Ihr zur Elfenstadt Astranaar reist. Sie befindet sich im Eschental, einem großen Wald südlich von Dunkelküste auf dem Kontinent Kalimdor.\n\nBitte sprecht mit Verteidigerin Palanaar, wenn Ihr angekommen seid, und fragt nach, ob es etwas gibt, bei dem Ihr den Bewohnern behilflich sein könnt.", sourceObjective = "Reist nach Astranaar im Eschental und sprecht mit Verteidigerin Palanaar.", sourceObjectiveStatus = "unverified-source-field" }
quests[9433] = { id = 9433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dip in the Moonwell" }
quests[9434] = { id = 9434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testing the Tonic" }
quests[9435] = { id = 9435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisste Kristalle", description = "Wenn man etwas mit Sicherheit über das Hügelland sagen kann, dann, dass es auserkoren wurde, um unter dem Schatten des Krieges zu leben. Sogar etwas so Harmloses wie eine Wagenladung Steine kann als Ziel dienen.\n\nNormalerweise ist der Verlust von Baumaterial kein allzu großes Problem, aber bei der letzten Lieferung aus dem Azurschacht war eine Kiste mit seltenen Kristallen dabei, die ich sehr gerne untersucht hätte. Plünderer der Verlassenen haben den Wagen abgefangen und ihn nach Nordosten zu einem Turm gebracht, den sie wiederaufbauen wollen. Wir müssen diese Kristalle zurückholen, {class}!", sourceObjective = "Besorgt die Lieferung seltener Kristalle von den Verlassenen und bringt sie zu Huraan in Süderstade zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9436] = { id = 9436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erkenntnisse über die Blutskalpe", description = "Das trifft sich gut, {class}. Auf meinen Reisen habe ich die Kampftechniken der verschiedenen Trollstämme untersucht und eine Entwicklung erkannt. Die Blutskalpe in den Ruinen von Tkashi und Bal'lal im Norden benutzen die gleichen Taktiken wie die Amani in den nördlichen Wäldern.\n\nIhre Magie scheint sich in eine interessante Richtung entwickelt zu haben, und sie haben sie benutzt, um der mächtigste Stamm in der Gegend zu werden. Sie könnte der Kern einer Waffe gegen die Amani sein, aber ich muss noch mehr darüber herausfinden.", sourceObjective = "Nemeth Falkenauge im Basislager von Grom'gol möchte, dass Ihr ihm ein Totem der Blutskalpe von einem Schamanen der Blutskalpe bringt.", progress = "Enttäuscht mich nicht, {name}. Wenn wir die Magie der Blutskalpe für unsere Zwecke einsetzen können, kann mein Volk vielleicht die Amanibedrohung auslöschen.", completion = "Gut gemacht. Nun, das ist interessant...\n\nDie Sprache auf dem Totem wird ein Troll niemals erlernen können, aber uns ist sie wohlbekannt. Sie macht den Träger des Totems zu einem Verbündeten eines Wasserelementars namens Naias und erkennt ihn als würdig an, seine Macht zu verwenden.\n\nDas kommt sehr unerwartet, aber es ist nicht verheerend, {name}. Mit Eurer Hilfe möchte ich der Sache noch weiter auf den Grund gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9437] = { id = 9437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Untergang der Morgenbö", description = "Die Oger hier sind für nichts außer dreckige Witze, bitteres Bier und Wettkämpfe im Köpfe-aneinander-Schlagen zu gebrauchen. Als mein Schiff, die Morgenbö, untergegangen ist, haben sich diese Hunde von Theramore mit meiner Ladung und dem letzten überlebenden Crewmitglied aus dem Staub gemacht. Ich habe mich auf der Suche nach Hilfe hierher begeben, aber diese nichtsnutzigen Oger haben mich nur dumm angeschaut, als ich ihnen erzählt habe, was passiert ist.\n\nIch könnte die Hilfe eines zuverlässigen Helden brauchen, um die Überreste meiner Ladung und Ithania aus der Nordwacht zu retten. Der Turm befindet sich im Nordosten.", sourceObjective = "Balandar Sternenlicht in Brackenwall möchte, dass Ihr die Fracht der Morgenbö wiederholt und den Ersten Maat Ithania von den Streitkräften von Theramore in der Nordwacht befreit.", progress = "Habt Ihr Ithania befreit und meine Fracht von diesen glorifizierten Freibeutern zurückgeholt?", completion = "Gut gemacht, {name}! Sobald Ithania Zeit hatte, sich auszuruhen, und meine Vorbereitungen abgeschlossen sind, werden wir aus diesem sumpfigen Ödland hier wieder in die Zivilisation aufbrechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9438] = { id = 9438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Messenger to Thrall" }
quests[9439] = { id = 9439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unclaimed Baggage" }
quests[9440] = { id = 9440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ittle Morsels" }
quests[9441] = { id = 9441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Envoy to the Mag'har" }
quests[9442] = { id = 9442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine erschöpfende Krankheit", description = "Es ist schön, dass Ihr uns helfen wollt, {name}. Unsere Grunzer haben verdorbenes Wasser getrunken und sind krank geworden. Leider fehlt mir eine Zutat für eine Heilsalbe. Ich benötige einen seltenen Pilz namens Trockenkappe.\n\nUnser wichtigster Befehl ist, unseren Aufenthaltsort geheim zu halten, weswegen ich nicht riskieren kann, bei der Suche danach entdeckt zu werden. Der einzige Ort, an dem man auf der Höllenfeuerhalbinsel Trockenkappen finden kann, ist eine Höhle in der Nähe der Großen Kluft, südlich von hier.\n\nSeid äußerst vorsichtig, wenn Ihr Euch entschließen solltet, danach zu suchen.", sourceObjective = "Erdenruferin Ryga beim Posten der Mag'har auf der Höllenfeuerhalbinsel möchte, dass Ihr 1 Trockenkappe aus einer Höhle in der Großen Kluft besorgt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9443] = { id = 9443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The So-Called Mark of the Lightbringer" }
quests[9444] = { id = 9444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defiling Uther's Tomb" }
quests[9445] = { id = 9445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein würdiges Opfer", sourceObjective = "Beschafft Euch Uthers Segen von der Spitze des Wachturms beim Eingang zu Herdweiler und bringt ihn zu <NPC> beim Zugwindlager.", sourceObjectiveStatus = "unverified-source-field" }
quests[9446] = { id = 9446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Grab des Lichtbringers", description = "Jetzt, da Ihr das Mal des Lichtbringers zurückgeholt habt, müssen wir es nur noch zu Uthers Grabmal bringen.\n\nWollt Ihr mich dorthin begleiten? Es ist nicht weit und ich würde Eure Gesellschaft genießen. Danach könnt Ihr hierher zurückkehren und der Hohepriesterin MacDonnell von Eurer Erfahrung berichten.\n\nWas haltet Ihr davon, {name}?", sourceObjective = "Begleitet Anachoret Truun zu Uthers Grabmal in den Westlichen Pestländern. Sprecht danach mit Hohepriesterin MacDonnell im Zugwindlager in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9447] = { id = 9447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salbe verabreichen", description = "Ich habe mit den Kräutern, die Ihr mir gebracht habt, eine Salbe zubereitet, die die Stärke der Grunzer wiederherstellen sollte. Nehmt sie und verabreicht sie allen entkräfteten Grunzern an, die Ihr hier in der Nähe seht.", sourceObjective = "Erdenruferin Ryga möchte, dass Ihr die Heilsalbe 10 entkräfteten Grunzern beim Posten der Mag'har auf der Höllenfeuerhalbinsel verabreicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[9448] = { id = 9448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitleid mit den Verfluchten", description = "Diese Blutelfenhexe, Cersei Abendsänger, hat die Verirrten verflucht! Ich weiß es einfach! Ich weiß nicht wie und warum, aber die Folgen sind verheerend. Viele der Verirrten wurden noch weiter verderbt und mit noch teuflischeren Energien verflucht!\n\n{class}, könnt Ihr tief in Eurem Inneren etwas Mitleid für diese armen Kreaturen aufbringen? Sie sollten ihr Leben nicht in einem so furchtbaren Zustand verbringen.\n\nIhr findet die verfluchten Verirrten in der Zuflucht der Verirrten, den Pfad hinunter nach Osten.", sourceObjective = "Tötet 3 Verfluchte der Verirrten und kehrt dann zu Anachoret Avuun im Sicheren Hafen in den Sümpfen des Elends zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9449] = { id = 9449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Erde", description = "Die Zeit ist gekommen, {name}. Euer Körper und Euer Geist sind an einem Punkt angelangt, an dem Ihr direkt mit den elementaren Geistern Azeroths kommunizieren müsst.\n\nLasst Euch jedoch gewarnt sein. Ich spüre, dass unser ungewöhnliches Betreten dieser Welt und dessen unglückliche Nebenwirkungen die Erdgeister erzürnt und zu einem Ungleichgewicht der Elemente geführt haben.\n\nWollt Ihr Euer Erdtotem erschaffen, so müsst Ihr zuerst mit dem Geist des Tals sprechen. Ihr findet ihn im Heiligen Hain, der sich an die Hügel im Nordwesten schmiegt.", sourceObjective = "Sprecht mit dem Geist des Tals beim Heiligen Hain im Am'mental.", sourceObjectiveStatus = "unverified-source-field" }
quests[9450] = { id = 9450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Erde", description = "Das Gleichgewicht der Elemente wurde durch das gewaltsame Eindringen der Draenei ins Tal gestört. Euer Absturz hat die Erdgeister erzürnt und gegen die anderen Elemente gewendet. Ihr werdet sehen, dass man die Elemente nur dann verstehen kann, wenn diese in Einklang sind.\n\nFolglich müsst Ihr das Gleichgewicht wieder herstellen. Im Hain hinter mir findet Ihr ruhelose Erdgeister, die gegen die anderen drei Elemente aufbegehren. Helft uns, stellt den Einklang wieder her.", sourceObjective = "Tötet 4 ruhelose Erdgeister und kehrt zum Geist des Tals beim Heiligen Hain im Am'mental zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9451] = { id = 9451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Erde", description = "Ich werde Euch jetzt einen Teil meines physischen Wesens geben, damit Ihr Euer Erdtotem erschaffen könnt. Bringt es zu dem, der Euch hierher gesandt hat. Ihr und ich werden von nun an auf Lebzeiten miteinander verbunden sein.\n\nDie Kräfte der Erde werden Euch in Eurem Leben fortwährend zur Verfügung stehen. Wenn Eure Knochen am Ende Eurer Tage wieder zu uns zurückkehren, schließt sich der Kreislauf wieder.\n\nSetzt Eure Macht weise ein.", sourceObjective = "Bringt den Erdkristall zu Firmanvaar bei der Absturzstelle im Am'mental.", sourceObjectiveStatus = "unverified-source-field" }
quests[9452] = { id = 9452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnapper - sehr, sehr lecker!", description = "Ich habe festgestellt, dass es in diesen Gewässern von Schnappern nur so wimmelt. Das ist ein sehr, sehr leckerer Fisch.\n\nMit einem Fischernetz kann ich genug fangen, um dutzende von Draenei satt zu bekommen! Unglücklicherweise wurde ich erst kürzlich von einer Kreatur angegriffen, die man Murloc nennt, als ich im Fluss fischte. Ich wurde dabei verletzt und kann deshalb meine Arbeit nicht mehr verrichten. Ich brauche Hilfe!\n\nIhr müsst dieses Fischernetz lediglich in der Nähe von Schnapperschwärmen, die man im Kristalfluss östlich von hier findet, auswerfen.\n\nWas sagt Ihr? Vergesst aber nicht, das Netz nach getaner Arbeit wieder zurückzubringen.", sourceObjective = "Verwendet das Fischernetz der Draenei, um 10 Schnapper zu fangen. Bringt die Fische und das Netz anschließend zu Diktynna auf der Azurmythosinsel zurück.", progress = "Nehmt Euch vor den Murlocs in Acht: seltsame und extrem lästige kleine Kreaturen.", completion = "Ich hoffe Ihr hattet nicht zu viele Scherereien wegen der Murlocs, {name}. Ich bin Euch sehr dankbar für alles, was Ihr getan habt.\n\nSoll ich Euch vielleicht das Angeln beibringen? Ich kann Euch sogar eine Angelrute und ein glänzendes Schmuckstück geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9453] = { id = 9453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet Acteon!", description = "Ihr habt das wunderbar gemacht, {name}. Unsere Leute werden Euch für diesen Fang sehr dankbar sein. Ach ja, könntet Ihr diese Ladung Schnapper vielleicht zu Acteon bei der Azurwacht bringen?\n\nEr dürfte leicht zu finden sein, da er diese Lieferung bereits erwartet.", sourceObjective = "Bringt die Ladung Schnapper zu Acteon bei der Azurwacht.", progress = "Was haltet Ihr von meiner Rüstung? Habe sie selbst hergestellt! Sie unterscheidet sich zwar etwas von den traditionellen Rüstungen, die wir normalerweise tragen, ist aber sehr bequem.", completion = "Arme Diktynna... der Murloc hat ihr wohl einen ziemlichen Schrecken eingejagt.\n\n<Acteon seufzt.>\n\nHoffentlich heilen ihre Verletzungen bald...\n\nIhr haltet also nach Arbeit Ausschau, nun, davon gibt es bei der Azurwacht jede Menge!", sourceObjectiveStatus = "unverified-source-field" }
quests[9454] = { id = 9454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die große Mondweidenjagd", description = "Ihr macht Euch hier einen Namen, {name}. Warum versucht Ihr Euch nicht mal im Jagen?\n\nAuf Draenor würden unsere besten Jäger Tiere jagen, die den Mondweidenhirschen dieser Gegend sehr ähneln und den Namen Talbuk tragen.\n\nWenn Ihr denkt, Ihr seid 'Draenei' genug, dann zieht durch die Wildnis rund um die Azurwacht und tötet ausreichend Mondweidenhirsche und -böcke, um Eure Taschen mit ihrem Fleisch zu füllen.\n\nDie Hirsche grasen südlich der Azurwacht, die Böcke im Norden. Gebt auf ihre Hörner Acht!", sourceObjective = "Acteon bei der Azurwacht möchte, dass Ihr ihm 6 Mondweidenhirschlenden bringt.", progress = "Die Bälge der Hirsche taugen nichts, dafür ist ihr Fleisch köstlich zart.", completion = "Gut gemacht, {name}, gut gemacht!\n\nHier, während Ihr fort wart, habe ich ein paar der Lenden, die Ihr mir gebracht habt, zubereitet. Vielleicht wollt Ihr ja auch das Rezept haben?", sourceObjectiveStatus = "unverified-source-field" }
quests[9455] = { id = 9455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltsame Funde", description = "Der Kristall, den Ihr beim Körper des Nachtpirscherjungen gefunden habt, scheint ein Teil der Exodar zu sein. Vielleicht ist dies eine Erklärung für das ungewöhnliche Aufkommen und Verhalten einiger Tiere dieser Gegend.\n\nBringt den Kristall zurück zur Azurwacht. Der Exarch wird sicherlich von dieser Entdeckung erfahren wollen.", sourceObjective = "Bringt den schwach leuchtenden Kristall zu Exarch Menelaous bei der Azurwacht.", progress = "Was habt Ihr gefunden? Wo?", completion = "Wie konnte solch ein Ding nur im Magen eines Nachtpirschers enden? Könnten die Trümmer des Absturzes noch mehr Kreaturen verseucht haben?", sourceObjectiveStatus = "unverified-source-field" }
quests[9456] = { id = 9456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachtpirscherjagd", description = "Ich werde nicht versuchen, irgendwelche Ausreden für das, was Ihr gefunden habt, zu finden. Es ist ganz klar unsere Schuld. Uns wurde von zertrümmerten Kristallfragmenten im östlich gelegenen Fluss berichtet, aber wir hatten beschlossen, diese Implikationen zu ignorieren. Wir können jetzt entweder auf dieser Insel herumsitzen und diese Tragödie beweinen, oder etwas tun, um eine Ausbreitung zu vermeiden.\n\nWenn Ihr es ertragen könnt, möchte ich, dass Ihr zurück in die Wildnis geht und so viele der infizierten Nachtpirscherjungen tötet, wie Ihr finden könnt.", sourceObjective = "Exarch Menelaous bei der Azurwacht möchte, dass Ihr 8 infizierte Nachtpirscherjungen tötet.", completion = "Ich hoffe nur, dass es nicht schon zu spät ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[9457] = { id = 9457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ungewöhnlicher Patron", description = "Naias ist also das Genie hinter den Blutskalpen und ihrer fremdartigen Magie? Ich muss zugeben, dass ich nie gedacht hätte, dass meine Nachforschungen dort enden würden, aber unsere Erkenntnisse könnten sich vielleicht trotzdem als hilfreich herausstellen.\n\nVor der Küste im Nordwesten befindet sich eine kleine Insel, die von geringen Wasserelementaren bewohnt wird. Es gibt dort eine grobe Steinplatte, die den Trollen vielleicht als Altar dienen könnte. Bringt das Totem, das Ihr gefunden habt, zu diesem Altar. Vielleicht können wir diesen Naias ja hervorlocken und seine Macht in eine angenehmere Form bringen.", sourceObjective = "Benutzt Naias' Gabe in der Nähe des Altars von Naias, um den Wasserelementar Naias zu rufen. Besiegt ihn und kehrt dann zu Nemeth Falkenauge im Basislanger von Grom'gol mit dem Herz von Naias zurück.", progress = "Was gibt es Neues von Naias, {name}?", completion = "Ich kann die rohe Macht in diesem Edelstein fühlen, {name}. Ich werde ihn nach Silbermond schicken, damit unsere Magister ihn weiter untersuchen können, aber ich bin mir sicher, dass er uns im weiteren Kampf gegen die Amani dienlich sein kann.\n\nEure Hilfe bei der Besorgung dieses Steins war unbezahlbar. Ich werde dafür sorgen, dass die Weltenwanderer den Namen des Helden, der diesen Fund möglich gemacht hat, erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[9458] = { id = 9458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trank der geschärften Sinne" }
quests[9459] = { id = 9459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anticrittrank" }
quests[9460] = { id = 9460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit vereinten Kräften", description = "Keltus Dunkellaub meldet sich zum Dienst!\n\nOh... wer seid Ihr eigentlich? Wenn Ihr wegen meinem Bericht hier seid, dann müsst Ihr mir zuerst helfen.\n\nIch habe vor, die Spione der Schildwache anzugreifen, möchte meine treue Tuschel aber als Vorhut vorausschicken. Sie braucht lediglich eine Fährte, die sie auf sie hetzt.\n\nJemand von Eurem Können kann sich doch sicherlich hineinschleichen und etwas von der Anführerin der Schildwachen stehlen?", sourceObjective = "Keltus Dunkellaub möchte, dass Ihr das spitzenverzierte Taschentuch von der Anführerin der Schildwachen stehlt und zu ihm bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9461] = { id = 9461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Feuers", description = "Ihr sollt wissen, dass der Prophet nach Euch gefragt hat, da er von Euren Erfolgen in Euren Prüfungen erfahren hat. Die Erschaffung Eures Feuertotems muss warten, bis Ihr mit ihm gesprochen habt.\n\nDies ist eine seltene Ehre; geht sofort zur Exodar, um so schnell wie möglich mit ihm zu sprechen!", sourceObjective = "Geht zu Prophet Velen in der Halle des Lichts in der Exodar.", sourceObjectiveStatus = "unverified-source-field" }
quests[9462] = { id = 9462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Feuers", description = "{name}! Es ist an der Zeit, dass Ihr weitere Ausbildung im Weg der Geister erhaltet. Ihr solltet mit Tuluun, dem Schamanen in der Azurwacht, sprechen. Er kann Euch in dem Verständnis und der Beherrschung der Macht des Feuers unterweisen.", sourceObjective = "Geht zu Tuluun in der Azurwacht auf der Azurmythosinsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[9463] = { id = 9463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Medizinische Notwendigkeit", description = "Ich habe herausgefunden, dass die Ranken der Pflanzenkreaturen, den sogenannten Peitschern, auf dieser Insel eine regenerierende Eigenschaft besitzen. Wenn man die Ranken richtig verarbeitet, kann man aus ihnen eine hochwirksame Heilsalbe herstellen. Durch die vielen verletzten Draenei, die ständig in der Azurwacht eintreffen, sind unsere Vorräte an Heilmitteln beinahe erschöpft.\n\nUnser besonderer Gast wurde erst gestern schwer verletzt und bewusstlos am Kristallfluss gefunden. Bringt mir die Wurzeln und wir können sie möglicherweise retten.\n\nHaltet südlich und östlich von hier nach den Lauerwurzkreaturen Ausschau, {class}. Ihr dürft keine Zeit verlieren!", sourceObjective = "Anachoret Fateema bei der Azurwacht möchte, dass Ihr für sie 8 Lauerwurzranken sammelt.", progress = "Ich fürchte, ihr Zustand verschlimmert sich zusehends.", completion = "Lasst uns hoffen, dass diese Salbe ihren Lebenswillen neu belebt!", sourceObjectiveStatus = "unverified-source-field" }
quests[9464] = { id = 9464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Feuers", description = "Ihr sollt noch einmal auf die Probe gestellt werden. Diesmal ist es das chaotische Element des Feuers, das Ihr verstehen müsst, wenn Ihr ein Totem erstellen wollt, um dessen Energien zu nutzen.\n\nIm Nordosten entlang der Küste gibt es einen heiligen Ort des Feuers, den Glutgrund. Inmitten der verbrannten Bäume wacht Glutos, ein besonders mächtiger und weiser Feuerelementar. Mit ihm müsst Ihr sprechen.\n\nGeht jetzt zu ihm, mögen die Elementargeister von Azeroth mit Euch sein.", sourceObjective = "Sprecht mit Glutos beim Glutgrund auf der Azurmythosinsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[9465] = { id = 9465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Feuers", description = "Einer meiner Brüder, Hauteur, ist verrückt geworden! Zweifellos ist der Absturz Eures Schiffs daran schuld. Er verlangt jetzt, dass ihn die heimischen Eulenbestien verehren.\n\nDas kann nicht so weitergehen! Keiner von uns würde jemals einen Gott verkörpern! Ihr müsst das Gleichgewicht wieder herstellen.\n\nAls Erstes müsst Ihr ihre Ritualfackel finden, welche in Besitz der wahnsinnigen Wildekin innerhalb der Tannenruhfeste im Westen ist.\n\nBringt mir diese Fackel.", sourceObjective = "Erlangt die Ritualfackel wieder und bringt sie zu Glutos beim Glutgrund auf der Azurmythosinsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[9466] = { id = 9466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Schwarzkralle die Wilde", description = "Auf Anweisung des Waldläuferhauptmanns wird hiermit eine Belohnung auf die Erlegung der teuflischen Felsklauenmatriarchin, bekannt als Schwarzkralle die Wilde, ausgesetzt.\n\nSchwarzkralle wurde zuletzt in einer Höhle in der Großen Kluft gesichtet. Zum Erhalt der Belohnung müssen die Klauen der Kreatur vorgezeigt werden.", sourceObjective = "Bringt Schwarzkralles Klauen zu Waldläuferhauptmann Venn'ren bei der Falkenwacht auf der Höllenfeuerhalbinsel.", progress = "Gibt es Neuigkeiten über Schwarzkralle?", completion = "Ihr seid ein tapferer {class}, {name}. Diese Bestie hat viele meiner besten Jäger das Leben gekostet.\n\nNehmt die Belohnung, Ihr habt sie Euch redlich verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[9467] = { id = 9467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Feuers", description = "Den Eulenbestien vom Mondschwingenbau auf der Silbermythosinsel, weit im Südwesten, wurde weisgemacht, dass Hauteur ein Gott sei, den es zu huldigen gilt. In Wirklichkeit ist er ein abtrünniger Elementar, den man von seinem Leid erlösen muss. Diese Fackel ist der Schlüssel zu seinem Niedergang.\n\nHauteur verlangt von den Eulenbestien die regelmäßige Entzündung eines Feuers zu seinen Ehren. Sobald Ihr es entfacht, wird er kommen. Tötet ihn und bringt mir seine Asche. Verwendet die Kugel in Eurer Tasche und ich werde Euch hierher zu mir zurückbringen.", sourceObjective = "Besorgt Euch Hauteurs Asche und bringt sie zusammen mit der Ritualfackel zu Glutos beim Glutgrund auf der Azurmythosinsel. Vergesst nicht, dass Ihr die Kugel der Rückkehr verwenden könnt, um zu Glutos zurückzukehren, sobald Ihr die Asche habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9468] = { id = 9468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Feuers", description = "Ihr habt heute bei dem Versuch, Eure Bindung zum Feuer zu verstehen, etwas Großartiges geleistet. Vergesst nicht, dass Ihr ihm stets den gebührenden Respekt erweisen sollt, um Euch nicht selbst daran zu verbrennen.\n\nIch habe einen Teil von Hauteurs Asche für Euch aufgehoben. Verwendet ihn, wenn Ihr Euer Feuertotem erstellt und vergesst nichts von dem, was Ihr auf Eurem Weg hierher gelernt habt.\n\nKehrt jetzt zu Tuluun zurück.", sourceObjective = "Bringt Hauteurs Asche zu Tuluun in der Azurwacht auf der Azurmythosinsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[9469] = { id = 9469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Federbarts Unterstützung", description = "Sollte ich endlich eine Audienz bei Falstad Wildhammer gewährt bekommen, hoffe ich einen der besten Fürsprecher der Wildhammerzwerge an meiner Seite zu haben, {name}.\n\nFederbart genießt bei seinen Leuten hohes Ansehen, sei es wegen seiner legendären Ausbildungsmethoden für Greifen oder wegen seiner Weisheit. Wenn jemand Falstad Wildhammer überzeugen kann, dann er.\n\nIch würde ihn ja gerne selbst aufsuchen, allerdings darf ich den Nistgipfel nicht verlassen, solange ich meine Audienz erwarte. Sucht Federbart bei seiner Wohnstätte im Süden auf und fragt ihn, ob er an meiner Seite aussagen möchte.", sourceObjective = "Geht zu Federbarts Hütte und stattet dem Zwerg dort einen Besuch ab. Solltet Ihr ihn nicht dort antreffen, so sucht nach Hinweisen auf seinen Verbleib.", sourceObjectiveStatus = "unverified-source-field" }
quests[9470] = { id = 9470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Geste des guten Willens", description = "Das zerklüftete Gebiet des Hinterlands ist nicht nur das Zuhause der Zwerge des Wildhammerklans und ihrer Greifen, sondern auch einiger Waldtrollstämme.\n\nDie Trolle betrachten die Wildhämmer als Besatzer ihres Heimatlands und lassen keine Gelegenheit aus, um die Zwerge zu belästigen, indem sie die Greifennester angreifen. Ein Weg uns in den Augen der Wildhämmer zu beweisen ist, diese Angriffe zum Ende zu bringen, indem wir einen Anführer der Bleichborken, Hexendoktor Mai'jin, töten. Er befindet sich in einer Höhle in Bogens Kante, westlich von Shadra'Alor.", sourceObjective = "Botschafter Rualeth auf dem Nistgipfel möchte, dass Ihr Hexendoktor Mai'jin und seine Spinne Tcha'kaz tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[9471] = { id = 9471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Raubtiere zur Beute machen", description = "Die Wildhammerzwerge sind die Begleiter, Hüter und Ausbilder der Greifen. Die Greifen haben genügend Feinde, vor allem unter den Stämmen der Waldtrolle.\n\nManchmal stammt die Gefahr aber auch von natürlichen Feinden, wie zum Beispiel den Wölfen. Ein einzelnes Tier ist kein erstzunehmender Gegner für einen Greifen, aber in letzter Zeit werden die Greifen immer häufiger von Rudeln angegriffen, da ihre natürliche Beute knapp wird. Die Wölfe auszulöschen könnte wesentlich zur Sicherheit der Greifen beitragen und uns bei den Wildhämmern sehr beliebt machen.", sourceObjective = "Botschafter Rualeth auf dem Nistgipfel möchte, dass Ihr 10 räudige Silbermähnen und 5 Silbermähnenwölfe tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[9472] = { id = 9472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arelions Geliebte", description = "Bei all den wichtigen Dingen, die er zu tun hatte, fand Arelion immer noch genug Zeit seine Geliebte zu besuchen!\n\nJetzt wird mir alles klar. Viera Sonnenwisper, dieses widerwärtige Frauenzimmer... wir werden Ihr beibringen, sich niemals in die Angelegenheiten einer Magistrix einzumischen.\n\nNehmt diese Schriftrolle und findet Viera. Sucht einen Weg, sie vom Dorf wegzulocken und benutzt die Schriftrolle.\n\nArelion erwähnte, dass sie einem bestimmten Wein, der von den Druiden des Cenarius angebaut wird, nicht widerstehen kann. Vielleicht findet Ihr ein wenig davon bei der Zuflucht des Cenarius in den Zangarmarschen westlich von hier.", sourceObjective = "Magistrix Carinda bei der Falkenwacht auf der Höllenfeuerhalbinsel möchte, dass Ihr Viera Sonnenwisper aus der Siedlung herauslockt und Carindas Rolle der Vergeltung auf sie anwendet.", completion = "Hervorragend! Diese hinterhältige Göre wird sich mit niemandes Ehemann mehr davonschleichen.\n\nHier habt Ihr eine Kleinigkeit für Eure Mühen. Ich vertraue darauf, dass diese Angelegenheit unter uns bleibt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9473] = { id = 9473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine alternative Alternative", description = "Der Zustand des Mädchens ist bereits zu kritisch, als dass einfache Salben sie noch retten könnten. Es gibt möglicherweise noch einen anderen Weg...\n\nDer Wald von Azurmythos birgt viele Geheimnisse, eines davon ist eine seltene Pflanze, das Azurlöwenmäulchen, die viele als Allheilmittel ansehen.\n\nSie ist leicht zu entdecken, da sich ihr Aussehen sehr stark von allen anderen Pflanzen unterscheidet und sie ausschließlich im Schatten der Azurkiefer wächst. Beeilt Euch!\n\nUnd {name}, nehmt Euch vor den Drescherwurzkreaturen in Acht! Sie ernähren sich von den Azurlöwenmäulchen.", sourceObjective = "Daedal bei der Azurwacht möchte, dass Ihr für ihn 5 Azurlöwenmäulchen sammelt.", progress = "Verschwendet keine Zeit, Junge.", completion = "Seht, wie die Pflanze ihre wundersame Wirkung entfaltet.", sourceObjectiveStatus = "unverified-source-field" }
quests[9474] = { id = 9474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mal des Lichtbringers", description = "In der kurzen Zeit, die ich in Azeroth verbracht habe, habe ich viele seiner Helden studiert. Einer von ihnen, Uther Lichtbringer, hebt sich von allen anderen ab. Nachdem er viele Jahre ein Held war, wurde er am Ende von seinem viel versprechendsten Schüler, Arthas, verraten.\n\nZu seiner Ehre würde ich gerne etwas, das er verloren hat, zu seinem Grabmal bringen. Man sagt, dass der Scharlachrote Kreuzzug eines seiner heiligen Relikte oben in dem Wachturm in der Nähe von Herdweiler aufbewahrt.\n\nBitte, {class}, geht und holt es zurück.", sourceObjective = "Besorgt das Mal des Lichtbringers und kehrt dann zu Anachoret Truuen im Zugwindlager in den Westlichen Pestländern zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9475] = { id = 9475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiedererlangen der Eier", description = "Die Begutachtung der Überreste lässt vermuten, dass es sich bei dem zerschmetterten Skelett um Federbart handeln muss. Eine der skelettierten Hände umklammert fest ein zerfetztes und schmutziges Stück Papier. Ihr zieht es vorsichtig heraus und rollt es auf. Zum Vorschein kommt eine handgezeichnete Karte und ein paar eilig hingekritzelte Notizen.\n\nDie Karte scheint eine Skizze von Shadra'Alor und seinen drei Tempeln zu sein. Mehrere 'X' auf der Zeichnung markieren vermutlich die Lage gestohlener Eier. Ihr packt die Karte ein und plant, sie an einem sicheren Ort genauer zu untersuchen.", sourceObjective = "Erlangt 5 Greifeneier und bringt sie zu Botschafter Rualeth beim Nistgipfel.", sourceObjectiveStatus = "unverified-source-field" }
quests[9476] = { id = 9476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach Federbart", description = "Die jüngsten Einträge in Federbarts Tagebuch beschreiben seine Sorge bezüglich der immer häufigeren Überfälle von Bleichborkentrollen auf die Greifen im Wildhammergebiet und die sich mehrenden Diebstähle von Eiern. Die Untersuchung der kleineren Bleichborkensiedlungen brachte keine Informationen zu Tage.\n\nDer letzte Eintrag handelt von Federbarts Verdacht, dass ein Hexendoktor der Bleichborken, namens Mai'jin, hinter all den Raubzügen steckt. Am Ende des Eintrags, steht mit hastig geschriebenen Worten, dass der Zwerg die Absicht hat, nach Shadra'Alor zu gehen und nach den Eiern zu suchen.", sourceObjective = "Reist nach Shadra'Alor und sucht nach Spuren von Federbart.", sourceObjectiveStatus = "unverified-source-field" }
quests[9477] = { id = 9477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trank der natürlichen Rüstung" }
quests[9478] = { id = 9478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tragbare Heilfontäne" }
quests[9479] = { id = 9479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glorreiches Banner der Allianz" }
quests[9480] = { id = 9480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwächendes Banner" }
quests[9481] = { id = 9481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leichtes Verbrauchsgut" }
quests[9482] = { id = 9482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trank des Naturwiderstands" }
quests[9483] = { id = 9483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die feinen Freuden im Leben", progress = "Nur weil wir auf dieser Pilgerfahrt sind, heißt das noch lange nicht, dass wir alle Freuden im Leben aufgeben müssen. Ich hatte schon seit Ewigkeiten keinen guten Wein mehr.\n\nIch könnte im wahrsten Sinne des Wortes für eine gute Flasche Cenarischer Geistertropfen töten!\n\nIch weiß, ich weiß, wie unpassend von mir, ein Nachtelfengebräu zu genießen.", completion = "Vielleicht werden wir ja doch noch Freunde. Folgt mir! Wir wollen schließlich nicht mit den anderen teilen müssen, oder?" }
quests[9484] = { id = 9484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Ihr habt zweifellos schon Tiere für Euren Schutz und für Euren Lebensunterhalt getötet, jedoch seid Ihr erst jetzt bereit, Euch mit ihnen anzufreunden und sie zu zähmen, um von ihrer Stärke Gebrauch zu machen. Ich kann Euch darin ausbilden.\n\nNehmt diese magische Zähmerrute, sie wird ein wildes Tier vorübergehend an Euch binden und an Eurer Seite kämpfen lassen. Beginnt mit einem wahnsinnigen Drachenfalken, ein recht gefügiger Vogel, den man außerhalb der Zuflucht der Weltenwanderer findet. Kehrt anschließend zu mir zurück.", sourceObjective = "Verwendet die Zähmerrute, um einen wahnsinnigen Drachenfalken zu zähmen. Kehrt anschließend zu Leutnant Dämmerflucht zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9485] = { id = 9485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Ihr habt Euch gut geschlagen, {name}. Euer Verständnis für die Wildnis wird rasch größer.\n\nDie Nebelfledermaus ist ein listiger Jäger, sie vereint die Schnelligkeit des Drachenfalken und die Wildheit einer Bachtatze. Man findet die Nebelfledermäuse direkt über dem Elrendar im Süden, wo sie unglücklichen Reisenden auflauern, die in den Geisterlanden umherwandern.\n\nVerwendet diese letzte Zähmerrute, um eine Nebelfledermaus zu bändigen. Kehrt anschließend zu mir zurück.Ihr erlernt:", sourceObjective = "Verwendet die Zähmerrute, um eine Nebelfledermaus zu zähmen. Kehrt anschließend zu Leutnant Dämmerflucht zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9486] = { id = 9486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Die alte Bachtatze ist ein gründlicher und geschickter Jäger. Wenn man sie zähmen möchte, sieht sie einen sofort als Beute. Lasst Euch nicht von Eurem Vorhaben abbringen.\n\nVerwendet die Zähmerrute, um diese große Katze gefügig zu machen und an ihrer Seite zu jagen. Man findet sie überall im Immersangwald, manche sogar ganz nahe bei der Jagdhütte. Kehrt zu mir zurück, wenn Ihr genug gelernt habt.", sourceObjective = "Verwendet die Zähmerrute, um eine alte Bachtatze zu zähmen. Kehrt anschließend zu Leutnant Dämmerflucht zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9487] = { id = 9487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkanhäscher", description = "Arkanhäscher sind magische Kunstwesen mit roher Kraft. Sie sind dick gepanzert und können schwere Schläge austeilen. Eure Zauberkraft gewährt Euch jedoch den Vorteil, ihre Abwehr umgehen und Treffer von ihnen vermeiden zu können, {name}.\n\nReist zum Morgensternturm und sprengt die Arkanhäscher in Stücke! Bei ihren Überresten findet Ihr kristallisierte Fragmente magischer Energie. Sammelt diese und bringt sie zu mir. Den Morgensternturm findet Ihr im Osten, jenseits des Sees.", sourceObjective = "Arkanist Vandril möchte, dass Ihr 10 Arkantrümmer für ihn sammelt.", progress = "Ihr seid den Rohlingen nicht zu Nahe gekommen, hoffe ich?", completion = "Welche Verschwendung, Magie zu nutzen um Wesen von körperlicher Gewalt zu erschaffen. Ich dachte immer, das wäre der Grund, warum wir uns mit den niederen Völkern verbündet hätten.\n\nEs war gut von Euch, sie zu zerstören. Nun können wir ihre Überreste für angemessenere Zwecke verwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9488] = { id = 9488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine einfache Robe", description = "Die Arkantrümmer, die Ihr gesammelt habt, sind gut geeignet.\n\nGeeignet wofür, möchtet Ihr wissen? Um eine prächtige {class}robe für Euch herzustellen!\n\nAlles, was wir jetzt noch benötigen, ist etwas Leinenstoff und eine Seidendrüse der Spindelweber. Die Seidendrüse bekommt Ihr von einer Spindelweberspinne, vorzugsweise nachdem Ihr diese getötet habt.", sourceObjective = "Arkanist Vandril möchte, dass Ihr ihm 15 Leinenstoff und eine Seidendrüse der Spindelweber bringt.", progress = "Die Robe kann ohne die notwendigen Materialien nicht fertiggestellt werden, aber das ist Euch sicherlich bekannt.", completion = "Die Details der Herstellung von magischen Roben brauchen Euch nicht zu interessieren, {name}, Ihr müsst nur Wissen, was Ihr mir zu bringen habt.\n\nUm ehrlich zu sein, Ihr habt mir genug für mehrere Roben gebracht. Der Profit, den ich damit machen kann, sollte ausreichen, um die Herstellungskosten Eurer Robe zu decken, und mir selbst noch etwas Nettes zu kaufen. Habt Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[9489] = { id = 9489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ordnung in der Schneise", description = "{name}, gut, dass Ihr hier seid. Die Geißel überfällt unsere Stadt mit so unendlichem Hass, dass ich befürchten muss, dass die Moral unserer Wache langsam dahinschwindet.\n\nEilt zu der Todesschneise südlich der Stadt, wo Jaela und ihre Waldläufer bereitstehen. Erfüllt sie mit Eurem Segen mit der Macht des Lichts.", sourceObjective = "Wirkt das Machtwort: Seelenstärke auf 6 Waldläufer von Immersang in der Todesschneise.", sourceObjectiveStatus = "unverified-source-field" }
quests[9490] = { id = 9490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Felsklauenmatriarchin", description = "Felsklauen sind bösartige, hinterhältige und grausame Kreaturen. Aber die normalen sind noch harmlose Schoßtierchen im Vergleich zu ihrer Matriarchin, Schwarzkralle der Wilden.\n\nMein Cousin wurde von ihr gefressen. Das war kein schöner Anblick. Ich habe an diesem Tag geschworen, dass Schwarzkralle dafür bezahlen wird. Bringt mir einen Beweis für den Tod dieses Monsters, und ich werde Euch meine Ersparnisse dafür geben. Einverstanden?\n\nIhr findet das Biest in einer Höhle in der Großen Kluft. Viel Erfolg!", sourceObjective = "Besorgt Schwarzkralles Klauen von Schwarzkralle der Wilden in der Großen Kluft und bringt sie zu Ikan beim Tempel von Telhamat auf der Höllenfeuerhalbinsel.", progress = "Habt Ihr schon einen Beweis für Schwarzkralles Tod, {name}?", completion = "Ja, an diese scharfen Krallen erinnere ich mich genau!\n\nNehmt diese Belohnung, {name}. Ihr habt eine gefährliche Aufgabe erledigt. Ihr habt Euch jedes einzelne Stück hiervon verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[9491] = { id = 9491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gier", description = "Ein reicher, und wenn ich sage 'reich', meine ich 'stinkreicher' Händler kam gestern hier vorbei und erzählte etwas über einen Ring von 'immenser archäologischer Bedeutung', der in einer der zahllosen Grabtruhen in den Amanikatakomben eingeschlossen ist. Wenn er nicht über den Ring sprach, dann darüber, wie viel er dafür bezahlen würde.\n\nIch könnte Euch Diebeswerkzeug vorstrecken, und wenn es Euch gelingt, mir den Ring zu bringen, zahle ich Euch so viel, dass ihr zehn Ringe für Euch selbst kaufen könnt!", sourceObjective = "Eralan in Tristessa möchte, dass Ihr ihr einen gekörnten Goldring aus den Amanikatakomben bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9492] = { id = 9492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal wenden", description = "Die weiterhin bestehende orcische Bedrohung ist eine der traurigen Wahrheiten der Scherbenwelt. Es gab eine Zeit, in der wir Söhne des Lothars glaubten, dass wir die Sicherheit der Ehrenfeste mit unserem Blut erkauft haben, aber es sollte keinen Frieden geben.\n\nDie Söhne werden sich keinem Orc fügen - ob er nun grün, braun oder eben rot sein mag - wir werden sie besiegen oder bei dem Versuch sterben. Wenn wir eine Chance auf den Sieg haben wollen, müssen wir sie in der Höllenfeuerzitadelle bekämpfen. Bringt mir die Waffe ihres selbsternannten Kriegshäuptlings Kargath Messerfaust, und ich werde Euch reich belohnen.", sourceObjective = "Bringt Kriegshäuptling Kargaths Faust zu Truppenkommandant Danath Trollbann in der Ehrenfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[9493] = { id = 9493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stolz der Höllenhorde", description = "Wir wissen herzlich wenig über die Höllenhorde in der Höllenfeuerzitadelle, und die Informationen, die wir haben, wurden teuer mit Blut bezahlt.\n\nDie Truppen der Höllenhorde unter dem Kommando von Kargath Messerfaust sind ein blutrünstiger, schlachterprobter Haufen, der von bösartigen Magiern unterstützt wird. Die Elite dieser Streitkräfte, die Legionäre, Champions und Zenturios der Zerschmetterten Hand, werden von den gewöhnlichen Soldaten gefürchtet und dienen als Offiziere.\n\nAuf sie loszugehen und sie zu vernichten ist der erste wichtige Schritt für einen erfolgreichen Angriff auf die Führung der Höllenhorde.", sourceObjective = "Feldkommandant Romus in der Ehrenfeste möchte, dass Ihr 8 Legionäre der Zerschmetterten Hand, 4 Zenturios der Zerschmetterten Hand und 4 Champions der Zerschmetterten Hand tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[9494] = { id = 9494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsglut", description = "Die altmodischen Akademiker Azeroths haben sich schon viel zu lange in ihren Türmen versteckt. Jetzt ist es an mir, ihnen zu zeigen, was hochmoderne Forschung bedeutet! Sie haben Angst, mit dem Feuer zu spielen, und genau das werde ich tun! Das heißt, sobald ich dieses Feuer in die Finger bekomme.\n\nIn den Zerschmetterten Hallen der Höllenfeuerzitadelle vollbringt der Großhexenmeister Nethekurse unerreichte magische Meisterleistungen, die von der Macht einer ungewöhnlichen Kohlenpfanne noch verstärkt werden. Benutzt dieses Gefäß, um ein Stück Teufelsglut zu fangen, und bringt es zu mir, {name}.", sourceObjective = "Magus Zabraxis in der Ehrenfeste möchte, dass Ihr ihr ein Stück Teufelsglut bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9495] = { id = 9495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Will of the Warchief" }
quests[9496] = { id = 9496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pride of the Fel Horde" }
quests[9497] = { id = 9497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emblem der Höllenhorde", description = "Als der Kriegshäuptling von der so genannten Höllenhorde hörte, wurde er sowohl wütend als auch sehr traurig. Wie Rend und seine Hochstapler damals wird auch diese falsche Horde fallen, und ihr Banner wird als Zeichen für die Macht unseres Kriegshäuptlings von den Zinnen der Feste Grommasch wehen.\n\nEs liegt an Euch, in dieser Angelegenheit den Willen des Kriegshäuptlings auszuführen, {name}. Es wird nicht einfach werden, denn das Banner wird von einem Champion der Höllenhorde, bekannt als Kriegshetzer O'mrogg, bewacht. Er wird sich das Banner nicht ohne Kampf nehmen lassen.", sourceObjective = "Tötet Kriegshetzer O'mrogg und besorgt Euch das Banner der Höllenhorde. Kehrt danach zu Oberanführer Hun Stümmelfaust in Thrallmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9498] = { id = 9498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falkenwacht", description = "Mein Volk hat die Falkenwacht erst kürzlich als Operationsbasis im Südwesten der Höllenfeuerhalbinsel, hinter der Höllenfeuerzitadelle, fertiggestellt. Man wird Euch dort als Verbündeten willkommen heißen, {name}.\n\nWenn Ihr also auf der Suche nach Arbeit seid, reist dorthin und sagt Waldläuferhauptmann Venn'ren, dass ich Euch geschickt habe. Er wird Euch sicherlich eine Aufgabe zuweisen können, die Eurer Fähigkeiten würdig ist.", sourceObjective = "Meldet Euch bei Waldläuferhauptmann Venn'ren bei der Falkenwacht auf der Höllenfeuerhalbinsel.", completion = "Willkommen in der Falkenwacht, {race}. Alle Verbündeten der Horde sind hier willkommen, insbesondere all jene, mit einer Empfehlung von Martik.", sourceObjectiveStatus = "unverified-source-field" }
quests[9499] = { id = 9499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falkenwacht", description = "Was macht Ihr denn noch hier, {name}? Habt Ihr nicht gehört, dass wir einen anständigen Außenposten der Sin'dorei auf der Höllenfeuerhalbinsel errichtet haben?\n\nIhr wärt doch sicher viel lieber bei den Blutelfen als bei all diesem... Gestank hier. Ihr findet die Falkenwacht im Südwesten, hinter der Höllenfeuerzitadelle. Meldet Euch bei Waldläuferhauptmann Venn'ren, er wird sich um Euch kümmern.\n\nDie Straße dorthin ist sehr gefährlich und wird von den Spähern der Allianz überwacht. Reist lieber in Begleitung. Am besten mit Blutelfen.", sourceObjective = "Reist zur Falkenwacht im Südwesten der Höllenfeuerhalbinsel und meldet Euch bei Waldläuferhauptmann Venn'ren.", completion = "Willkommen in der Falkenwacht, Bruder. Viele andere Blutelfen haben es leider nicht geschafft, heil hier anzukommen.\n\nEs ist eine Schande. Unsere Arbeit in der Scherbenwelt hat doch gerade erst begonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9500] = { id = 9500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Es ist schon eine Weile her, seitdem Ihr das letzte Mal auf die Probe gestellt wurdet. Scharfseher Nobundo hat nach Euch gefragt. Ihr müsst sehr viel an Erfahrung gewonnen haben, da man Euch nun die Geheimnisse des Elements des Wassers lehren möchte.\n\nIhr wisst noch, dass Ihr ihn in der Kristallhalle der Exodar findet, ja?", sourceObjective = "Sprecht mit Scharfseher Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[9501] = { id = 9501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Ein mächtiger Wasserelementar namens Aqueous hat nach Euch verlangt. Anscheinend ist das Element des Wassers auf der Blutmythosinsel aus dem Gleichgewicht geraten, was bei der unnatürlichen Vorliebe der Blutelfen nicht wirklich verwunderlich ist.\n\nIhr findet Aqueous in einem versteckten Riff unter den Wogen vor der Küste im Norden der Blutmythosinsel.\n\nNehmt diesen Trank, er wird Euch auf Eurem Weg zu Aqueous behilflich sein, sobald Ihr in der Nähe des Riffs im Wasser seid.", sourceObjective = "Sprecht mit Aqueous im Versteckten Riff bei der Blutmythosinsel.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[9502] = { id = 9502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Es ist schon eine Weile her, seitdem Ihr das letzte Mal auf die Probe gestellt wurdet. Scharfseher Nobundo hat nach Euch gefragt. Ihr müsst sehr viel an Erfahrung gewonnen haben, da man Euch nun die Geheimnisse des Elements des Wassers lehren möchte.\n\nIhr wisst noch, dass Ihr ihn in der Kristallhalle der Exodar findet, ja?", sourceObjective = "Sprecht mit Scharfseher Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[9503] = { id = 9503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "In Verbindung mit den anderen Elementen ist Wasser der Quell und die Grundlage allen Lebens. Alle Kreaturen sind darauf angewiesen. Allerdings bringt das Wasser durch die Verunreinigung jetzt auch den Tod.\n\nWir müssen das Ausmaß des Schadens erfassen. Im Südwesten liegt ein derart verderbtes Gewässer, welches mittlerweile als besudelter Teich bekannt ist. Geht dorthin und besorgt Euch besudelte Essenzen von den dort lebenden Wassergeistern.", sourceObjective = "Sammelt 6 besudelte Essenzen ein und bringt sie zu Aqueous im Versteckten Riff bei der Blutmythosinsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[9504] = { id = 9504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Es ist schlimmer als ich befürchtet hatte. Die Verunreinigung ist hartnäckig und könnte, wenn man nicht rechtzeitig handelt, ungehindert in die Ströme des Meeres fließen und sich somit in ganz Azeroth ausbreiten!\n\nWir brauchen eine Probe reinsten Wassers, um diesem Übel entgegenzuwirken. Auf der nicht verunreinigten Seite dieser Insel, im Südwesten, befinden sich Ruinen. Geht dorthin, wo die Naga der Hasspranken hausen, und entwendet eine Probe aus ihrem Brunnen.\n\nNehmt diesen Botabeutel, um die Probe zu transportieren. Beeilt Euch, {name}!", sourceObjective = "Füllt den leeren Botabeutel und kehrt anschließend zu Aqueous im Versteckten Riff bei der Blutmythosinsel zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9505] = { id = 9505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prophezeiung von Velen", description = "Der Prophet sprach von diesem Tag, da auf dieser Insel, in dieser Welt, sich uns unsere Verbündeten offenbaren würden.\n\n\"Man wird uns auf die Probe stellen. Wir werden für die Sünden unserer Vorväter bezahlen...\"\n\nDamals blieb mir der Sinn seiner Worte verborgen; doch in dem Moment, als ich dieses Wesen erblickte, wurde mir die Bedeutung seiner Prophezeiung gewahr. Selbst an diesem Ort verspüre ich noch die schleichende Verderbnis unseres Volkes.\n\nBegebt Euch nach Süden, dort wo wir sie gefunden haben. Findet ihresgleichen und berichtet ihnen von unserem Volk.", sourceObjective = "Daedal möchte, dass Ihr nach Süden reist und die Personen aufsucht, von denen das verletzte Wesen gesprochen hat.", completion = "Ihr sagt, dass Ihr eines unserer Besatzungsmitglieder gefunden habt und dass sie schwer verletzt ist? Ich werde umgehend ein Mitglied meiner Besatzung in Euer Dorf entsenden!", sourceObjectiveStatus = "unverified-source-field" }
quests[9506] = { id = 9506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kleiner Anfang", description = "Ich bin Admiral Odesyus vom Marinekommando der Allianz. Eine Plage der besonderen Art zwang uns dazu, an der Küste Eurer Insel vor Anker zu gehen. Es beschämt mich das sagen zu müssen, doch ein paar Goblins haben es irgendwie geschafft, sich als blinde Passagiere in den Frachträumen unserer beiden Schiffe zu verstecken.\n\nLetzte Nacht, als der Großteil der Schiffsmannschaften in den Kojen lag, schlugen sie zu!\n\nSie stahlen unsere Navigationsinstrumente und sprangen von Bord!\n\nAnschließend verschwanden sie im Dickicht, östlich von hier. Werdet Ihr uns bei der Suche nach den Instrumenten behilflich sein? Es wäre eine großzügige Geste von Euch.", sourceObjective = "Admiral Odesyus bei Odesyus' Ankerplatz möchte, dass Ihr den von der Venture Co. gestohlenen nautischen Kompass und die nautische Karte wiederbeschafft.", progress = "Hattet Ihr Erfolg, Fremder?", completion = "Ihr seid verdammt einfallsreich! Jetzt, da wir unsere Navigationsinstrumente zurückerhalten haben, sollte es leicht sein, herauszufinden, wie weit wir vom Kurs abgekommen sind.\n\nAber wartet, was ist das? Da ist etwas in der Karte eingerollt. Lasst mich mal sehen...\n\nDas sind Befehle von Mogul Raztunk der Venture Company. Laut diesen Plänen sind sie hier, um die Insel ihrer Kristalle zu berauben und unsere Schiffe zu kapern, wenn sie fertig sind!\n\nBei Bronzebarts buschiger Braue! Deswegen haben sie uns an Land gezwungen? Wie konnten sie von unseren Plänen erfahren?\n\nDas riecht nach einem Verräter...", sourceObjectiveStatus = "unverified-source-field" }
quests[9507] = { id = 9507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Mogul Ratztunks Schreibtisch", description = "Die Goblins sind diesen Plänen zufolge wegen der Kristalltrümmer der Exodar hier. Es scheint so, als beabsichtigten die Goblins, die Kristalle auf der gesamten Insel abzubauen und die zwei Schiffe der Allianz, die abseits der Küste angelegt haben, zu entführen, sobald sie ihre Pläne in die Tat umgesetzt haben.\n\nIhr solltet diese Pläne besser zu Admiral Odesyus bringen.", sourceObjective = "Bringt die streng geheimen Pläne der Venture Company zu Admiral Odesyus bei Odesyus' Ankerplatz.", sourceObjectiveStatus = "unverified-source-field" }
quests[9508] = { id = 9508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Ich habe den Ursprung der Verunreinigung gefunden. Es ist das Nebenprodukt eines wahnsinnigen Experiments und Ihr werdet dem Ganzen ein Ende bereiten!\n\nSüdwestlich des Besudelten Teichs liegt ein kleines Lager, wo Ihr auf das 'Experiment' von Tel'athion dem Unreinen stoßen werdet. An diesem Ort erzeugt er den Unrat und lässt ihn in die Gewässer der Insel sickern.\n\nVerwendet das reine Wasser aus dem Eschental, um seine Fässer zu zerstören. Das wird ihn sicherlich aus seinem Versteck locken.\n\nWir werden das alles ein für alle Mal beenden!", sourceObjective = "Bringt Tel'athions Kopf zu Aqueous im Versteckten Riff bei der Blutmythosinsel zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9509] = { id = 9509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Ich habe etwas von dem Wasser aus dem Eschental beiseite gelegt, jedoch nicht, weil ich an Euren Fähigkeiten, die Situation in den Griff zu bekommen, gezweifelt habe. Im Gegenteil, ich wusste, dass Ihr Erfolg haben würdet. Ich wollte lediglich sicherstellen, dass Ihr etwas Besonderes habt, das Ihr zurück zu Nobundo bringen könnt.\n\nHier, {name}, nehmt dieses Fläschchen mit reinstem Wasser. Die Erstellung eines mächtigen Wassertotems ist Euch dadurch gewiss.\n\nScharfseher Nobundo erwartet Eure Rückkehr bei der Exodar.Ihr erlernt:", sourceObjective = "Nehmt das Fläschchen mit reinstem Wasser zu Scharfseher Nobundo innerhalb der Exodar auf der Azurmythosinsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[9510] = { id = 9510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bälge eines borstigen Grollhufs", description = "Ihr wollt Euch also nützlich machen? Unsere Vorräte an Grollhufbälgen sind sehr knapp, {name}.\n\nWenn Ihr von hier aus nach Südwesten geht, werdet Ihr in der Nähe der Falkenwacht haufenweise borstige Grollhufe finden. Ihre Bälge sind ideal für die Lederverarbeitung. Bringt mir einen Stapel davon und ich werde Euch angemessen belohnen.", sourceObjective = "Versorger Braknar beim Mag'harposten auf der Höllenfeuerhalbinsel möchte, dass Ihr ihm 5 Bälge eines borstigen Grollhufs bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9511] = { id = 9511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kargaths Schlachtpläne", description = "Die Dokumente, die Ihr bei Kargath gefunden habt, enthalten genaue Pläne für einen großen Angriff auf die Ehrenfeste." }
quests[9512] = { id = 9512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kräckas Jumboeintopf", description = "Der Admiral hat wohl Recht, Ihr seid ziemlich clever. Könnt Ihr Kräcka vielleicht aushelfen?\n\nWenn ich der Mannschaft noch einmal Hühnchen vorsetze, werden'se mich sicher kielholen.\n\nHab' gesehen, dass es an der Küste nur so von Kriechern wimmelt! Bringt mir Kriecherfleisch und ich steh' für immer in Eurer Schuld.\n\nHelft Ihr 'nem ehemaligen Piraten aus der Patsche?", sourceObjective = "\"Kräcka\" Aschebäscha bei Odesyus' Ankerplatz möchte, dass Ihr ihm 6 Stücke Raubkriecherfleisch bringt.", progress = "Arrr... Jarr... beim Klabautermann... Eh, 'tschuldigung Junge, ich muss mal wieder 'n bisschen Pirat spielen, bevor ich's ganz vergesse...", completion = "Erste Sahne, Fremder. Das wird helfen, die Moral der Mannschaft wieder mächtig aufzumöbeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[9513] = { id = 9513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückeroberung der Ruinen", description = "Während einige glauben, dass unsere momentane Lage das Resultat einer langen Kette von unglücklichen Ereignissen ist, glaube ich vielmehr, dass wir aus einem bestimmten Grund hier sind. Die unsichtbare Hand des Schicksals hat uns an diesen Ort verschlagen. Die Gründe dafür werden sich uns im Laufe der Zeit offenbaren.\n\nIm Westen liegt eine uralte Stadt der Nachtelfen, heute sind es nur noch von Naga besetzte Ruinen. Ich wäre nachlässig, würde ich tatenlos zusehen, wie die Naga weiterhin das Land meiner Vorfahren mit ihrer Anwesenheit beflecken.\n\nIhr habt Eure Fähigkeiten als {class} unter Beweis gestellt. Nun ehrt mein Volk und reinigt diese Ruinen von seinen unrechtmäßigen Einwohnern.", sourceObjective = "Priesterin Kyleen Il'dinare bei Odesyus' Ankerplatz auf der Azurmythosinsel möchte, dass Ihr 5 Myrmidonen der Hasspranken, 5 Naga der Hasspranken und 5 Sirenen der Hasspranken tötet.", completion = "Gelobt sei Elune! Mögen die ruhelosen Geister endlich Frieden finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9514] = { id = 9514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runenbesetzte Schrifttafel", description = "Es gelingt Euch nicht, die Symbole auf der Schrifttafel zu entziffern. Vielleicht ist die Priesterin in der Lage, die mysteriösen Runen zu entschlüsseln.", sourceObjective = "Bringt die runenbesetzte Schrifttafel zu Priesterin Kyleen Il'dinare bei Odesyus' Ankerplatz auf der Azurmythosinsel.", progress = "Ihr habt etwas entdeckt?", completion = "Ich kann diese Runen leider nicht entziffern, doch ich kenne jemanden, der dies zu tun vermag...", sourceObjectiveStatus = "unverified-source-field" }
quests[9515] = { id = 9515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsherr Sriss'tiz", description = "Eine Nagainvasion wäre ein Desaster, {name}. Ich habe gesehen, was diese Naga anrichten können und ich werde es nicht zulassen, dass sie weiter über unschuldige Wesen herfallen. Ich nehme an, dass dieser Kriegsherr Sriss'tiz sich in einer Höhle versteckt - möglicherweise irgendwo an der Küste im Westen.\n\nMacht Kriegsherr Sriss'tiz ausfindig und beendet seine Herrschaft für immer!", sourceObjective = "Priesterin Kyleen Il'dinare bei Odesyus' Ankerplatz auf der Azurmythosinsel möchte, dass Ihr Kriegsherr Sriss'tiz tötet.", completion = "Nach dem Tod von Kriegsherr Sriss'tiz dürfte die Gefahr einer Nagainvasion fürs Erste gebannt sein...\n\nIch muss gestehen, es war falsch von mir, so schlecht über Euch zu denken, {name}. Ihr habt bewiesen, dass Ihr weit entfernt seid vom Abschaum, der sich Archimonde nannte. Bitte nehmt dieses Geschenk der Nachtelfen als ein Zeichen der Freundschaft entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9516] = { id = 9516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerstört die Legion", description = "Ich werde Ihre Existenz in dieser Welt nicht tolerieren! Die Brennende Legion hat unser Volk fast ausgerottet, und wir mussten ein neues Zuhause in einer neuen Welt suchen. Dann kamen sie erneut. Und wir haben uns zurückgezogen, immer und immer wieder.\n\nNie wieder!\n\nIm Süden gibt es noch ein Überbleibsel der Legion, in den Regionen, die als Dämonenhügel, Dämonensturz und Dämonenstieg bekannt sind. Sie sind von dieser Macht, die einst in Eure Welt eingedrungen ist, übriggeblieben.\n\nGeht und zerstört so viele von ihnen, wie Ihr könnt, bevor es zu spät ist!", sourceObjective = "Tötet 15 Dämonen auf dem Dämonenhügel, dem Dämonensturz und dem Dämonenstieg.", sourceObjectiveStatus = "unverified-source-field" }
quests[9517] = { id = 9517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine schändliche Verschwendung", description = "Willkommen in Waldeslied, {class}. Wo Ihr jetzt noch Zelte seht, werden einst Gebäude stehen, aber dieses Ziel erfordert einen ständigen Nachschub an Baumaterial. Ich bringe es nicht übers Herz, unseren Arbeitern zu befehlen, die uralten Bäume dieses Hains zu fällen, aber unsere Nachbarn im Süden und Westen haben keine so große Ehrfurcht vor dem Wald.\n\nWir werden das verdorbene Holz aus der Festung der Satyrn im Westen zurückfordern. Bringt das Holz zu Knorre im Holzfällerlager des Kriegshymnenklans. Er ist ein Urtum, der es für unsere Zwecke reinigen wird.", sourceObjective = "Sammelt 5 Stück verdorbenes Satyrnaarholz.", sourceObjectiveStatus = "unverified-source-field" }
quests[9518] = { id = 9518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agenten der Zerstörung", description = "Das Holzfällerlager des Kriegshymnenklans ist ein Schandfleck in unserer Landschaft. Wann immer wir Fortschritte dabei machen, ihre Arbeiten zu stoppen, befiehlt Vorarbeiter Gorthak seinen Holzarbeitern, ihre Anstrengungen noch zu verdoppeln!\n\nJetzt fällen die Orcs mehr Holz, als sie je verbrauchen können und lassen es verrotten, während ihre Klingen schon wieder in frisches Holz schlagen! Dies ist eine Beleidigung gegenüber allem, für das wir einstehen, {name}, und wir werden ihnen zeigen, dass wir uns eine weitere Zerstörung unseres Landes nicht gefallen lassen!\n\nGeht, und ruht nicht, bevor Vorarbeiter Gorthak und seine Lakaien tot sind!", sourceObjective = "Tötet Vorarbeiter Gorthak und 12 weitere, beliebige Mitglieder der Horde im Holzfällerlager des Kriegshymnenklans.", sourceObjectiveStatus = "unverified-source-field" }
quests[9519] = { id = 9519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elunes Kelch", description = "Das Gebiet westlich von hier, das nun Satyrnaar heißt, war einst ein bedeutender Schrein meines Volkes. Dort befand sich ein Relikt von unschätzbarem Wert, Elunes Kelch, der den Hütern des Schreins von den Priestern Elunes anvertraut wurde. Einst reisten Pilger zu dem Schrein, um die heilenden Kräfte, die dem Kelch nachgesagt wurden, am eigenen Leib zu erfahren.\n\nVielleicht sind diese Geschichten nur Ammenmärchen, aber wenn nur ein Körnchen Wahrheit in ihnen steckt, könnte der Kelch vielleicht der Schlüssel zur Wiederherstellung unseres leidenden Waldes sein. Ich muss es wissen, {name}.", sourceObjective = "Bringt Elunes Kelch in Euren Besitz.", sourceObjectiveStatus = "unverified-source-field" }
quests[9520] = { id = 9520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teuflische Pläne", description = "Der Dämon hat dieses Pergament fallenlassen, welches überraschenderweise in der Allgemeinsprache verfasst wurde! Darin werden Diathorus und Gorgannon erwähnt, zwei berüchtigte Schreckenslords, die die Dämonen in dieser Gegend befehligen.\n\nDie Pläne enthalten genaue Vorbereitungen für einen dämonischen Angriff auf Waldeslied im Norden, wo gerade eine neue Draeneisiedlung errichtet wird.\n\nVielleicht ist Verteidiger Vedaar im Holzfällerlager des Kriegshymnenklans daran interessiert?", sourceObjective = "Bringt die teuflischen Pläne zu Verteidiger Vedaar im Holzfällerlager des Kriegshymnenklans im Eschental.", sourceObjectiveStatus = "unverified-source-field" }
quests[9521] = { id = 9521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht von der Nordfront", description = "Die Schlacht gegen das Holzfällerlager des Kriegshymnenklans wird nicht nur vom Rajenbaumturm aus geführt, {name}. Eine beträchtliche Anzahl von Schildwachen der Silberschwingen hat sich im Hain der Silberschwingen, in der Nähe der Grenze zum Brachland, postiert. Schildwache Weltensang ist für unsere Bemühungen gegen die, die unser Land zerstören wollen, verantwortlich.\n\nIch bin mit meinem Bericht an Schildwache Weltensang etwas spät dran, möchte aber den Turm nur ungern unbewacht lassen. Wenn Eure Reisen Euch in die Nähe des Silberschwingenhains bringen, könntet Ihr dann meinen Bericht abgeben?", sourceObjective = "Bringt Schildwache Melyrias Bericht zu Schildwache Weltensang im Hain der Silberschwingen im Eschental.", sourceObjectiveStatus = "unverified-source-field" }
quests[9522] = { id = 9522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nie wieder!", description = "{name}, es ist Eure Aufgabe dafür zu sorgen, dass dieser Angriff der Brennenden Legion niemals stattfindet. Ihr müsst losziehen und ihre Anführer erschlagen. Ohne sie ist der Rest der Dämonen nur ein Haufen geistloser Untiere.\n\nIhr findet Gorgannon im Dämonensturz südlich hinter dem Dämonenhügel in der Nähe des schwebenden Speers von Mannoroth.\n\nDiathorus der Sucher lebt irgendwo im Grabhügel auf dem Dämonensturz. Um dort hinaufzugelangen, sucht nach einem Stieg in der Nähe des Denkmals der Horde für Grom Höllschrei.\n\nBringt mir ihre Waffen.", sourceObjective = "Erhaltet Gorgannons flammende Klinge und den Teufelsspeer des Suchers.", sourceObjectiveStatus = "unverified-source-field" }
quests[9523] = { id = 9523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marmor, Stein und Eisen bricht, aber uralte Nachtelfenrelikte nicht...", description = "Die Priesterin sagte mir, dass die Ruinen im Westen die Überreste einer Nachtelfenkultur sind. Das erinnerte mich wiederum an etwas, was mein Paps immer über Nachtelfenruinen zu sagen pflegte: \"Kleiner, wenn du Nachtelfenruinen siehst, dann sind bestimmt auch Nachtelfenrelikte in der Nähe.\"\n\nWas für ein Zwerg wäre ich wohl, wenn ich nicht die erste Person anstellen würde, die mir über den Weg läuft, um für mich nach Nachtelfenrelikten zu graben? Los jetzt!", sourceObjective = "Archäologe Adamant Eisenherz bei Odesyus' Ankerplatz möchte, dass Ihr ihm 8 uralte Relikte bringt.", progress = "Kommt nicht ohne uralte Relikte zurück.", completion = "Mein Paps wäre stolz! Sein Junge hat bei den ersten Nachtelfenruinen, auf die er gestoßen ist, das große Los gezogen... dank Eurer Hilfe natürlich. Ja, macht Euch keine Sorgen, ich werde Euch nicht von der Entdeckung ausschließen. Euer Name ist {name}, stimmt's? In Eisenschmiede werden alle von Euch hören.", sourceObjectiveStatus = "unverified-source-field" }
quests[9524] = { id = 9524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangene der Zitadelle", description = "Allianztruppen, hier?! Hört mir genau zu, {class}.\n\nKargath hat viele unserer Kämpfer gefangen genommen. Unter ihnen ist auch Hauptmann Alina, einer unserer wichtigsten Offiziere. Rettet sie, bevor sie hingerichtet wird.\n\nMacht Euch um mich keine Sorgen, ich komme hier schon heraus, lasst mich nur etwas Luft schnappen.", sourceObjective = "Rettet Hauptmann Alina aus der Höllenfeuerzitadelle, bevor sie hingerichtet wird.\n\nUm diese Aufgabe zu beenden, müsst Ihr den Dungeon auf dem Schwierigkeitsgrad 'Heroisch' betreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9525] = { id = 9525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imprisoned in the Citadel" }
quests[9526] = { id = 9526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückeroberung des Dämonenhügels", description = "Kleines Wesen. Im Süden gibt es ein Gebiet im Nachtweisenwald, das seit kurzer Zeit Dämonenhügel genannt wird. Es ist sehr traurig zu sehen, wie die Dämonen auf ihm herumkrabbeln und ihre Verderbnis verbreiten.\n\nWürdet Ihr etwas tun, um dabei zu helfen, das Land zurückzuerobern?\n\nIch habe ein paar Samen, die ich für eine solche Gelegenheit aufgehoben habe. Bringt sie zum Dämonenhügel und pflanzt sie in fruchtbare Erdhaufen.", sourceObjective = "Pflanzt 8 Baumsetzlinge in die fruchtbaren Erdhaufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9527] = { id = 9527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was noch bleibt", description = "Wir lebten viele Jahre in Frieden mit den Kreaturen dieser Insel. Ihr könnt Euch vorstellen, wie überrascht ich war, als sie den Strand stürmten und uns angriffen.\n\nIch habe mich mit Händen und Füßen gewehrt, wurde aber sofort überwältigt. Als ich auf Grund der zahlreichen Schläge in Ohnmacht fiel, betete ich, dass meine Familie nicht leiden muss.\n\nIch erwachte und alles war ruhig. Der Sand war rot, vor Blut getränkt - mit ihrem Blut. Man hatte sie vollständig verschlungen.\n\nIch sehne mich nicht nach Rache, {name}. Ich wünsche mir nur, dass man mir ihre Überreste bringt, damit ich sie ordnungsgemäß bestatten kann.", sourceObjective = "Cowlen auf der Azurmythosinsel möchte, dass Ihr ihm die Überreste von Cowlens Familie bringt.", progress = "Meine Frau hieß Thalrisa und meine Tochter Magwin.", completion = "Ich danke Euch, {name}. Ihre Geister können nun in Frieden ruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9528] = { id = 9528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Hilferuf", description = "Meine Familie wurde vor einigen Wochen von den Murlocs und Eulkin dieser Insel überfallen. Ich schaffte es zu fliehen, aber ich glaube, dass mein Vater und meine Mutter getötet wurden. Ich weiß nicht, was ich jetzt tun soll, aber ich muss versuchen, zurück zu meinem Zuhause zu gehen - oder was davon übrig ist... Könnt Ihr mich durch den Wald begleiten?", sourceObjective = "Begleitet Magwin über die Insel zu ihrem Zuhause.", completion = "<Freudentränen strömen über Cowlens Gesicht.>\n\nWie kann ich Euch dafür jemals genug danken, {name}? Bitte, nehmt dieses Erbstück. Es symbolisiert die heiligen Bande der Freundschaft sowie das Vertrauen und die Verbundenheit zwischen den Nachtelfen. Ihr seid wie ein Bruder für mich - vom heutigen Tag bis in alle Ewigkeit...", sourceObjectiveStatus = "unverified-source-field" }
quests[9529] = { id = 9529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stein", description = "Ich bin mir sicher, dass Euer Wichtel sich als nützlicher und manchmal auch unterhaltsamer Begleiter bewiesen hat. Es ist jetzt an der Zeit, dass Ihr einen mächtigeren Dämonen zu beherrschen lernt: den Leerwandler.\n\nReist bis zu dem Punkt der Todesschneise, an dem sie vom Elrendar gekreuzt wird. Macht direkt südlich vom Fluss einen der blauen glühenden Steine ausfindig und nehmt ihn. Euer Weg wird sich Euch dort offenbaren.", sourceObjective = "Beschafft Euch einen Leerstein von der Todesschneise.", sourceObjectiveStatus = "unverified-source-field" }
quests[9530] = { id = 9530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Plan aus Hecken", description = "Ich habe eine ganze Zeit nun darüber gegrübelt, aber es stellt sich als wahr heraus.\n\nEs gibt einen Verräter unter uns.\n\nDie Pläne, die von den Goblins zurückgelassen wurden, bestätigen diesen Komplott. Da ich nicht weiß, wer es sein könnte, benötige ich Eure Hilfe, um den Verräter auszumachen. Keinem aus meiner Mannschaft kann vertraut werden.\n\nFür ein gelungenes Unterfangen benötige ich einen ausgehöhlten Stamm und Laub. Sucht in der Nähe der Holzarbeiter nördlich von uns nach dem Baumstamm. Das Laub müsst Ihr selbst auftreiben. Durchforstet den Wald.", sourceObjective = "Admiral Odesyus bei Odesyus' Ankerplatz auf der Azurmythosinsel möchte, dass Ihr ihm einen ausgehöhlten Stamm und 5 Laubhaufen bringt.", progress = "Ich liebe es, wenn ein Plan aufgeht...", completion = "Ich muss Euch warnen: Das, was ich als Nächstes von Euch verlangen werde, ist sehr gefährlich. Ich würde es Euch nicht verdenken, wenn Ihr mir dabei lieber nicht aushelfen wollt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9531] = { id = 9531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Laubangriff", description = "Der Verräter wird sich den Plänen zufolge mit dem Anführer der Goblins, Geezle, bei einer Bucht auf der westlichen Insel treffen. Ihr müsst zu diesem Treffen gehen, {name}.\n\nErinnert Ihr Euch an den Stamm und das Laub? Ihr müsst Euch damit verkleiden! Es ist die perfekte Tarnung.\n\nGeht zur Bucht und haltet nach einer Nagaflagge Ausschau. Seht Ihr die Flagge, so wurde ein Treffen arrangiert. Legt die Verkleidung an, wenn Ihr die Flagge seht, und wartet. Der Verräter wird sich früher oder später zeigen. Lasst das Treffen enden und kehrt anschließend mit der Identität des Schufts zu mir zurück.", sourceObjective = "Admiral Odesyus bei Odesyus' Ankerplatz auf der Azurmythosinsel möchte, dass Ihr das Treffen beobachtet, das Geezle und der Verräter gemeinsam ausgemacht haben.\n\nKehrt zu ihm zurück, wenn Ihr ihm die Identität des Verräters mitteilen könnt.", progress = "Der Verräter wird noch bereuen, dass er sich mit dem Marinekommando der Allianz angelegt hat!", completion = "Ich kann es nicht glauben! Der Gnom war es, die ganze Zeit über... Ich hätte es wissen sollen!", sourceObjectiveStatus = "unverified-source-field" }
quests[9532] = { id = 9532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet Keltus Dunkellaub", description = "{name}, einer unserer Späher nimmt seine Pflichten ein wenig zu ernst. Er bewacht unsere Feinde ohne Unterlass, erstattet uns aber keine Berichte darüber.\n\nIhr müsst diesen Spion, Keltus Dunkellaub, finden und überzeugen, damit er seinen Bericht aushändigt und so schnell wie möglich zu mir zurückkommt. Ihr findet ihn weit im Südwesten, wo der Elrendar sich teilt und um Goldnebel herum fließt. Er beobachtet die Nachtelfen von An'daroth und hält sich sicher in ihrer Nähe auf.", sourceObjective = "Macht Keltus Dunkellaub ausfindig.", sourceObjectiveStatus = "unverified-source-field" }
quests[9533] = { id = 9533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine helfende Hand", description = "Meine Leute haben im Osten des Eschentals mithilfe der Kaldorei eine wichtige Entdeckung gemacht.\n\nUnter der Aufsicht von Architekt Nemos und Verteidiger Vedaar erneuern sie einen alten elfischen Außenposten. Der Wiederaufbau wird nicht leicht werden, {name}, denn sie stehen vielen Herausforderungen und Feinden gegenüber. Ich weiß, dass Architekt Nemos und seine Landsleute in Waldeslied jede Hilfe, die sie bekommen können, zu schätzen wissen, und er bat mich, <jeden Mann, der/jede Frau> die; Interesse hat, zu ihm zu schicken.", sourceObjective = "Geht nach Waldeslied im Eschental und sprecht mit Architekt Nemos.\n\nVerteidigerin Palanaar kann Euch ein Reittier anbieten, um schneller dorthin zu gelangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9534] = { id = 9534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroy the Legion" }
quests[9535] = { id = 9535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diabolical Plans" }
quests[9536] = { id = 9536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never Again!" }
quests[9537] = { id = 9537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Gnade mit dem Gnom", description = "Wir müssen uns Funks vornehmen!\n\nGeht zum Strand und sucht nach diesem betrügerischen Gnom. Quetscht so viele Informationen wie möglich aus ihm heraus!\n\nWer weiß, wie viele andere ebenfalls ein faules Spiel treiben, wenn schon ein hochrangiger Beamter der Allianz solch verräterische Taten begangen hat?\n\nUnd {name}, wendet Gewalt an, wenn es nicht anders geht...", sourceObjective = "Admiral Odesyus bei Odesyus' Ankerplatz möchte, dass Ihr die Mitteilung des Verräters von Ingenieur \"Funks\" Oberschleif an Euch bringt.", progress = "Habt Ihr den elenden Lügner gefunden?", completion = "Unglaublich! Das gehörte alles zu ihrem perfiden Plan!\n\nIhr müsst diese Informationen dem König und Euren eigenen Anführern zukommen lassen. Die Folgen sind erschütternd.", sourceObjectiveStatus = "unverified-source-field" }
quests[9538] = { id = 9538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erlernen der Sprache", description = "Ich glaube, ich hab's, {name}!\n\n<Aurren zeigt auf das Totem.>\n\nAlles, was wir über die Sprache der Furbolgs der Tannenruhfeste wissen müssen, ist auf ihren Totems verzeichnet. Wenn wir den grundlegenden Aufbau der Symbole verstehen, können wir die Totems studieren und somit lernen, mit den Furbolgs zu kommunizieren.\n\nIch habe das Grundmuster der Symbole auf dieses Pergament gezeichnet. Studiert es und untersucht dann das Totem. Es sollte Euch zu dem nächsten Sprachtotem führen.\n\nSprecht mit Arugoo, wenn Ihr als <gelehrter/gelehrte:r> {race} zurückkehrt!", sourceObjective = "Lest die Übersetzungsfibel der Tannenruhfeste, die Aurren Euch gegeben hat. Kommuniziert anschließend mit dem Totem von Akida bei der Azurwacht.", progress = "Ihr könnt ein dunkles Brummen hören, das von dem Totem ausgeht.", completion = "Das Totem weist zahlreiche Symbole der Fibel auf. Ihr könnt Eulen, Bären, Wölfe und Hirsche erkennen, die darauf eingraviert wurden.\n\nEuch fällt eine seltsame Ansammlung von Symbolen auf, die Eure Lippen das Wort A-K-I-D-A formen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9539] = { id = 9539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totem von Coo", description = "Ihr beginnt das Totem zu entschlüsseln, die komplizierten Begriffe lassen sich kaum aussprechen. Langsam formen sich Worte in Eurem Kopf. Das Totem scheint Euch sagen zu wollen: Geht auf dem nahegelegenen Hügel nach oben, Richtung Nordosten.", sourceObjective = "Findet das Totem von Coo, indem Ihr den Hinweisen folgt.", completion = "Das Totem weist zahlreiche Symbole der Fibel auf. Ihr könnt Eulen, Bären, Wölfe und Hirsche erkennen, die darauf eingraviert wurden.\n\nEuch fällt eine seltsame Ansammlung von Symbolen auf, die Eure Lippen das Wort C-O-O formen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9540] = { id = 9540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totem von Tikti", description = "Ihr beginnt das Totem zu entschlüsseln, die Begriffe lassen sich bereits etwas leichter aussprechen. Worte formen sich in Eurem Kopf. Das Totem scheint Euch sagen zu wollen: Überquert den Kristallfluss Richtung Osten. Vielleicht liegt Euer Ziel ja auf der anderen Uferseite des Flusses.", sourceObjective = "Findet das Totem von Tikti, indem Ihr den Hinweisen folgt.", completion = "Das Totem weist zahlreiche Symbole der Fibel auf. Ihr könnt Eulen, Bären, Wölfe und Hirsche erkennen, die darauf eingraviert wurden.\n\nEuch fällt eine seltsame Ansammlung von Symbolen auf, die Eure Lippen das Wort T-I-K-T-I formen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9541] = { id = 9541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totem von Yor", description = "Die Symbole des Totems scheinen sich viel schneller entschlüsseln zu lassen. Die Begriffe ergeben rasch einen Sinn. Ihr seid ziemlich sicher, dass das Totem Euch auf etwas den Fluss herab im Süden verweist. Etwas muss auf dem Grund des Flusses selbst liegen.", sourceObjective = "Findet das Totem von Yor, indem Ihr den Hinweisen folgt.", completion = "Das Totem weist zahlreiche Symbole der Fibel auf. Ihr könnt Eulen, Bären, Wölfe und Hirsche erkennen, die darauf eingraviert wurden.\n\nEuch fällt eine seltsame Ansammlung von Symbolen auf, die Eure Lippen das Wort Y-O-R formen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9542] = { id = 9542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totem von Vark", description = "Die Symbole auf dem Totem lassen sich jetzt ganz einfach lesen. Es ist, als wäre die Beschriftung auf dem Totem von Yor in Eurer Muttersprache verfasst worden.\n\nDie Hinweise deuten auf einen anderen Furbolgbau im Westen hin. Ihr entschlüsselt meisterhaft die Sprache auf dem Totem und wisst, dass Euer Ziel das Dorf der Sichelklauen ist. Yor wird Euch dorthin führen, falls Ihr Euch dennoch verlaufen solltet, wisst Ihr, dass Ihr die alte Elfenstraße im Wald nehmen könnt, die Richtung Westen zu Eurem Ziel führt.", sourceObjective = "Findet das Totem von Vark, indem Ihr den Hinweisen folgt.", completion = "Beim Lesen des Totems formen Eure Lippen das Wort V-A-R-K. Ihr versteht die Bedeutung, sie lautet Gerechtigkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[9543] = { id = 9543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sühne", description = "Unsere Vergangenheit mit den Orcs ist gezeichnet von andauernden Konflikten, {name}. Einst hätten sie uns im Blutrausch beinahe vollständig ausgelöscht und selbst als der dämonische Einfluss von ihnen wich, haben wir uns weiter von den Orcs fern gehalten.\n\nTrotz dieser Vergangenheit... das Letzte, was Sedai gewollt hätte, wäre Rache und Blutvergießen. Sprecht mit unserem Ältesten, Amaan dem Weisen. Ihm wird es gelingen, Licht in diese Ereignisse zu bringen.", sourceObjective = "Sprecht mit Amaan dem Weisen beim Tempel von Telhamat auf der Höllenfeuerhalbinsel.", completion = "Wie kann ich Euch behilflich sein, {name}? Ihr klingt, als hättet Ihr Sorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9544] = { id = 9544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prophezeiung von Akida", description = "Die Abbildungen auf dem Totem stellen einen Krieg zwischen dem Furbolgstamm der Tannenruhfeste und dem der Sichelklauen dar. Die Motive zeigen Gräueltaten, die die Sichelklauen den Furbolgs der Tannenruhfeste angetan haben.\n\nInmitten des Chaos wird eine Prophezeiung offenbart: Ein Held wird kommen - in seinen Adern fließt kein Furbolgblut - er wird den Stamm der Tannenruhfeste erretten.\n\nTötet die Furbolgs der Sichelklauen im Dorf der Sichelklauen für ihre Schlüssel. Verwendet diese Schlüssel, um gefangene Furbolgs der Tannenruhfeste zu befreien. Sobald Ihr alle befreit habt, kehrt zu Arugoo der Tannenruhfeste zurück.", sourceObjective = "Befreit 8 gefangene Furbolgs der Tannenruhfeste aus den Käfigen im Dorf der Sichelklauen. Kehrt anschließend zu Arugoo der Tannenruhfeste bei der Azurwacht zurück.", completion = "[Furbolg] Die Prophezeiung sprach von jemandem, der sich erheben und uns aus dem gewaltsamen Griff der Sichelklauen befreien würde; dass die Geister selbst die Ankunft dieses Helden verkünden würden.\n\nJetzt seid Ihr gekommen.\n\nIch beuge mich vor Euch in Demut, Großartiger.", sourceObjectiveStatus = "unverified-source-field" }
quests[9545] = { id = 9545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Relikt des Sehers", description = "Die Störrischen unter uns verschließen ihren Geist und glauben an die eine Wahrheit. Der Weise jedoch, hat ein offenes Ohr für die Existenz unterschiedlicher Möglichkeiten, die letztlich zur Gegenwart führen, oder von ihr ausgehen.\n\nBringt dieses Relikt zu dem Ort, an dem Ihr Sedai gefunden habt. Seht nicht mit Euren Augen, {name}, sondern mit Eurem Verstand.", sourceObjective = "Amaan der Weise beim Tempel von Telhamat auf der Höllenfeuerhalbinsel möchte, dass Ihr Sedais Leichnam im Nordosten des Tempels erneut aufsucht, um dort das Relikt des Sehers zu benutzen. Kehrt nach Abschluss der Aufgabe zu ihm zurück.", progress = "Habt Ihr eine Vision gehabt, {name}?", completion = "Tief in meinem Innersten hoffe ich, dass Eure Vision Euch neue Einblicke auf die Ereignisse, die zu Sedais Tod geführt haben, gewährt hat. Das Relikt zeigte Euch eine mögliche Reihe von Ereignissen, die zur Gegenwart führten. Die Wahrheit mag irgendwo dazwischen liegen, doch wir werden es nie mit Sicherheit erfahren.\n\nHättet Ihr mit Eurem jetzigen Wissen anders gehandelt?\n\nWer kann schon sagen, ob unser Konflikt mit den Orcs ewig währen wird? Doch am wichtigsten ist es, immer für alle Möglichkeiten offen zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[9546] = { id = 9546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einlösung eines Versprechens", description = "Die Prophezeiung sprach von jemanden, der sich erheben würde und uns aus dem eisernen Griff der Sichelklauen befreien würde - die Geister selbst sollten das Erscheinen dieses Helden ankündigen.\n\nJetzt seid Ihr gekommen.\n\nIch verbeuge mich in Demut vor Euch, oh Einzigartiger. Ich flehe Euch an, rettet unsere Jüngsten. Sie wurden von den Sichelklauen entführt, nachdem man unsere Verteidigung lahmgelegt hat. Ihr findet sie in Käfigen im Dorf der Sichelklauen im Südwesten. Die Furbolgs der Sichelklauen tragen die Schlüssel für die Käfige bei sich. Streckt sie nieder und entwendet die Schlüssel. Befreit meinesgleichen.", sourceObjective = "Arugoo der Tannenruhfeste hat Euch gebeten, 8 gefangene Furbolgs der Tannenruhfeste aus Käfigen im Dorf der Sichelklauen zu befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[9547] = { id = 9547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Luft", description = "{name}, Scharfseher Nobundo hat nach Euch verlangt. Es scheint für Euch an der Zeit zu sein, die Geheimnisse der Luft - des noch fehlenden Elements - zu erlernen!\n\nIch bin sehr stolz auf all das, was Ihr bis jetzt erfolgreich gemeistert habt. Ich weiß, dass Euch ein besonderes Schicksal erwartet.", sourceObjective = "Sprecht mit Scharfseher Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[9548] = { id = 9548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlene Ausrüstung", description = "Schhh! Sprecht leise und lenkt keine Aufmerksamkeit auf mich.\n\nWenn die Murlocs meiner Anwesenheit gewahr werden, ist es mit dem Experiment vorbei! Ich war schon sehr nahe daran, meine Arbeit zu gefährden.\n\nAls ich gestern am Herumkramen war, muss einer von ihnen zu nahe gekommen sein und mein Lager entdeckt haben. Ich kam noch rechtzeitig, um zwei von ihnen eine meiner Ausrüstungskisten fortschleppen zu sehen! Sie muss in einer ihrer Siedlungen hier zu finden sein, aber ich kann es nicht riskieren, meine Deckung aufzugeben. Wollt Ihr mir vielleicht helfen?", sourceObjective = "Bringt Kloppers Ausrüstung zurück zu Klopper Knacksklug, der sich in einem angespülten Schildkrötenpanzer versteckt hält.", progress = "Konntet Ihr meine Ausrüstung finden?", completion = "Das ist fantastisch! Der Diebstahl meiner Ausrüstung hat mir zu noch mehr Einsicht in das Verhalten der Murlocs verholfen, als ich womöglich mittels wochenlanger Beobachtungen hätte gewinnen können!\n\nIch weiß schon, was ich in meinen Bericht schreiben werde.\n\n'Beim Aufeinandertreffen mit Erzeugnissen einer technologisch höher gestellten Kultur, zeigten die Murlocs der Schwarzschlammküste nicht die sonst typische Neugier wie humanoide Entwicklungskulturen.'\n\nDas ist großartig! Die Herren in Eisenschmiede werden es lieben! Ich kann Euch nicht genug danken, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9549] = { id = 9549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzschlammartefakte", description = "Meine Beobachtungen und Aufzeichnungen über die Murlocs der Schwarzschlammküste sind recht aufschlussreich, {name}, aber ich habe gerade erst damit angefangen. Ich habe vor, mit Gegenständen, die auf primitivste Weise von den Murlocs der Schwarzschlammküste hergestellt wurden, nach Eisenschmiede zurückzukehren.\n\nDas Problem ist allerdings, dass die Murlocs diese Gegenstände stets bei sich tragen. Ich könnte es nicht ertragen, wenn meine Hände mit ihrem Blut befleckt wären. Wollt Ihr mir vielleicht dabei helfen, Götzen von den Sehern der Schwarzschlammküste und kunstlosen Messer von den Kriegern und Küstenschlägern der Schwarzschlammküste einzusammeln? Ich werde Euch auch nicht fragen, wie Ihr sie Euch beschafft habt.", sourceObjective = "Bringt 3 kunstlose Murlocgötzen und 6 kunstlose Murlocmesser zu Klopper Knacksklug, der sich in einem angespülten Schildkrötenpanzer versteckt hält.", progress = "Habt Ihr die Gegenstände, die ich nach Eisenschmiede bringen möchte?", completion = "Verblüffend, einfach verblüffend! Diese Stücke sind perfekt, {name}. Ich kann sie mir bereits unter Glas im Museum von Eisenschmiede vorstellen. Der Text für die Vitrine schreibt sich in meinem Kopf gewissermaßen von selbst!\n\nEure Hilfe war für den Fortgang meiner Studien von unschätzbarem Wert. Wie schreibt sich Euer Name doch gleich? Ich werde dafür sorgen, dass Ihr in meinem Bericht als Mitautor auftaucht.\n\nEiner der Burschen auf dem Schiff gab mir diese 'Schatzkarte', um seine Spielschulden bei mir zu begleichen, allerdings ist Mythologie keines meiner Fachgebiete. Abergläubiges Pack, diese Seefahrer.", sourceObjectiveStatus = "unverified-source-field" }
quests[9550] = { id = 9550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wohin führt die Karte?", description = "Die nicht gerade sorgfältig gezeichnete Karte verrät zwar nichts über ihren Verfasser, scheint aber mit zittrigen Händen angefertigt worden zu sein. Krakelige Linien und Symbole beschreiben einen kleinen Pavillon mit eingestürzten Säulen. Er befindet sich im Westen eines Turms, der teilweise unter Wasser steht.\n\nGlaubt man der Karte, so liegen diese Ruinen an der östlichen Küste der Insel. Es ist Euch ein Rätsel, was Ihr dort vorfinden werdet, es scheint für die Erstellung dieser Karte jedoch wichtig genug gewesen zu sein.", sourceObjective = "Macht den auf der Karte beschriebenen Pavillon ausfindig und sucht, auf was der Verfasser der Karte hinweisen wollte.", progress = "Vielleicht bezieht sich die Karte ja auf dieses alte Tagebuch.", completion = "Nachdem Ihr Euch das Buch sorgfältig angesehen habt, kommt Ihr zu dem Schluss, dass es sich um ein Tagebuch handelt. Die Eintragungen auf den Seiten weisen eine elegante Handschrift auf, die sich von der auf der Karte unterscheidet. Zahlreiche Texte sind durch hinzugefügte Beschriftungen und Zeichnungen im Stil der Karte unleserlich geworden.\n\nDurch das Geschreibsel des Kartenverfassers, in dem er von Trinkgelagen während des Landgangs faselt, sind die eigentlichen Eintragungen fast nicht mehr auszumachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9551] = { id = 9551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Luft", description = "{name}, Scharfseher Nobundo hat nach Euch verlangt. Es scheint für Euch an der Zeit zu sein, die Geheimnisse der Luft - des noch fehlenden Elements - zu erlernen!\n\nIch bin sehr stolz auf all das, was Ihr bis jetzt erfolgreich gemeistert habt. Ich weiß, dass Euch ein besonderes Schicksal erwartet.", sourceObjective = "Sprecht mit Scharfseher Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[9552] = { id = 9552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Luft", description = "Der mächtige Geist der Luft verlangt nach Euch, {name}, es ist an der Zeit, diesem Ruf zu folgen.\n\nIch möchte, dass Ihr den Wildwindpfad im Norden hinaufwandert, dem Berg zugewandt, an dem die Exodar zerschellt ist. Auf seinem Gipfel werdet Ihr eine Höhle finden und darin eine meiner am besten ausgebildeten Schülerinnen, Velaada.\n\nBitte, hört auf ihre Weisheit und befolgt ihren Rat. Wenn Ihr zurückkehrt, werdet Ihr ein größeres Verständnis für das Element der Luft haben.", sourceObjective = "Sprecht mit Velaada beim Wildwindgipfel auf der Azurmythosinsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[9553] = { id = 9553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Luft", description = "Die Luft scheint flüchtig zu sein, sie ist jedoch eine alles bedeckende und durchdringende Kraft, die uns umgibt.\n\nAuch wenn Ihr sie nicht sehen könnt, so bestehen die Felsen dieser Höhle doch hauptsächlich aus Luft, das Wasser der Ozeane ist mit ihr gesättigt und ohne sie könnte kein Feuer bestehen. Lasst dies die Elemente niemals hören!\n\nDerjenige, den ihr wegen dieses Wissens wirklich zu sprechen wünscht, ist ganz in der Nähe. Am nördlichen Ende der Felsklippe erwartet Euch Susurrus. Mit seiner Hilfe werdet Ihr verstehen lernen.", sourceObjective = "Sprecht mit Susurrus beim Wildwindgipfel auf der Azurmythosinsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[9554] = { id = 9554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Luft", description = "Während meine Brüder und Schwestern der anderen Elemente die Erfüllung verschiedenster Aufgaben von Euch verlangten, werde ich keine weiteren Anforderungen an Euch stellen. Ich glaube, dass Ihr genug geleistet habt, um für eine 'Wiedergutmachung' für den Unfall, den der Absturz Eures Schiffs verursacht hat, zu sorgen. Ich kann sehen, dass Ihr bereits über die Erfahrenheit verfügt, die Ihr für einen weisen Umgang mit dem Element der Luft benötigt.\n\nNehmt diesen Teil meiner Selbst zurück zu Scharfseher Nobundo, damit er Euch bei der Erstellung Eures Totems helfen kann. Sobald Ihr bereit seid, werde ich Euch zurück zur Exodar fliegen.", sourceObjective = "Kehrt mit dem Luftwirbel zu Scharfseher Nobundo bei der Exodar auf der Azurmythosinsel zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9555] = { id = 9555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Feuers", description = "Es freut mich, dass Ihr den schwierigen Pfad des Schamanen gewählt habt. Nur wenige entscheiden sich für diesen Weg, aber ich spüre, dass es für unsere Zukunft von großer Bedeutung sein wird, die Macht des Schamanismus von den Zerschlagenen zu erlernen.\n\nMan nennt sie so, aber einst waren auch sie Draenei. Teuflische Magie hat sie verwandelt und deshalb können sie sich nicht auf die Macht des Lichts berufen. Einige missbilligen sie und den Schamanismus, den sie lehren, aber sie sind nicht bösartig.\n\nIch möchte, dass Ihr mit Scharfseher Nobundo sprecht. Er ist der weiseste Schamane, den ich kenne, er wird Euch viel beibringen können.Ihr erlernt:", sourceObjective = "Sprecht mit Scharfseher Nobundo in der Kristallhalle der Exodar.", sourceObjectiveStatus = "unverified-source-field" }
quests[9556] = { id = 9556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Sieger...", description = "Ihr habt zweifellos lange und hart um die Verteidigung der Türme gekämpft, {race}. Wir würden Euch gerne etwas im Gegenzug für Euren tapferen Einsatz geben, allerdings müsst Ihr uns zuerst beweisen, dass Ihr die Gewichtigkeit dieser hier stattgefundenen Tragödien auch versteht.\n\nLauft durch Stratholme und sucht nach einer Phiole mit dem heiligen Wasser. Sobald Ihr sie gefunden habt, reist zum Magierviertel in Sturmwind oder nach Unterstadt... Dort werdet Ihr, insofern Ihr in diesen Landen siegreich wart, auf meinen Kollegen treffen.", sourceObjective = "Sucht nach einer Phiole mit heiligem Wasser in Stratholme und bringt sie zu dem Magier von Lordaeron im Magierviertel von Sturmwind oder in Unterstadt, falls Eure Seite in den Östlichen Pestländern erfolgreich war.", sourceObjectiveStatus = "unverified-source-field" }
quests[9557] = { id = 9557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entziffern des Buchs", description = "Da Ihr über keinerlei Mittel verfügt, die es Euch ermöglichen würden, den Inhalt des Buchs zu entschlüsseln, versucht Ihr Euch jemanden ins Gedächtnis zu rufen, der Euch dabei helfen könnte, die ursprünglichen Eintragungen zwischen dem Gekritzel des Kartenverfassers herauszulesen.\n\nIhr erinnert Euch an Anachoret Paetheus' Sammlung verschiedenster Artefakte, die die Draenei während ihrer Reisen entdeckten. Vielleicht können Euch ja seine erfahrenen Augen bei der Entzifferung des Buchs weiterhelfen.", sourceObjective = "Bringt das alte Tagebuch zu Anachoret Paetheus bei der Blutwacht.", progress = "Möge das Licht bei all Euren Bemühungen mit Euch sein, {class}. Was habt Ihr da?", completion = "Hmm... das ist äußerst faszinierend. Ja, ich sollte in der Lage sein, die eigentlichen Einträge des Schreibers in diesem Buch entziffern zu können.\n\nIch verfüge über die benötigten Mittel hier. Es sollte nur einen Augenblick dauern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9558] = { id = 9558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Langbarts", description = "Vor nicht allzu langer Zeit hatten wir einige Probleme mit Arakkoabanditen. Sie haben viele unserer Versorgungskarawanen überfallen, weswegen ich ein paar Zwerge angeheuert habe, die sich um sie kümmern sollten.\n\nEs waren Brüder, wobei Gremni Langbart der Älteste von ihnen war. Sie sind losgezogen und nie zurückgekehrt.\n\nIch mache mir ein wenig Sorgen um sie, versteht Ihr? Diese verrückten Zwerge haben mehr Bier als Essen oder Munition eingepackt! Könntet Ihr vielleicht einmal nach ihnen sehen?\n\nDas Versteck der Arakkoa, der Haal'eshbau, befindet sich von hier aus weit im Westen, hinter der Großen Kluft. Sie müssen irgendwo nordwestlich von dort ein Lager aufgeschlagen haben, südlich der Staubstachelschlucht.", sourceObjective = "Sucht nach Gremni Langbart nordwestlich des Haal'eshbaus, weit im Westen der Ehrenfeste auf der Höllenfeuerhalbinsel.", completion = "Wie habt Ihr uns gefunden, {class}? Egal, Ihr seid sicher hier, um uns zu helfen. Dann mal an die Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[9559] = { id = 9559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tannenruhfeste", description = "<Auserwählter/Auserwählte>, Ihr müsst nach Norden zur Heimstätte meiner Leute reisen – zur Tannenruhfeste. Dort werdet Ihr auf Eure schrecklichste Herausforderung treffen.\n\nGeht jetzt, der Oberhäuptling der Tannenruhfeste erwartet Euch.", sourceObjective = "Sprecht mit dem Oberhäuptling bei der Tannenruhfeste.", completion = "Jahrhunderte lang lebten wir in verhältnismäßigem Frieden mit den Kreaturen des Landes. Vor einigen Monaten begann Kurz, dunkle Vorzeichen zu sehen. Der Frieden, den wir so lange genossen hatten, schien in Gefahr. Keiner konnte die Ausmaße dieser Katastrophe erahnen!\n\nUnd so kam es, dass die Götter unser Land straften und sowohl Feinde als auch Freunde gegen uns richteten. Aber es gab da noch etwas... inmitten des Chaos sollte sich ein Held erheben: ein Held, in dessen Adern nicht das Blut der Tannenruh fließt. Der Auserwählte würde uns vor der Zerstörung erretten.\n\nDer prophezeite Held wart Ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[9560] = { id = 9560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Biester aus der Apokalypse!", description = "Mein Bruder und ich waren im östlich gelegenen Wald beim Jagen, als wir von seltsamen, insektenartigen Biestern angegriffen wurden. Solch fremdartige Geschöpfe hatten wir zuvor noch nie auf der Azurmythosinsel gesehen! Könnten es die Vorboten der angekündigten Apokalypse sein? Der Weltuntergang, den IHR verhindern sollt?\n\nSolltet Ihr wirklich der auserwählte Held sein, so werdet Ihr die Biester der Apokalypse bezwingen... und mir ihre Bälge bringen. Ich kann Euch aus diesem Material eine mächtige Rüstung anfertigen!\n\nSucht Richtung Osten nach ihnen, abseits der Straße.", sourceObjective = "Moordo bei der Tannenruhfeste auf der Azurmythosinsel möchte, dass Ihr ihm 8 Felshetzerbälge bringt.", progress = "Es sind hässliche kleine Kreaturen. Sogar der blinde Behüter könnte sie sehen... und er ist blind.", completion = "Nicht nur, dass die Prophezeiung wahr ist, nein, diese Rüstung ist ebenso erstaunlich! Eine Rüstung für einen Helden! Ich werde sie Euch für einen besonders günstigen Preis verkaufen, Fellloser.\n\nDas war ein Scherz... das erste Teil gibt's umsonst.", sourceObjectiveStatus = "unverified-source-field" }
quests[9561] = { id = 9561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nolkais Worte", description = "Ich bin mit der Entschlüsselung jetzt fertig, {name}.\n\n<Anachoret Paetheus zeigt auf einen Textabschnitt am Ende seiner Abschrift.>\n\n'Der Feind ist ganz nah. Wir haben alle Überlebenden zusammengerufen und uns mit ihnen zu dem östlich gelegenen Tempel geflüchtet. Es ist der letzte Ort auf dieser Insel, den wir noch halten können. Unter den Überlebenden hat sich der Glaube verbreitet, dass dies unsere endgültige Zuflucht sein wird. Ich habe Vorkehrungen getroffen und meine verbliebene Habe im Boden des Tempels vergraben. Ich hoffe, dass sie jemand finden und somit erfahren wird, was hier geschehen ist.'", sourceObjective = "Findet den in Nolkais Tagebuch beschriebenen Ort und sucht nach seinen seit langem vergrabenen Besitztümern.", completion = "Gras und Gestrüpp bedecken eine unnatürliche Wölbung am Boden.\n\nNach nur kurzem Graben entdeckt Ihr einen alten Kasten. Es muss sich dabei um den, der in Nolkais Tagebuch beschrieben ist, handeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[9562] = { id = 9562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murlocs... Warum hier? Warum jetzt?", description = "Es herrschen dunkle Zeiten, <Auserwählter/Auserwählte>. Sogar die Murlocs trampeln uns auf den Füßen herum - im wahrsten Sinne des Wortes. Unglücklicherweise wurde nicht nur mein Stolz verletzt.\n\nUnser Verhältnis zu den Schlickflossenmurlocs war zwar schon immer recht bescheiden, jedoch hätten wir uns niemals vorstellen können, dass sie uns angreifen und von unseren Essensvorräten stehlen würden! Reist Richtung Westen zur Schlickerküste und bringt uns unsere gestohlenen Vorräte wieder!\n\nUnd solltet Ihr einen dunkelhäutigen Murloc mit einem Stück weißen Fell zwischen den Schwimmhäuten sehen...", sourceObjective = "Gurf bei der Tannenruhfeste auf der Azurmythosinsel möchte, dass Ihr 5 Säcke mit Tannenruhgetreide wiedererlangt.", progress = "Ein Murloc hat mir in den Hintern getreten und mich angespuckt... und das am helllichten Tag!", completion = "Mmmmm... köstliches Getreide... Parkat wird sich freuen!", sourceObjectiveStatus = "unverified-source-field" }
quests[9563] = { id = 9563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mirrens Vertrauen erlangen", description = "Ihr wollt also unser Vertrauen erlangen? In diesen Zeiten vertraue ich nicht vielen Leuten.\n\nVor kurzer Zeit haben wir einen der unseren an die Arakkoa verloren. Das hat mich etwas nervös gemacht.\n\nIch sag' Euch was, wenn Ihr Eure Loyalität gegenüber der Ehrenfeste beweisen könnt und... mir einen Krug Nethergarde Bitter bringt... ja, das klingt so weit ganz gut... dann biete ich Euch einen Handel an.\n\nBernie in der Burg Nethergarde hat das Bitter auf Lager.", sourceObjective = "Mirren Langbart auf der Höllenfeuerhalbinsel möchte, dass Ihr ihm 1 Nethergarde Bitter bringt. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Ehrenfeste.", progress = "Probleme, das Bitter zu finden? Der gute alte Bernie in der Burg Nethergarde sollte Fässer davon auf Lager haben.\n\nEs sei denn, seine Vorräte sind ausgegangen... das wäre fatal!", completion = "Oh ja! Ihr scheint ganz in Ordnung zu sein, {race}. Ich denke, ich kann Euch vertrauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9564] = { id = 9564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurfs Würde", description = "Nehmt dem Murloc das Stück Fell, das Gurf bei seiner Auseinandersetzung mit den Biestern \"verloren\" hat, ab und bringt es anschließend zu Gurf zurück. Lasst ihn sogleich wissen, dass der entsetzliche Murgurgula vernichtet wurde.", sourceObjective = "Bringt Gurfs Würde zu Gurf bei der Tannenruhfeste auf der Azurmythosinsel.", progress = "Ist das etwa das, was ich vermute?", completion = "<Gurf spuckt auf den Fellfetzen und versucht ihn auf die kahle Stelle auf seinem Hintern anzubringen.>\n\nDas muss vorerst halten! Ich hoffe, dass einer der Schamanen den Schaden wieder beheben kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[9565] = { id = 9565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht in der Tannenruhfeste", description = "Als Oberhäuptling gilt meine erste Sorge der Ursache, die hinter der Verderbnis innerhalb der Tannenruhfeste steckt.\n\nWarum haben uns die Wildekin - einst unsere Verbündeten - angegriffen? Warum haben sie die Tannenruhfeste besetzt?\n\nVielleicht finden wir im Innern der Feste ja eine Antwort. Sucht in der Tannenruhfeste nach dem Quell der Verderbnis.", sourceObjective = "Sucht in der Tannenruhfeste nach Hinweisen.", completion = "Der Blutkristall verstrahlt eine kränkliche Aura, die in das Wasser im Keller sickert.", sourceObjectiveStatus = "unverified-source-field" }
quests[9566] = { id = 9566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutkristalle", description = "Außerhalb des Wassers sieht der Kristall wie ein Teil der Exodar aus. Allerdings scheint mit diesem Kristall etwas nicht zu stimmen, denn er ist blutrot und löst sich sehr schnell im Wasser des Kellers auf.\n\nDas könnte das ungewöhnlich aggressive Verhalten der Kreaturen auf der Azurmythosinsel erklären. Kehrt mit diesen Informationen zum Oberhäuptling der Tannenruhfeste zurück.", sourceObjective = "Sprecht mit dem Oberhäuptling bei der Tannenruhfeste.", completion = "Von den Blutkristallen, wie Ihr sie gesehen habt, wurden von meinen Spähern noch viele weitere im Norden gesichtet.\n\nIch danke Euch für die Hilfe, muss Euch nun aber bitten zu gehen, weil ich mich noch mit den Ältesten beraten muss. Ich werde nach Euch rufen lassen, sobald ich mit den anderen Ältesten des Dorfes gesprochen habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[9567] = { id = 9567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kenne deinen Feind", description = "Es tut gut, neue Gesichter hier bei der Blutwacht zu sehen, {class}. Die Blutelfen stellen zwar die derzeit größte Bedrohung für uns dar, jedoch gibt es noch andere finstere Kreaturen, die die Blutmythosinsel zu ihrem Zuhause gemacht haben.\n\nDie Satyrn der Nazzivus beunruhigen uns besonders. Es sind üble, dämonische Kreaturen, die dunkle Magien beherrschen und sich an der Verderbnis nähren, die der Absturz der Exodar verursacht hat.\n\nWir müssen sie in Schach halten, aber bevor wir handeln, gilt es noch etwas mehr über sie in Erfahrung zu bringen. Geht nach Nazzivian im Südwesten und versucht so viel wie möglich von ihrem grotesken Monument zu lernen.", sourceObjective = "Findet das Monument der Nazzivus in Nazzivian und beschafft Euch eine Glyphe vom Monument der Nazzivus. Kehrt zu Verteidiger Aalesia bei der Blutwacht zurück, sobald Ihr die Glyphe habt.", progress = "Habt Ihr schon etwas Wissenswertes von den Satyrn der Nazzivus erlangt?", completion = "Gut gemacht, {name}. Mal sehen, was ich von dieser Glyphe in Erfahrung bringen kann. Dann können wir unseren nächsten Schritt planen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9568] = { id = 9568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der Offensive", description = "Es ist schlimmer, als ich dachte, {name}. Wir Draenei wissen nur zu gut, was passiert, wenn man seine Seele an die Brennende Legion im Austausch für das Versprechen von Macht und Unsterblichkeit verkauft.\n\nDie Satyrn auf dieser Insel, die Nazzivus, sind Abkömmlinge der ersten abartigen Kreatur, die sich mit der Legion verbündet hatte. Ich fürchte, dass sie einen Weg finden werden, um die Kraft der Kristalle von der Exodar gegen uns zu verwenden.\n\nIhr habt gesehen, was sie diesem Land angetan haben. Stellt Euch nur vor, was sie in den Händen der Satyrn anrichten könnten. Geht Richtung Südwesten nach Nazzivian und startet unsere Offensive!", sourceObjective = "Verteidigerin Aalesia bei der Blutwacht möchte, dass Ihr 10 Satyrn der Nazzivus, 5 Schurken der Nazzivus und 5 Teufelsanbeter der Nazzivus tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[9569] = { id = 9569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bedrohung bekämpfen", description = "Jetzt, da wir bei den Satyrn Eindruck hinterlassen haben, müssen wir ihnen zu verstehen geben, dass wir Übeltäter der Brennenden Legion hier nicht dulden.\n\nDie Draenei sind schon viel zu lange im Schatten der Legion und ihrer Diener geflohen, {name}. Wo immer sie uns auch fanden, sie zeigten niemals Gnade.\n\nWir dürfen es nicht zulassen, dass die Satyrn den Absturz der Exodar ausnutzen und die verderbten Kristalle als Waffe einsetzen. Geht nach Axxarien im Norden, dem Sitz ihres Anführers. Tötet ihn und nehmt die verderbten Kristalle, die er angesammelt hat, an Euch!", sourceObjective = "Tötet 5 Schattenpirscher von Axxarien, 5 Höllenrufer von Axxarien und Zevrax. Sammelt außerdem 5 verderbte Kristalle ein und kehrt zu Verteidigerin Aalesia bei der Blutwacht zurück.", progress = "<Verteidigerin Aalesia scheint eher durch Euch hindurch, als Euch anzusehen, sie ist voll und ganz mit den Satyrn beschäftigt.>\n\nSeid Ihr schon gegen den Anführer der Satyrn vorgegangen?", completion = "Ohne ihren Anführer und die entwendeten Kristalle können wir die Satyrn bedenkenlos in Schach halten. Nur das Licht weiß, wie viele dieser erbärmlichen Kreaturen da draußen noch lauern.\n\nHerold Mikolaas und ich sind Euch für Eure Hilfe sehr dankbar. Ihr habt uns geholfen, eine noch größere Bedrohung durch die Satyrn abzuwenden. Euer Einsatz wird alle daran erinnern, dass Wachsamkeit der Schlüssel zum Erfolg ist, wenn es darum geht, gegen die Legion und ihre Diener vorzugehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9570] = { id = 9570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kurken lauert", description = "Nachdem der Kristallsturm nachgelassen hatte, erschien eine mythische Bestie in unserem Dorf. Das Untier, Kurken, das von den einfallenden Wildekin hierher gebracht wurde, legte alles in Trümmer. Zahlreiche Furbolgs der Tannenruhfeste wurden bei der Verteidigung unseres Landes von der Bestie getötet. Beim Versuch, das Untier zu bezwingen, ließen viele weitere ihr Leben.\n\nIn meinen Visionen sah ich jemanden, der Kurken besiegte. Diese Person müsst Ihr sein, {name}. Es kann nur einen geben. Betretet die Tannenruhfeste und tötet Kurken. Bringt mir seinen Balg als Beweis für Eure Tat.", sourceObjective = "Kurz der Weise bei der Tannenruhfeste auf der Azurmythosinsel möchte, dass Ihr Kurken tötet und dass Ihr ihm Kurkens Balg bringt.", progress = "<Kurz schnaubt Euch an.>", completion = "Der Held ist erfolgreich zurückgekehrt!\n\nDie Prophezeiung hat sich fast vollständig bewahrheitet. Jetzt zu dem Balg...", sourceObjectiveStatus = "unverified-source-field" }
quests[9571] = { id = 9571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kurkens Balg", description = "Bringt Kurkens Balg zu Moordo, auf der anderen Seite des Dorfes. Er wird daraus ein Rüstungsteil Eurer Wahl anfertigen.", sourceObjective = "Bringt Kurkens Balg zu Moordo bei der Tannenruhfeste.", progress = "Hallo, Held!", completion = "Das ist die stärkste Rüstung, die ich jemals angefertigt habe! Nutzt sie weise, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9572] = { id = 9572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weaken the Ramparts" }
quests[9573] = { id = 9573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Häuptling Oomooroo", description = "Ich bin der Jüngling Tannenruh, Erbe des Vermächtnisses von Tannenruh. Wie Ihr sehen könnt, haben meine Verteidiger eine Todesfalle für die irren Wildekin aufgestellt, die von der Tannenruhfeste aus angreifen. Wir können sie zwar hier draußen abwehren, allerdings hat es noch keiner meiner Verteidiger geschafft, in die Feste vorzudringen. Wenn es Euch gelingen sollte, dort hinein zu gelangen und ihren Anführer zu töten, würde uns das vielleicht eine Gelegenheit zum Angriff verschaffen!\n\nFindet Häuptling Oomooroo und vernichtet ihn. Tötet auch alle wahnsinnigen Wildekin, die Euch im Innern der Feste in die Quere kommen.", sourceObjective = "Der Jüngling Tannenruh bei der Tannenruhfeste auf der Azurmythosinsel möchte, dass Ihr Häuptling Oomooroo und 9 wahnsinnige Wildekin tötet.", completion = "Das könnte die Gelegenheit sein, auf die wir so lange gewartet haben! Ich werde sofort angreifen lassen! Der Stamm der Tannenruhfeste dankt Euch für Euren Einsatz, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[9574] = { id = 9574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Opfer der Verderbnis", description = "Unsere Ankunft hat die Blutmythosinsel für alle Zeit verändert. Der Absturz der Exodar hat Trümmer über die gesamte Insel verstreut und ich glaube, dass sich dies langsam negativ auf die Natur hier auswirkt.\n\nIch muss mir alles erst genauer ansehen, bevor ich meine Schlussfolgerung bestätigen kann. Die Kristalle scheinen die Bäume als erstes beeinträchtigt zu haben, also müssten die Treants am ehesten die Symptome aufweisen. Wenn Ihr mir Proben von der Rinde verderbter Treants bringen würdet, könnte ich mich weiter in meine Studien vertiefen.", sourceObjective = "Bringt 6 Stücke kristallisierte Rinde zu Morae bei der Blutwacht.", progress = "Konntet Ihr die Proben bekommen, die ich benötige?", completion = "Ich habe jetzt mehr als genug für meine Untersuchungen. Ich danke Euch, {name}. Solltet Ihr noch etwas anderes auftreiben können, das beweist, dass die Kristalle die einheimischen Kreaturen der Blutmythosinsel beeinträchtigen, so lasst es mich sofort wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9575] = { id = 9575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bollwerke schwächen", description = "Schnell, wir haben nicht viel Zeit. Die Existenz der Ehrenfeste steht auf Messers Schneide!\n\nWir sitzen zwischen der Höllenfeuerzitadelle im Westen und der Brennenden Legion im Osten fest. Da die Legion ihre Aufmerksamkeit auf das Dunkle Portal gerichtet hat, müssen wir die Chance nutzen, um die Höllenorcs in der Zitadelle anzugreifen. Der Schlüssel dazu ist, zunächst die Bollwerke zu durchbrechen!\n\nGeht dorthin, tötet ihre Anführer und bringt einen Beweis für Eure Tat zu Gunny gegenüber von mir!", sourceObjective = "Tötet den Wachhabenden Gargolmar, Omor den Narbenlosen und Nazan, den Drachen. Bringt Gargolmars Hand, Omors Huf und Nazans Kopf zu Gunny in der Ehrenfeste auf der Höllenfeuerhalbinsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[9576] = { id = 9576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schandflosses Anhänger", description = "Ihr untersucht den sehr simpel angefertigten Anhänger und stellt fest, dass der Kristall ganz sachte pulsiert. Er leuchtet ein wenig, aber Ihr spürt auch, dass irgendetwas Unnatürliches davon ausgeht.\n\nIhr seid Euch zwar nicht sicher, was Schandflosse zur Anfertigung dieses Anhängers getrieben hat, aber der Fund scheint zu wichtig, als dass er ignoriert werden könnte. Ihr solltet ihn jemandem bei der Blutwacht zeigen.", sourceObjective = "Bringt den roten Kristallanhänger zu Morae bei der Blutwacht.", progress = "Was habt Ihr da bei Euch?", completion = "Das ist äußerst verwunderlich, {class}. Ich glaube nicht, dass wir jemals einen Murloc gesehen haben, der Schmuck trägt.\n\nBetrachtet man den verderblichen Einfluss, den die Kristallsplitter ganz offensichtlich haben, so muss der Murloc, der diesen Anhänger getragen hat, davon überzeugt gewesen sein, dass er ihm eine Art Macht über seine Artgenossen verleihen würde. Es würde mich nicht verwundern, wenn er in kürzester Zeit stärker als seine Murlocgefährten geworden ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[9578] = { id = 9578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach Galaen", description = "Denkt Ihr oft an Eure Familie, {name}? An Bord der Exodar befanden sich einige Familien, aber ich habe nur von sehr wenigen gehört, die sich nach dem Absturz wiedergefunden haben.\n\nIch suche zum Beispiel nach Spuren von meinem Mann, Galaen. Er war Techniker im Kryokern. Die Trümmer davon wurden im Westen gefunden, allerdings wimmelt es dort nur so von Blutelfen!\n\nIch muss wissen, was Galaen zugestoßen ist! Selbst die Nachricht von seinem Tod wäre noch besser als diese Ungewissheit. Mein Mann trägt den gleichen Anhänger wie ich; sie waren ein Geschenk meiner Schwester.", sourceObjective = "Sucht nach Moraes Mann Galaen.", completion = "Der Leichnam trägt die für einen Techniker der Exodar übliche Kleidung, aber der von Morae beschriebene Anhänger fehlt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9579] = { id = 9579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Galaens Schicksal", description = "Die Informationen von Morae ermöglichen es Euch nicht, den Leichnam eindeutig als den von Galaen zu identifizieren, allerdings scheint man die Kleidung bei der Suche nach Kostbarkeiten zerrissen zu haben.\n\nDie Blutelfen der Umgebung hätten bei den Wrackteilen jeglichen Gegenstand von Wert an sich genommen, einschließlich das mit Juwelen besetzte Amulett von Galaen.\n\nAuch wenn Moraes Mann den Absturz nicht überlebt hat, so wird sie mit Sicherheit dankbar sein, wenn Ihr das Amulett von den Blutelfen wiedererlangt.", sourceObjective = "Bringt Galaens Amulett zu Morae bei der Blutwacht.", progress = "<Morae sieht Euch voller Hoffnung an.>\n\nSeid Ihr bei Eurer Suche auf Spuren von Galaen gestoßen?", completion = "<Ihr berichtet Morae von Eurem Fund in den Trümmern des Kryokerns.>\n\nAlso... er ist...\n\nIch denke, dass ich es bereits wusste, wollte es aber einfach nicht glauben. Es sind zwar nicht die Neuigkeiten, die ich mir erhofft hatte, aber ich bin Euch für das Auffinden von Galaen zutiefst dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[9580] = { id = 9580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bärdarfsgüter", description = "Seit Ihr auf der Blutmythosinsel seid, habt Ihr sicherlich nur wenig gesehen, dass sich nicht auf Grund unserer Ankunft verändert hat. Meine Ausbildung und Erfahrung haben mich gelehrt, dass sogar die Erzeugnisse einer derartigen Umgebung noch von Nutzen sein können.\n\nMit so wenigen Ressourcen müssen wir uns auf unseren Einfallsreichtum verlassen, um versorgt zu sein. Ich habe unsere Läden mit Fleisch ausgestattet, das von Bären stammt, die auf dieser Insel umherstreifen. Wenn man es richtig zubereitet, kann es bedenkenlos verzehrt werden. Solltet Ihr da draußen unterwegs sein, so helft uns doch bitte unsere Vorräte aufzufüllen.", sourceObjective = "Bringt 8 Flanken eines alten Braunbären zu Fährtenleser Lyceon bei der Blutwacht.", progress = "Wie verläuft Eure Jagd, {name}?", completion = "Mit diesen Vorräten werden wir fürs Erste versorgt sein und die Zubereitung für den späteren Verzehr wird mich sicherlich ein Weilchen beschäftigen. Ich danke Euch für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9581] = { id = 9581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von den Kristallen lernen", description = "Willkommen bei der Blutwacht, {class}. Meine hauptsächliche Sorge gilt der Verteidigung des Außenpostens, aber unsere Anführer bei der Exodar haben mir auch zahlreiche andere Pflichten überantwortet.\n\nDas Problem ist nur, dass es eigentlich zu unsicher ist, eine große Anzahl von Forschern auszusenden, wenn die Insel so gefährlich ist. Ich brauche jemanden, der für mich eine Reihe von Kristallproben von verschiedenen Stellen der Insel einsammelt.\n\nDie erste Probe muss von den von Felshetzern besetzten Schiffstrümmern kommen, die südlich des Dorfs und auf der anderen Seite der Brücke liegen.", sourceObjective = "Benutzt die Kristallspitzhacke, um eine Kristallprobe der Absturzstelle von einem Kristall der Absturzstelle zu nehmen. Bringt die Probe zu Herold Mikolaas bei der Blutwacht.", progress = "Konntet Ihr die erste Kristallprobe bekommen?", completion = "Dieser Kristallsplitter wird unseren Forschern als Vergleichsgrundlage für Proben von anderen Teilen der Insel dienen, da er aus einem weniger verseuchten Gebiet der Blutmythosinsel stammt.\n\nIch werde die Probe erst losschicken können, wenn ich ein vollständiges Probenset habe, aber der Anfang ist getan. Wenn Ihr mir helfen möchtet, die anderen Proben einzusammeln, werde ich Euch für Eure Mühe natürlich belohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9582] = { id = 9582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stärke des Einen", description = "Als das Schiff abstürzte, wurde unsere Menagerie an den nordöstlichen Stränden dieser Insel zerstreut. Mir wurde ein Schlüssel für den Käfig eines besonders gefährlichen Exemplars anvertraut, dem Todesfelshetzer. Die Kreatur ist zwar nur leicht gepanzert, widersteht aber fast jeglicher Magie. Man muss sie mit der einfachen Kraft des Schwerts erlegen.\n\nNehmt diesen Schlüssel und befreit den Felshetzer aus seinem Gefängnis und von seiner Qual. Wir können es nicht zulassen, dass er aus dem Käfig ausbricht und der Umwelt hier noch weiteren Schaden zufügt.", sourceObjective = "Öffnet den Felshetzerkäfig und tötet den darin befindlichen Todesfelshetzer. Kehrt dann zu Ruada in der Azurwacht auf der Azurmythosinsel zurück.", progress = "Habt Ihr das Biest bezwungen?", completion = "<Ruada nickt ernst.>\n\nSo sei es denn.\n\nIhr seid nun bereit für Eure nächste Lektion, {name}, aber Ihr werdet sie nicht von mir erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9584] = { id = 9584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die zweite Probe", description = "Da wir nun einen Kristall als Vergleichsgrundlage haben, benötigen wir jetzt Proben von gefährlicheren Gegenden der Insel, um das Set zu vervollständigen, das ich zur Exodar senden möchte.\n\nDie nächste Probe muss von den Kristallen kommen, die von den Blutelfen in der Umgebung des Messerwinkels, nordwestlich der Blutwacht, kontrolliert werden. Berichten zufolge verändern und ernten sie die Kristalle, um sie in einer Art magischer Apparatur zu verwenden. Versucht einen Kristall zu finden, der noch nicht in eines dieser Geräte eingebaut wurde, und entnehmt eine Probe davon.", sourceObjective = "Benutzt die Kristallspitzhacke, um eine Veränderte Kristallprobe von einem veränderten Blutmythoskristall zu nehmen. Bringt die Probe zu Herold Mikolaas bei der Blutwacht.", progress = "Habt Ihr die zweite Kristallprobe?", completion = "<Herold Mikolaas untersucht den Kristallsplitter.>\n\nDieser Splitter unterscheidet sich stark von der ersten Probe.\n\n<Herold Mikolaas hält den Kristall ins Licht.>\n\nSeht Ihr, wie das Licht darin pulsiert? Das ist bedenklich. Ich werde in meinem Bericht vermerken, dass die Blutelfen diesen Kristall verändert zu haben scheinen. Ich danke Euch für Eure erneute Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9585] = { id = 9585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte Probe", description = "Ich benötige nur noch eine letzte Probe, bevor ich das Set mit den Kristallen zur Exodar schicken kann, {name}. Die letzte Probe muss von der Feste der Satyrn im Nordwesten, Axxarien, kommen.\n\nIch weiß nicht genau, was mir diese Probe aufzeigen wird, aber ich bin mir sicher, dass sie Spuren der Verderbnis enthalten wird. Achtet darauf, dass Ihr eine Probe von den Kristallen entnehmt, die wie die aussehen, von denen Ihr zuvor Proben entnommen habt, ansonsten können unsere Forscher keine korrekten Vergleiche mehr anstellen.", sourceObjective = "Benutzt die Kristallspitzhacke, um eine Axxarienkristallprobe von einem Axxarienkristall zu nehmen. Bringt die Probe zu Herold Mikolaas bei der Blutwacht.", progress = "Habt Ihr die letzte Probe für mein Set?", completion = "<Herold Mikolaas nimmt den letzten Kristall von Euch entgegen.>\n\nDamit ist das Set vollständig. Ich muss nur noch alles verpacken und zur Exodar senden.\n\n<Der Herold scheint erleichtert, dass die Sache erledigt ist.>\n\nVersteht mich nicht falsch, {name}, ich bin mir sicher, dass die Forschungsarbeit wertvoll ist, aber wir haben es hier draußen noch mit zahlreichen anderen Problemen zu tun, die dringend sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[9586] = { id = 9586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft Tavara", description = "Tavara, eine unserer Kräuterkundigen, ist bei ihrer Suche nach Kräutern viel zu weit gegangen. Ich befürchte sie wurde verletzt und braucht Hilfe, aber unglücklicherweise kann ich mich nicht selbst auf die Suche nach ihr begeben.\n\nBitte findet und heilt sie, wenn nötig, {class}. Sie verließ die Azurwacht in Richtung Osten und machte sich auf den Weg zu einigen heißen Quellen.", sourceObjective = "Guvan bei der Azurwacht möchte, dass Ihr Tavara findet und ihre Wunden heilt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9587] = { id = 9587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Düstere Neuigkeiten", description = "Die Durchsuchung der leblosen Hülle von Vazruden dem Herold fördert einen zusammengerollten Brief zu Tage. Ein kunstvolles \"I\" ziert das noch intakte, blutrote Siegel. Ihr brecht das Siegel auf und was Ihr lest, beunruhigt Euch zutiefst.\n\nSicherlich würde Truppenkommandant Danath Trollbann in der Ehrenfeste gerne einen Blick auf den Brief werfen.", sourceObjective = "Bringt den unheilvollen Brief zu Truppenkommandant Danath Trollbann in der Ehrenfeste auf der Höllenfeuerhalbinsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[9588] = { id = 9588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Düstere Neuigkeiten", description = "Die Durchsuchung der leblosen Hülle von Vazruden dem Herold fördert einen zusammengerollten Brief zu Tage. Ein kunstvolles \"I\" ziert das noch intakte, blutrote Siegel. Ihr brecht das Siegel auf und was Ihr lest, beunruhigt Euch zutiefst.\n\nSicherlich würde Nazgrel in Thrallmar gerne einen Blick auf den Brief werfen!", sourceObjective = "Bringt den unheilvollen Brief zu Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[9589] = { id = 9589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut bedeutet Leben", description = "Ich bin mir sicher, dass dieser Brief hier für einigen Aufruhr sorgen wird. Wir glauben, etwas gegen die Erschaffung immer neuer Höllenorcs unternehmen zu können, wenn wir nur mehr über ihren Entstehungsprozess in Erfahrung bringen. Es ist schon schlimm genug, dass wir im Osten gegen die Brennende Legion kämpfen müssen.\n\nHeute ist also Euer Glückstag, <mein Bester/meine Beste>! Ihr bekommt die Chance auf einen Spaziergang im Blutkessel, wie manche den Innenhof der Höllenfeuerzitadelle nennen. Klingt verdammt heiß!\n\nZieht los, tötet ein paar Höllenorcs und bringt Proben ihres Blutes mit zurück.\n\nFühlt Ihr Euch der Aufgabe gewachsen?", sourceObjective = "Sammelt 10 Phiolen mit Höllenorcblut und bringt sie zu Gunny in der Ehrenfeste auf der Höllenfeuerhalbinsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[9590] = { id = 9590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blood is Life" }
quests[9591] = { id = 9591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Das Erste und Einzige, was <ein/eine:c> {class} am Anfang lernt, ist das Töten. Ihr scheint nun für den nächsten Schritt bereit zu sein.\n\nDie Furbolgs der Tannenruhfeste haben uns beigebracht, wie man Wildtiere zähmt, ohne monatelang zu studieren. Sie können ein Totem in der Gestalt eines Tiers formen, was sie für kurze Zeit mit einer Kreatur dieser Art verbindet.\n\nLektion Nummer Eins: Ihr nehmt dieses Totem und wendet es auf einen Stachelkriecher an. Ihr findet dergleichen an der westlichen Küste der Insel.", sourceObjective = "Benutzt das Zähmertotem, um einen Stachelkriecher zu bändigen. Kehrt nach gelungenem Unterfangen zu Jägerin Kella Nachtbogen zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9592] = { id = 9592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Der Kriecher war zweifellos widerborstig, aber der Grünschreiter wird Eure Beharrlichkeit mit Sicherheit auf eine noch härtere Probe stellen. Stärkere Verbündete benötigen mehr Entschlossenheit.\n\nNehmt dieses Zähmertotem und bändigt damit einen großen Grünschreiter. Ihr findet diese Kreaturen im Norden der Azurmythosinsel.", sourceObjective = "Benutzt das Zähmertotem, um einen großen Grünschreiter zu bändigen und kehrt anschließend zu Jägerin Kella Nachtbogen zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9593] = { id = 9593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Während der Zähmung des Grünschreiters sind Euch sicherlich die großen Katzen, die man Nachtpirscher nennt, aufgefallen. Es sind rasche und tödliche Jäger... und Verbündete.\n\nNehmt dieses Zähmertotem und bändigt damit einen Nachtpirscher. Geht mit dem Nachtpirscher auf die Jagd und schützt ihn vor Angreifern. Kehrt anschließend zu mir zurück.Ihr erlernt:", sourceObjective = "Benutzt das Zähmertotem, um einen Nachtpirscher zu bändigen und kehrt anschließend zu Jägerin Kella Nachtbogen zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9594] = { id = 9594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeichen der Legion", description = "Das Rüstungsstück wurde aus einem tiefschwarzen Metall geschmiedet, das Licht zu absorbieren scheint. Es wirkt zwar nicht verzaubert, allerdings kommt es Euch alles andere als normal vor.\n\nSolch eine Rüstung wird nur von einer bestimmten Macht verwendet - der Brennenden Legion. Die Gegenwart der Legion kann nur bedeuten, dass sie vorhaben, die Satyrn der Insel gegen die Draenei aufzuhetzen.\n\nGeht gegen die einheimischen Satyrn vor und zeigt dieses Rüstungsstück Verteidigerin Aalesia bei der Blutwacht.", sourceObjective = "Tötet 8 Satyrn der Nazzivus und 8 Teufelsanbeter der Nazzivus. Bringt anschließend Tzeraks Panzerplatte zu Verteidigerin Aalesia bei der Blutwacht.", progress = "Ja, {class}? Was habt Ihr da?", completion = "Es war richtig, dass Ihr damit zu mir gekommen seid, {name}. Es handelt sich hierbei zweifellos um ein Rüstungsstück einer Teufelswache.\n\nDann ist es also, wie ich es befürchtet hatte. Die Satyrn der Nazzivus nehmen erneut Verbindung zur Brennenden Legion auf. Wenn wir sie nicht aufhalten, werden uns die Satyrn und ihre dämonischen Verbündeten überrennen. Ich werde Herold Mikolaas sofort davon in Kenntnis setzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9595] = { id = 9595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kontrolle", description = "Ihr habt Euch entschieden, als {class} durchs Leben zu gehen, also müsst Ihr jetzt Kontrolle erlernen. Ungezügelte Magie ist fähig, Seelen zu verderben und Welten zu zerstören.\n\nUm all das noch besser verstehen zu können, müsst Ihr einem Wesen gegenüber treten, das der eigens ausgeübten Magie erlegen ist. Reist zu den Stränden an der nordwestlichen Küste der Azurmythosinsel und setzt Eure Magie ein, um ein paar üble Murlocs zu vernichten. Euer Magiegebrauch wird wahrscheinlich die böse Macht hervorlocken, die sich dort herumtreibt - ein Magiergeist der Quel'dorei. Vernichtet ihn.\n\nWenn Ihr fertig seid. macht Euch auf die Suche nach Bati in der Halle des Lichts der Exodar.", sourceObjective = "Vernichtet die Murlocs der Schlickerküste, um einen Magiergeist der Quel'dorei zu rufen, und vernichtet ihn. Sprecht dann mit Bati in der Halle des Lichts in der Exodar.", sourceObjectiveStatus = "unverified-source-field" }
quests[9596] = { id = 9596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kontrolle", description = "Macht etwas anderes, {class}!", sourceObjective = "Beschreibung", sourceObjectiveStatus = "unverified-source-field" }
quests[9598] = { id = 9598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erlösung", description = "Ich bin dafür verantwortlich, die Paladine auf den Pfad der größten Tugend zu bringen, sobald sie sich dem Weg des Lichts verschreiben und unser Volk vor den Bedrohungen verteidigen.\n\nDie Zeit ist gekommen, den ersten Schritt hin zu wahrer Tugend zu tun. Wenn Ihr einverstanden seid, gebe ich Euch das Buch der Offenbarung. Wenn Ihr es studiert, erfahrt Ihr etwas über das Licht und was von Euch erwartet wird. Wenn Ihr es versteht und tüchtig seid, werdet Ihr erfolgreich größere Fähigkeiten erlangen.", sourceObjective = "Lest das Buch der Offenbarung und sprecht mit Jol.", sourceObjectiveStatus = "unverified-source-field" }
quests[9600] = { id = 9600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erlösung", description = "Es wird Eure Aufgabe sein, {name}, unseren neuen Verbündeten, den Furbolgs der Tannenruhfeste, zu helfen.\n\nEinige der jüngeren Schamanen der Tannenruhfeste sind in eine Enklave der Sichelklauen gestolpert und wurden allesamt getötet. Nehmt dieses Symbol des Lebens und erweckt einen der Schamanen wieder zum Leben.\n\nDie Enklave der Sichelklauen liegt östlich der Straße, direkt nachdem man die Brücke überquert, die die Azurmythosinsel und die Blutmythosinsel verbindet. Sprecht mit mir, wenn Ihr diese Aufgabe erfüllt habt.Ihr erlernt:", sourceObjective = "Jol möchte, dass Ihr einen jungen Schamanen der Furbolgs mit dem Symbol des Lebens wieder zum Leben erweckt und dass Ihr anschließend wieder zu ihr zurückkehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9601] = { id = 9601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Bollwerk", description = "Der Blutritter Mehlar Dämmerklinge hat ein Treffen mit Euch gefordert, {name}. Ihr findet Mehlar beim Bollwerk, das den Übergang zwischen Tirisfal und den Westlichen Pestländern schützt.\n\nEr ist nicht gerade für seine Geduld bekannt. Ihr solltet ihn also nicht warten lassen.", sourceObjective = "Sprecht mit Mehlar Dämmerklinge beim Bollwerk.", sourceObjectiveStatus = "unverified-source-field" }
quests[9602] = { id = 9602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unheilvolle Mitteilung", description = "Ihr müsst Euren Leuten diese Informationen überbringen, {name}. Auch wenn Euer mutiger Einsatz die Pläne von Kael'thas und seinem dunklen Meister sicherlich ins Stocken gebracht hat, werden mit Sicherheit auch weiterhin Angriffe verübt werden.\n\nNehmt die Mitteilung des Verräters zu Euren Anführern. Sie müssen es mit ihren eigenen Augen sehen. Vielleicht verstehen sie einiges von dem Geschriebenen besser.", sourceObjective = "Bringt die Mitteilung des Verräters zu Exarch Menelaous bei der Azurwacht.", progress = "Ihr seid zurück!", completion = "<Exarch Menelaous nimmt die Mitteilung von Euch entgegen und beginnt sie zu lesen.>\n\nVerdammt... verdammt sie alle in den Nether. Sie hatten einen Spion, der sie über all unsere Aktivitäten informiert hat! Und seit wann?\n\nIch werde sofort Velen informieren!\n\nIhr habt uns einen großen Dienst erwiesen, {name}. Haltet die Augen offen, ich werde mich an Euch wenden, sobald der Prophet mir mitgeteilt hat, was es zu tun gilt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9603] = { id = 9603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Betten, Verbände und noch viel mehr", description = "Willkommen bei der Azurwacht, {class}. Bitte entschuldigt die Unordnung, die hier überall herrscht. Man betrachtet die einfachsten Dinge oft als selbstverständlich, wie zum Beispiel ein komplett eingerichtetes und ausgestattetes Gasthaus... bis man selbst ein neues aus dem Nichts errichten muss.\n\nWir konnten dieses Wrackteil bergen und für das Gebäude verwenden, allerdings ist dieses Gasthaus lediglich ein besseres Zelt, ohne die entsprechende Einrichtung und die Notvorräte. Nurguni bei der Exodar hat uns angeboten, ein paar Vorräte mit den im Moment am dringendsten benötigten Dingen zusammenzustellen. Ich brauche jedoch jemanden, der ihm diese Liste hier bringt.", sourceObjective = "Bringt Chellans Liste zu Zaldaan, dem Hippogryphenmeister bei der Azurwacht.", progress = "Guten Tag, {name}. Interessiert Ihr Euch für einen Hippogryphenflug?", completion = "Ihr müsst also zu der Exodar?\n\nDas ist ein ganz schön weiter Weg, aber keine Sorge, ich weiß schon, wie Ihr auf dem schnellsten Weg an Euer Ziel kommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9604] = { id = 9604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Rücken eines Hippogryphen", description = "Ihr könnt einen meiner Hippogryphen gegen ein kleines Entgelt mieten, um zur Exodar zu fliegen.\n\nEinen Hippogryphen zu nehmen, ist eine schnellere und, was noch wichtiger ist, sichere Reisemöglichkeit für jemanden, der eine wichtige Nachricht zu überbringen hat. Wenn Ihr Euch für einen Hippogryphenritt entschieden habt, sprecht einfach nochmal mit mir und ich kümmere mich um den Rest.", sourceObjective = "Erwerbt bei Zaldaan einen Hippogryphenritt zur Exodar. Bringt Chellans Liste nach der Landung zu Nurguni im Sitz der Naaru der Exodar.", progress = "Seid gegrüßt, Freund. Ihr seht aus, als hättet Ihr einen langen Weg hinter Euch. Wie kann ich Euch helfen?", completion = "Ah, Ihr habt also Chellans Liste mitgebracht. Ausgezeichnet! Ich hatte gehofft, dass ich sie heute erhalten würde. Lasst mal sehen, was sie braucht.\n\n<Nurguni überfliegt die Liste und beginnt verschiedene Gegenstände in eine Kiste zu packen.>\n\nDas sind fast alle Dinge, die sie aufgelistet hat. Die Teile für die Betten sind einfach zu groß, um auf einem Hippogryphen transportiert werden zu können. Ich werde dafür sorgen, dass sie mit einem Wagen nachgeliefert werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9605] = { id = 9605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hippogryphenmeister Stephanos", description = "Hier ist die Kiste, {name}. Es sollte genug sein, damit Chellan das Gasthaus fertigstellen und eröffnen kann. Richtet ihr bitte aus, dass sie bei steigendem Bedarf jederzeit weitere Vorräte anfordern kann. Die Azurwacht braucht unbedingt einen Ort, an dem Verwundete versorgt und Reisende empfangen werden können.\n\nSucht Stephanos auf, wenn Ihr zur Azurwacht zurück möchtet, er hält sich am Sitz der Naaru in der Exodar auf.", sourceObjective = "Geht zu Stephanos am Sitz der Naaru in der Exodar und erwerbt einen Hippogryphenritt zurück zur Azurwacht.", progress = "Wohin wollt Ihr, {class}?", completion = "Ihr wollt also mit dieser Kiste zurück zur Azurwacht? Kein Problem, {class}. Sagt einfach Bescheid, wenn's losgehen soll.", sourceObjectiveStatus = "unverified-source-field" }
quests[9606] = { id = 9606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zu Versorgerin Chellan", description = "Wenn ich mich recht erinnere, dann ist Zaldaan der Hippogryphenmeister bei der Azurwachtwacht. Falls Ihr schon einmal mit ihm gesprochen habt, könnt Ihr einen meiner Hippogryphen zurück zu ihm nehmen.\n\nIhr solltet Euch etwas Wichtiges merken: Hippogryphen werden stets so ausgebildet, dass sie zu ihrer Hauptstadt zurückfliegen, sie bringen Euch aber nur zu einem entlegenen Hippogryphenmeister, wenn Ihr schon einmal dort gewesen seid.\n\nDa Ihr mit einem von Zaldaans Hippogryphen hier angekommen seid, könnt Ihr diese Route auch wieder zurück zur Azurwacht nehmen und die Vorräte bei der Versorgerin abliefern.", sourceObjective = "Sprecht mit Stephanos und erwerbt einen Hippogryphenritt zurück zur Azurwacht. Bringt Nurgunis Vorräte nach Eurer Ankunft zu Versorgerin Chellan.", progress = "Willkommen zurück, {name}. Konnte Nurguni Euch alle Vorräte mitgeben, die auf der Liste standen?", completion = "<Ihr überreicht die Kiste und erklärt, dass Nurguni dafür sorgt, dass die größeren Gegenstände mit einem Wagen nachgeliefert werden.>\n\nGroßartig! Ich werde jetzt endlich ein paar Lagerstätten und eine Versorgungsstation einrichten können. Hier wird man sich in Zukunft um Verwundete und mögliche weitere Überlebende kümmern können.\n\nIch weiß gar nicht, wie ich Euch für Eure Hilfe danken kann, {name}. Die Anerkennung von mir und den Verteidigern der Azurwacht ist Euch sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[9607] = { id = 9607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Herzen des Hasses", description = "{class}, sucht Euch sofort eine Gruppe und kundschaftet den Blutkessel im Inneren der Höllenfeuerzitadelle aus! Und ich meine heute noch Prinzesschen!\n\nUnsere magische Überwachung besagt, dass dort etwas Unnatürliches vor sich geht. Jedoch werden unsere weiteren arkanen Untersuchungen von einer großen Macht im Inneren abgeblockt. Das sagt schon alles!\n\nRechnet mit starkem Widerstand; keine andere Truppe, die wir hineingeschickt haben, ist je zurückgekehrt.\n\nGeht hinein, untersucht das gesamte Areal und meldet Euch dann beim Truppenkommandant!", sourceObjective = "Untersucht das gesamte Areal des Blutkessels und meldet Euch anschließend bei Truppenkommandant Danath Trollbann in der Ehrenfeste auf der Höllenfeuerhalbinsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[9608] = { id = 9608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of Rage" }
quests[9609] = { id = 9609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft Behüter Biggs", description = "Magtoor hat mir gesagt, dass in der Nähe ein Behüter gestrandet ist. Offensichtlich wurde die Karawane, die er von Dunkelhain ab begleitet hat, von Verirrten angegriffen. Wie es aussieht ist er der einzige Überlebende.\n\nEr ist irgendwo im Süden. Bitte, {class}, helft ihm.", sourceObjective = "Sucht Behüter Biggs in den Sümpfen des Elends.", sourceObjectiveStatus = "unverified-source-field" }
quests[9610] = { id = 9610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tränenteich", description = "Ich interessiere mich für die Geschichte von Azeroth und frage mich, ob Ihr mir helfen möchtet.\n\nIn der Nähe im Sumpf gibt es einen Platz von historischer Bedeutung, zu dem ich Euch gerne schicken möchte. Der Tränenteich liegt im Südosten. Man sagt, dass sich an seinem Ufer und in seinen Tiefen vergrabene Artefakte der Zivilisation der Atal'aitrolle befänden.\n\nAber seid vorsichtig, der Teich wird von Somnus, einem uralten grünen Drachen, und seinen Drachlingen sowie fleischfressenden Fischen bewacht!", sourceObjective = "Besorgt 5 Artefakte der Atal'ai und bringt sie zu Holaaru im Sicheren Hafen in den Sümpfen des Elends.", sourceObjectiveStatus = "unverified-source-field" }
quests[9611] = { id = 9611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azurmythosinsel" }
quests[9612] = { id = 9612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herzlichen Dank!", description = "Ihr habt mein Leben gerettet, {name}! Ich danke Euch von ganzem Herzen! Wärt Ihr nicht gewesen, hätte mich diese Bestie in Fetzen gerissen.\n\nWenn Ihr den Exarch bei der Azurwacht seht, erzählt ihm von Eurer Tat. Ich bin mir sicher, dass er diese Neuigkeit mit Freuden aufnehmen wird!", sourceObjective = "Sprecht mit Exarch Menelaous bei der Azurwacht.", completion = "Gut gemacht, {name}. Wirklich sehr, sehr gut! Ihr erweist Euch langsam als besonderer {race} - Ihr seid den anderen Euren Alters einen Schritt voraus. Nehmt dies als Belohnung!", sourceObjectiveStatus = "unverified-source-field" }
quests[9613] = { id = 9613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keannas Wille", description = "<Als Ihr das Schwert berührt, Hört Ihr eine weibliche Stimme, die Euch anspricht.>\n\nAu! Lasst das! Könnt Ihr nicht sehen, dass ich zerbrochen bin? Das tut weh!\n\nWie ich sehe, seid Ihr Karazhan nicht in die Falle gegangen. Dann müsst Ihr von Khadgar und dem Violetten Auge wissen.\n\nIhr müsst jemanden finden, der mich wieder zusammenfügen kann. Koren... er war einst unser Agent... er ist in der Nähe. Ich hoffe, dass Ihr zu den Guten gehört. Wenn ja, dann kann er uns helfen!", sourceObjective = "Die zertrümmerte Klinge, die ihr in Karazhan gefunden habt, möchte, dass Ihr Koren bittet, sie zu reparieren. Ihr müsst außerdem einen wohlwollenden Ruf beim Violetten Auge innehaben, um die Quest abzuschließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9614] = { id = 9614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Klinge zusammenfügen", description = "Diese Waffe wurde in so viele Stücke zerbrochen... sie wieder zusammenzufügen wird nicht einfach.\n\nIch brauche Khorium. Viel davon. Und einen Kristall der Leere sowie etwas Urfeuer.", sourceObjective = "Bringt 40 Khoriumbarren, 1 Kristall der Leere und 8 Urfeuer zu Koren in Karazhan.", sourceObjectiveStatus = "unverified-source-field" }
quests[9615] = { id = 9615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Klinge zusammenfügen", description = "Diese Waffe wurde in so viele Stücke zerbrochen... sie wieder zusammenzufügen wird nicht einfach.\n\nIch brauche Khorium. Viel davon. Und einen Kristall der Leere sowie etwas Urfeuer.", sourceObjective = "Bringt 40 Khoriumbarren, 1 Kristall der Leere und 8 Urfeuer zu Koren in Karazhan.", sourceObjectiveStatus = "unverified-source-field" }
quests[9616] = { id = 9616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Banditen!", description = "Es scheint sich um ein Kopfgeldverzeichnis zu handeln. Ihr könnt die Sprache der Blutelfen zwar nicht verstehen, aber Ihr bemerkt ein Bild, das einen toten Draenei darstellt, einen grinsenden Blutelfen, der sich über dessen Körper beugt, und ein Symbol, das Eurer Meinung nach für eine Art Währung der Blutelfen steht.\n\nSie haben es auf die Draenei abgesehen! Ihr müsst den Exarch darüber informieren.", sourceObjective = "Nehmt das Blutelfendokument zu Exarch Menelaous bei der Azurwacht.", progress = "Ja? Ich bin wirklich sehr beschäftigt, {name}.", completion = "Beim bartlosen, quadratischen Schädel von O'ros! Gut, dass Ihr das zu mir gebracht habt, {name}. Diese Blutelfen haben es... nun ja, auf Blut abgesehen. Velen wird davon sofort in Kenntnis gesetzt werden! Nehmt dies als Anerkennung.", sourceObjectiveStatus = "unverified-source-field" }
quests[9617] = { id = 9617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht die Weltenwanderer auf", description = "Leutnant Dämmerflucht bei der Zuflucht der Weltenwanderer hat nach einer Audienz mit allen fähigen Jägern verlangt. Es würde Euch zugutekommen, wenn Ihr sie aufsuchen würdet, {name}. Sie ist ein Stern der Erleuchtung für unsereins.\n\nDie Zuflucht der Weltenwanderer liegt südlich von Silbermond.", sourceObjective = "Sprecht mit Leutnant Dämmerflucht bei der Zuflucht der Weltenwanderer.", sourceObjectiveStatus = "unverified-source-field" }
quests[9618] = { id = 9618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überbringen der Berichte", description = "Eure Geschicklichkeit war äußerst beeindruckend. Es besteht kein Zweifel, ich kann Euch die Überbringung dieser Berichte an Zelanis anvertrauen.", sourceObjective = "Bringt Keltus Dunkellaubs Berichte zu Zelanis in Silbermond.", sourceObjectiveStatus = "unverified-source-field" }
quests[9619] = { id = 9619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschwörungsrune", description = "Der Leerstein offenbart Euch eine Vision von einem mehrstöckigen Gebäude, das von geisterhaften Figuren behaust wird. Die Szene wird schärfer und verschwimmt dann wieder, andere Gebäude kommen ins Bild, es scheint sich um den Ort Goldnebel zu handeln.\n\nHausdächer und Baumwipfel schwirren plötzlich vorbei, sie verraten Euch den Weg nach Goldnebel, der den Elrendar entlang nach Westen führt.\n\nVerwendet den Leerstein, sobald Ihr dort angekommen seid, nahe der Beschwörungsrune auf dem Hauptgebäude und bezwingt den heraufbeschworenen Leerwandler. Erst dann könnt Ihr zu Eurem Lehrer zurückkehren.Ihr erlernt:", sourceObjective = "Verwendet den Leerstein, um einen Leerwandler in Goldnebel zu beschwören. Bezwingt ihn und kehrt zu Talionia in Silbermond zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9620] = { id = 9620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das vermisste Vermessungsteam", description = "Als wir uns hier bei der Blutwacht langsam eingerichtet hatten, schickte ich Vermessungsteams aus, die zuverlässigere Karten der Insel erstellen sollten. Meistens kamen sie wieder unversehrt mit den von uns benötigten Angaben zurück, aber das Team, das ich nach Osten zu den Ruinen entsendet hatte, wird noch immer vermisst.\n\nIch mache mir Sorgen um sie, aber leider kann ich niemanden entbehren, um ein weiteres Team nach ihnen suchen zu lassen. Findet sie, {name}, und helft ihnen, so weit es geht, damit sie mit ihren gesammelten Informationen wieder zurückkehren können.", sourceObjective = "Herold Mikolaas möchte, dass Ihr das Vermessungsteam findet, das er zu den Ruinen von Loreth'Aran entsendet hatte, und dass Ihr dem Team so gut es geht zur Seite steht.", completion = "Auf dem Boden liegen überall die Körper der {race}, die dem Vermessungsteam angehörten - von Waffen der Naga durchbohrt. Ihr seht die verstreuten Überreste ihrer Vorräte und Vermessungsausrüstung, aber ihre Datenkristalle befinden sich nicht darunter.", sourceObjectiveStatus = "unverified-source-field" }
quests[9621] = { id = 9621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesandter zur Horde", description = "Unter unseren neuen möglichen Verbündeten regen sich Zweifel über unsere Fähigkeiten. Wie könnten wir ihnen helfen, wenn sie glauben, dass wir nicht einmal mit unseren Problemen zuhause fertigwerden?\n\nDas ändert alles. Wir lassen keine Zweifel an unserer Stärke zu. Wir werden der Horde als Ebenbürtige beitreten.\n\nBringt diesen Brief zu Sylvanas, Anführerin der Verlassenen. Sie war schon immer auf unserer Seite, aber die Nachricht von Dar'Khans Tod muss wie Musik in ihren Ohren klingen. Bereitet Euch auf eine lange Reise vor, {name}. Wenn alles gut geht, wird sie Euch nach Orgrimmar schicken.", sourceObjective = "Bringt den Brief von Lor'themar Theron zu Fürstin Sylvanas Windläufer in Unterstadt, der Hauptstadt der Verlassenen in Tirisfal.", progress = "Ah, ein Besucher aus Quel'Thalas! Welche Neuigkeiten bringt Ihr?", completion = "Dann ist es also geschehen. Der gemeine Verräter hat bekommen, was er verdient hat.\n\nIhr habt das selbst getan? Eine beeindruckende Tat, die beweist, dass Euer Volk immer noch würdig ist, {name}.\n\nWie ich sehe, hat Lor'themar weitere Nachrichten, die seine Beziehungen zu den Trollen und ihrem Kriegshäuptling deutlich verbessern werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9622] = { id = 9622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warnt vor der Gefahr", description = "Die Feste ist jetzt wieder sicher und schon bald werden sich meine Leute auf den Weg zurück zu ihrem Ahnenstammsitz machen. Die Prophezeiung wurde Wirklichkeit und für die Furbolgs der Tannenruhfeste beginnt eine neue Ära des Wohlstands.\n\nIch befürchte allerdings, dass die Dunkelheit für Eure eigenen Leute eine Bedrohung darstellt. Es gibt noch immer unbeantwortete Fragen - ungesehene Visionen aus der Prophezeiung.\n\nKehrt zu Euren Anführern zurück und erzählt ihnen von all dem, was Ihr hier erlebt habt.\n\nSolltet Ihr jemals die Hilfe der Tannenruhfeste benötigen, lasst es uns einfach wissen.", sourceObjective = "Sprecht mit Exarch Menelaous bei der Azurwacht.", completion = "Visionen sagt Ihr? Interessant... und diese Prophezeiung hat sich also bewahrheitet?\n\nIhr sagt jedoch, dass man den Kraftkern der Exodar gesehen hat? O'ros erschien auch in der Vision? Was kann das nur bedeuten?", sourceObjectiveStatus = "unverified-source-field" }
quests[9623] = { id = 9623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reifer werden", description = "Ihr habt in der Wildnis unserer neuen Heimat überlebt und Euch als etwas Besonderes unter den anderen hervorgetan. Ich glaube, dass Ihr nun reif genug seid, um die zu unterstützen, die an der Front der Blutmythosinsel kämpfen. Die Hand von Argus könnte <einen/eine> wie Euch brauchen.\n\nMeldet Euch bei Torallius dem Gruppenkommandanten. Ihr findet ihn außerhalb der Exodar bei dem Elekk. Gebt ihm diese Befehle, damit er Euch neue Aufträge auf der Blutmythosinsel erteilen kann.", sourceObjective = "Exarch Menelaous bei der Azurwacht hat Euch gebeten, die Befehle des Exarchen zu Torallius dem Gruppenkommandanten, der außerhalb der Exodar steht, zu bringen.", progress = "<Torallius rückt seine Augenklappe zurecht und sieht Euch an.>\n\nHaben wir der Hand von Argus nichts Besseres anzubieten?", completion = "<Torallius seufzt.>\n\nNun gut, lasst mich einen Blick auf diese Befehle werfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9624] = { id = 9624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieblingsleckerli", description = "Ich habe eine wundervolle Entdeckung gemacht, {class}. In den noch unberührten Gebieten dieser Insel wächst eine außergewöhnliche Frucht, die Sandbirne genannt wird. Man findet sie am Boden nahe der Bäume.\n\nIch habe sie zum Kuchenbacken verwendet, aber wenn ich nicht Acht gebe, kommen die Elekks angelaufen und stehlen mir das Obst. Ich hatte genug eingesammelt, um mit den Tieren teilen zu können, aber mein Vorrat ist aufgebraucht und nun herrscht wieder großes Verlangen nach Kuchen. Würdet Ihr mir mit dem Sammeln der Früchte helfen, damit ich eine weitere Charge Kuchen backen kann? Ich werde teilen, ich verspreche es!", sourceObjective = "Aonar bei Kessels Wegelager möchte, dass Ihr ihm 10 Sandbirnen bringt.", progress = "Man findet die Sandbirnen immer seltener, was natürlich weniger Kuchen und somit weniger Leckerli für die Elekks hier bedeutet. Konntet Ihr die benötigten Früchte auftreiben?", completion = "War das Auffinden der Früchte schwierig? Ich brauche mit jedem Mal länger.\n\nIch werde allmählich ganz damit aufhören müssen, da ich keine Zeit mehr dafür habe. Danke für das Sammeln der Birnen, {name}. Jetzt kann ich zumindest noch ein oder zwei Kuchen backen, bevor die Saison vorüber ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[9625] = { id = 9625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekks sind starker Tobak", description = "Ist er verrückt geworden? Wie kann er von mir erwarten, dass ich einen meiner wertvollen Lieblinge einem namenlosen <Jüngling/jungen Ding> wie Euch überlasse!\n\nLasst Euch etwas gesagt sein, Kindchen: Ihr werdet es nie zu einem von der Hand von Argus bringen! Ihr habt nicht das Zeug dazu!\n\nIch glaube, dieses Mal muss ich ihm seinen Willen lassen. Sprecht mit Vorkhan bei Kessels Wegelager auf der Blutmythosinsel. Folgt einfach der Straße von hier aus nach Norden und geht einfach nach Norden weiter, wenn sie abzweigt.", sourceObjective = "Sprecht mit Vorkhan dem Elekktreiber auf der Blutmythosinsel.", completion = "Naja, zumindest habt Ihr's bis hierher geschafft! Jetzt schicken wir Euch lieber an die Arbeit, bevor Ihr noch zertrampelt werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[9626] = { id = 9626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begegnung mit den Orcs", description = "Wie Ihr wisst, habe ich nichts von der Liebe zu meinem Heimatland oder seinem Volk verloren. Ich habe mit Zähnen und Klauen darum gekämpft, dass Silbermond am Verhandlungstisch einen Platz neben Unterstadt und Orgrimmar erhält.\n\nDies sollte sämtliche Gegenstimmen zum Schweigen bringen. Bringt diesen Brief zu Saurfang in Orgrimmar. Als Anführer der Orcs muss auch seine Meinung zu der Bitte der Sin'dorei gehört werden.\n\nIch habe den Brief als Zeichen meiner persönlichen Bekräftigung mit meinem Siegel versehen. Geht in den Nordwesten der Stadt und steigt auf dem Turm in den Zeppelin nach Durotar.", sourceObjective = "Fürstin Sylvanas Windläufer möchte, dass Ihr den Brief mit Sylvanas' Siegel zu Hochfürst Saurfang nach Orgrimmar, der Hauptstadt von Durotar, bringt.", progress = "Ihr seid weit gereist, um mich zu treffen. Was bringt Euch nach Orgrimmar?", completion = "<Saurfang beginnt, den Brief zu lesen.>\n\nSylvanas ist hartnäckig. Sie geht sogar so weit, einen Champion von Silbermond zu schicken... aber was soll das ändern?", sourceObjectiveStatus = "unverified-source-field" }
quests[9627] = { id = 9627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treue gegenüber der Horde", description = "Die Allianz hat schweren Verrat an Eurem Volk begangen. Ihr habt die darnassischen Angriffe und die Spione aus Eisenschmiede erfolgreich geschlagen. Jetzt habt ihr einen mächtigen Anführer der Geißel direkt vor Eurem Heim besiegt. Es gibt keine Zweifel mehr an Eurer Würdigkeit.\n\nEs ist offensichtlich, dass wir uns gegenseitig brauchen. Kehrt zu Lor'themar zurück. Sagt ihm, dass ich Eure Nachricht erhalten habe und zustimme.\n\n<Saurfang zerknüllt den Brief in seiner Hand.>\n\nWillkommen in der Horde, Elf.", sourceObjective = "Kehrt nach Silbermond zurück und erstattet Lor'themar Theron Bericht.", completion = "Eure Taten waren den Zielen unseres Volkes sehr dienlich.\n\nBereitet Euch auf große Veränderungen vor, {name}. Wir sind nun offiziell ein Teil der Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[9628] = { id = 9628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergung der Daten", description = "Es ist zu spät, um den Kartografen beim Abschluss ihrer Mission zu helfen, aber es scheint, als hätten sie die Angaben gesammelt, nach denen Herold Mikolaas gefragt hat. Der Kristall, der ihre Vermessungsdaten beinhaltet, befand sich nicht unter ihren durchwühlten Habseligkeiten, also muss er den Naga der Hasspranken in die Hände gefallen sein.\n\nIhr wisst, dass Herold Mikolaas sehr betrübt über den Verlust des Teams sein wird, aber auch, dass er die Vermessungsdaten gerne retten würde.", sourceObjective = "Erlangt den Vermessungsdatenkristall von den Hasspranken nahe der toten Kartografen wieder und bringt ihn zu Herold Mikolaas bei der Blutwacht.", progress = "Konntet Ihr herausfinden, was das Vermessungsteam von seiner Rückkehr abgehalten hat?", completion = "<Ihr erzählt Herold Mikolaas vom Schicksal des Vermessungsteams. Er nimmt den Kristall von Euch entgegen, aber schweigt für einen langen Augenblick.>\n\nEs waren gute Männer, {name}, sie wussten, dass ihre Mission gefährlich sein würde. Ich bin Euch dankbar für das Auffinden des Teams und die Wiederbeschaffung des Kristalls.\n\n\n\nWir haben bereits zu viele unserer Männer verloren, dabei hat unsere Mission gerade erst begonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9629] = { id = 9629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kurz geschnappt", description = "Die Murlocs der Schwarzschlammküste an der südwestlichen Küste sind merkwürdige Kreaturen. Oft verhalten sie sich nach keinem richtigen Verhaltensmuster und manchmal legen sie ein erstaunliches Organisationsgeschick an den Tag.\n\nIch verfolge ein paar Theorien, die belegen könnten, wie sie das zustande bringen. Bis vor Kurzem konnte ich das Ganze jedoch noch nicht untersuchen. Ich habe eine Methode entwickelt, die es mir ermöglichen wird, die für mich interessanten Murlocs im Auge zu behalten, ohne ihnen dadurch längerfristig zu schaden oder ihr natürliches Verhalten zu stören. Wenn Ihr mir bei der Anbringung der Sender behilflich sein wollt, werde ich Euch gerne für Eure Unterstützung bezahlen.", sourceObjective = "Morae bei der Blutwacht möchte, dass Ihr 6 Späher der Schwarzschlammküste mit einem Murlocsender 'markiert'.", progress = "Hat der Apparat funktioniert? Habt Ihr die Murlocs für meine Untersuchungen markiert?", completion = "Gut gemacht, {name}. Ich hatte befürchtet, dass der Sender beim Markieren beschädigt werden könnte, aber anscheinend ist ja alles wie geplant verlaufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9630] = { id = 9630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Medivhs Tagebuch", description = "Euer Name spricht sich herum, {name}. Ihr habt es nach Karazhan und wieder heraus geschafft - das ist mehr, als die meisten Sterblichen von sich behaupten können.\n\nIhr müsst mir einen ganz besonderen Gefallen tun. Im Rahmen unserer Forschungen hat das Violette Auge versucht, an Medivhs Tagebuch zu kommen.\n\nUnglücklicherweise kam keiner der Agenten, die wir hineingeschickt haben, wieder heraus. Wravien war der letzte, den wir geschickt haben. Sucht ihn und erkundigt Euch, ob es neue Anhaltspunkte zu diesem Tagebuch gibt.", sourceObjective = "Erzmagier Alturus am Gebirgspass der Totenwinde möchte, dass Ihr nach Karazhan geht und mit Wravien sprecht.", completion = "Welch unermesslicher Wert an Informationen... Ich könnte Jahre hier verbringen! Ich bin sicher, Dalaran wird das verstehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[9631] = { id = 9631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe unter Kollegen", description = "Es gibt da ein kleines Detail, das ich vergessen habe. Die Überreste von Medivhs Essenz in diesem kleinen Knochenfragment ist völlig ohne Leben, genauso wie Arcanagos'.\n\nEs gibt jedoch einen Weg, sie wieder zum Leben zu erwecken. Und ich weiß auch genau, wer uns dabei helfen kann.\n\nReist nach Area 52 und zeigt Kalynna Lathred das Knochenfragment. Sie wird wissen, was damit zu tun ist.", sourceObjective = "Bringt das verkohlte Knochenfragment zu Kalynna Lathred in Area 52 im Nethersturm.", progress = "Alturus hat Euch geschickt. Die Sterne haben von Eurer Ankunft gesprochen.", completion = "Alturus möchte einen ganzen Drachen von den Toten zurückholen? Keine leichte Aufgabe.\n\nLasst uns darüber reden, wie wir uns gegenseitig unterstützen können, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9632] = { id = 9632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Verbündete", description = "Herold Mikolaas hat bei der Sicherung der Blutwacht äußerst löbliche Arbeit geleistet, {class}, allerdings sind unsere Feinde zahlreich und unsere Ressourcen gering.\n\nUnsere Gegner kennen unsere Schwäche nur zu gut, aber sie haben dabei nicht an Eure Verbindung zu den Streitkräften der Allianz gedacht. Ich habe ein Vorstellungsschreiben für Auberdine vorbereitet, der nächstgelegenen Siedlung der Allianz, in dem ich ihnen eine Zusammenarbeit beim Kampf gegen unsere Feinde vorschlage. Nehmt das Schreiben an Euch und sucht Jägerin Kella Nachtbogen auf, sie befindet sich in der Nähe der Docks westlich der Exodar.", sourceObjective = "Bringt das Vorstellungsschreiben zu Jägerin Kella Nachtbogen auf die Azurmythosinsel.", progress = "Seid gegrüßt, {class}. Was habt Ihr da?", completion = "Ich kann Euch helfen, nach Auberdine zu kommen. Glücklicherweise ist es nur eine kurze Fahrt mit dem Schiff von hier!", sourceObjectiveStatus = "unverified-source-field" }
quests[9633] = { id = 9633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg nach Auberdine", description = "Wenn Ihr am Dock wartet, werdet Ihr das Schiff sehen, das aus Auberdine von der Dunkelküste hier ankommt. Sobald alle Passagiere von Bord gegangen sind, könnt Ihr einsteigen.\n\nDas Schiff wird nach einer kurzen Fahrt in Auberdine anlegen und Ihr werdet Euer Schreiben überbringen können.\n\nAm besten bringt Ihr es zu Thundris Windwirker, er ist ein alter Freund von mir und genießt überall hohes Ansehen.", sourceObjective = "Nehmt das Schiff in der Nähe von Jägerin Kella Nachtbogen nach Auberdine. Bringt das Vorstellungsschreiben zu Thundris Windwirker, sobald Ihr in Auberdine angekommen seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[9634] = { id = 9634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubtiere aus einer anderen Welt", description = "Eine Sache, die wir auf unseren Reisen gelernt haben, ist, dass man bei der Einführung von Wildtieren aus einer anderen Welt besonders vorsichtig sein muss. Als die Exodar abstürzte, hatte sie Exemplare verschiedenster Tierarten aus der Scherbenwelt an Bord, einschließlich eines insektenartigen Raubtiers, dem Felshetzer.\n\nBei dem Absturz starben einige der Tiere, aber viele andere überlebten und suchten in der Wildnis das Weite. Wenn wir sie nicht in Schach halten, werden sie hier auf den Inseln das natürliche Gleichgewicht von Jägern und Gejagten stören.\n\nIhr findet die Hetzer westlich von Kessels Wegelager, in der Nähe der Küste.", sourceObjective = "Tötet 10 junge Blutfelshetzer und kehrt danach zu Vorkhan dem Elekktreiber bei Kessels Wegelager auf der Blutmythosinsel zurück.", completion = "Gut gemacht, {name}. Der Felshetzerbestand wird zwar nur für einige Zeit begrenzt bleiben, aber es ist ein guter Anfang.", sourceObjectiveStatus = "unverified-source-field" }
